# ==============================================================================
# คลังข้อมูลกฎหมาย พ.ร.บ. และระเบียบปฏิบัติ พม. (Knowledge Base 2)
# ==============================================================================

LAW_CHILD_KNOWLEDGE = """
--- [คลังข้อมูลกฎหมาย และ พ.ร.บ. พม.] ---

 หมวดกฎหมายเด็กและเยาวชน

**พระราชบัญญัติความร่วมมือระหว่างประเทศในทางแพ่งเกี่ยวกับการละเมิดสิทธิควบคุมดูแลเด็ก พ.ศ. 2555**

มาตรา 1: พระราชบัญญัตินี้เรียกว่า "พระราชบัญญัติความร่วมมือระหว่างประเทศในทางแพ่งเกี่ยวกับการละเมิดสิทธิควบคุมดูแลเด็ก พ.ศ. 2555"

มาตรา 2: ให้ใช้บังคับเมื่อพ้นกำหนดเก้าสิบวันนับแต่วันประกาศในราชกิจจานุเบกษาเป็นต้นไป

มาตรา 3: บทนิยามศัพท์สำคัญ
    - "เด็ก" หมายความว่า บุคคลซึ่งมีอายุต่ำกว่าสิบหกปีบริบูรณ์
    - "สิทธิควบคุมดูแลเด็ก" หมายความว่า สิทธิเกี่ยวกับการดูแลความเป็นอยู่ของเด็ก และหมายความรวมถึงสิทธิกำหนดที่อยู่ของเด็ก ซึ่งสิทธิดังกล่าวอาจเกิดขึ้นได้โดยผลของกฎหมาย โดยคำสั่งของศาลหรือเจ้าหน้าที่ของรัฐ หรือเป็นผลจากความตกลงที่มีผลตามกฎหมาย
    - "สิทธิในการพบและเยี่ยมเยียนเด็ก" หมายความรวมถึงสิทธิในการนำเด็กออกไปจากถิ่นที่อยู่ปกติของเด็กไปยังสถานที่อื่นภายในระยะเวลาจำกัด
    - "ผู้ประสานงานกลาง" หมายความว่า อัยการสูงสุดหรือผู้ที่อัยการสูงสุดมอบหมายให้มีอำนาจหน้าที่ประสานงานในการให้ความช่วยเหลือตามพระราชบัญญัตินี้
    - "ศาล" หมายความว่า ศาลเยาวชนและครอบครัวกลาง
มาตรา 4: ให้นายกรัฐมนตรีและรัฐมนตรีว่าการกระทรวงการพัฒนาสังคมและความมั่นคงของมนุษย์รักษาการตามพระราชบัญญัตินี้ และให้มีอำนาจออกกฎกระทรวงหรือระเบียบเพื่อปฏิบัติการตามพระราชบัญญัตินี้
  
  [หมวด 1: ผู้ประสานงานกลาง]
มาตรา 5: ผู้ประสานงานกลางมีอำนาจหน้าที่ดังต่อไปนี้
    (1) รับคำร้องขอความช่วยเหลือจากผู้ร้องขอ
    (2) พิจารณาและวินิจฉัยว่าควรจะให้หรือขอความช่วยเหลือหรือไม่
    (3) ให้ความร่วมมือกับผู้ประสานงานกลางหรือเจ้าหน้าที่ผู้มีอำนาจของต่างประเทศ รวมทั้งติดตามและเร่งรัดเพื่อให้มีการส่งตัวเด็กกลับคืนโดยเร็วและเพื่อให้บรรลุวัตถุประสงค์อื่นตามพระราชบัญญัตินี้
    (4) สืบหาแหล่งที่อยู่ของเด็กซึ่งถูกพาตัวมาหรือถูกกักตัวตามพระราชบัญญัตินี้
    (5) ดำเนินการเพื่อให้มีการปกป้องเด็กมิให้ได้รับอันตราย หรือป้องกันการปฏิบัติที่ไม่เป็นธรรมต่อผู้มีส่วนได้เสียทุกฝ่าย
    (6) ดำเนินการเพื่อให้มีการส่งตัวเด็กกลับคืนโดยสมัครใจหรือเพื่อระงับข้อขัดแย้งอย่างสันติและเป็นธรรม
    (7) แลกเปลี่ยนข้อมูลเกี่ยวกับเด็ก
    (8) ให้ข้อมูลเกี่ยวกับกฎหมายของประเทศไทยในส่วนที่เกี่ยวกับการดำเนินการตามพระราชบัญญัตินี้
    (9) ดำเนินการเพื่อให้มีการส่งตัวเด็กกลับคืนหรือเพื่อให้การใช้สิทธิในการพบและเยี่ยมเยียนเด็กเป็นไปอย่างมีประสิทธิภาพ
    (10) จัดให้มีพนักงานอัยการ ทนายความ หรือที่ปรึกษากฎหมาย เพื่อให้มีการส่งตัวเด็กกลับคืนหรือเพื่อให้การใช้สิทธิในการพบและเยี่ยมเยียนเด็กเป็นไปอย่างมีประสิทธิภาพ
    (11) ดำเนินการอย่างอื่นเพื่อให้การให้หรือการขอความช่วยเหลือตามพระราชบัญญัตินี้บรรลุผล
    (การดำเนินการของผู้ประสานงานกลางต้องกระทำโดยรวดเร็ว โดยถือประโยชน์สูงสุดของเด็กเป็นสำคัญ และคำนึงถึงความเป็นไปได้ที่ศาลจะมีคำสั่งอนุญาตตามคำร้องขอหรือไม่ตามมาตรา 13)

  [หมวด 2: การให้ความช่วยเหลือแก่ต่างประเทศ]
  - ส่วนที่ 1 การขอความช่วยเหลือ:
มาตรา 6: ผู้มีสิทธิควบคุมดูแลเด็กอาจขอความช่วยเหลือให้ส่งตัวเด็กที่ถูกพาตัวมาหรือกักตัวไว้ในไทยกลับคืนสู่ถิ่นที่อยู่ปกติในต่างประเทศ โดยยื่นคำร้องขอต่อผู้ประสานงานกลาง ซึ่งต้องระบุ: 
        (1) หลักฐานแสดงตัวบุคคลของผู้ร้องขอ เด็ก และผู้พาตัว/กักตัวเด็ก 
        (2) วัน เดือน ปีเกิดของเด็ก 
        (3) เหตุผลที่สนับสนุนคำร้องขอ 
        (4) แหล่งที่อยู่ของเด็กและบุคคลที่เด็กไปอยู่ด้วย 
        (5) เอกสารหลักฐานอื่นตามที่กำหนด

มาตรา 7: การพิจารณาคำร้องขอของผู้ประสานงานกลาง หากมีรายละเอียดครบถ้วนให้ดำเนินการช่วยเหลือหรือยื่นคำร้องต่อศาล หากไม่เข้าเกณฑ์ให้แจ้งปฏิเสธพร้อมเหตุผล 
         หากเชื่อว่าเด็กอยู่ในรัฐอื่นที่เป็นภาคีอนุสัญญาฯ ให้ส่งคำร้องต่อไปยังผู้ประสานงานกลางของรัฐนั้นโดยเร็ว และอาจปฏิเสธคำร้องขอได้หากกระทบต่ออธิปไตย ความมั่นคง หรือสาธารณประโยชน์สำคัญของไทย

มาตรา 8: ผู้ร้องขออาจขอทบทวนคำวินิจฉัยของผู้ประสานงานกลางที่ปฏิเสธการให้ความช่วยเหลือต่อศาลได้ภายใน 30 วันนับแต่วันที่ได้รับแจ้งคำปฏิเสธ (คำวินิจฉัยชี้ขาดของศาลให้เป็นที่สุด)

มาตรา 9: การปฏิเสธคำร้องขอของผู้ประสานงานกลางไม่ตัดสิทธิของผู้ร้องขอที่จะยื่นคำร้องขอเพื่อใช้สิทธิของตนต่อศาลโดยตรง

มาตรา 10: การดำเนินการช่วยเหลือ 
     (1) ผบ.ตร. และปลัดกระทรวงมหาดไทย สืบหาแหล่งที่อยู่เด็กและแจ้งผลต่อผู้ประสานงานกลาง 
     (2) พนักงานอัยการมีอำนาจยื่นคำร้องขอต่อศาลให้มีคำสั่งส่งตัวเด็กกลับคืน 
     (3) พนักงานอัยการอาจยื่นคำร้องขอต่อศาลห้ามมิให้ผู้ใดย้ายเด็กไปจากแหล่งที่อยู่ 
     (4) หากเด็กอาจได้รับอันตราย พนักงานอัยการยื่นคำขอต่อศาลให้นำตัวเด็กส่งไปไว้ในความคุ้มครองดูแลของกระทรวงการพัฒนาสังคมและความมั่นคงของมนุษย์ (พม.)
  
มาตรา 11: ให้กระทรวงการพัฒนาสังคมและความมั่นคงของมนุษย์ (พม.) มีหน้าที่รับตัวเด็กตามมาตรา 10 (4) ไว้คุ้มครองดูแลจนกว่ากระบวนการส่งตัวกลับคืนจะเสร็จสิ้นหรือศาลสั่งเป็นอย่างอื่น 
          ได้แก่ (1) การตรวจสุขภาพกายและสุขภาพจิต พร้อมให้การรักษาเยียวยา (2) การจัดที่พักอาศัย ที่หลับนอน เครื่องนุ่งห่มที่เหมาะสม ถูกสุขลักษณะ และอาหารที่ถูกอนามัยและเพียงพอ
  
  - ส่วนที่ 3 ศาลและกระบวนพิจารณา:
มาตรา 12: ให้ศาลเยาวชนและครอบครัวกลางมีอำนาจพิจารณาพิพากษาคดีและมีคำสั่งตาม พ.ร.บ. นี้ (คำพิพากษาหรือคำสั่งของศาลให้เป็นที่สุด)

มาตรา 13: หลักเกณฑ์การพิจารณาสั่งส่งตัวเด็กกลับคืนของศาล
      (1) ยื่นคำร้องภายใน 1 ปีนับแต่วันที่ถูกพาตัวมาหรือกักตัวไว้: ให้ศาลสั่งให้ส่งตัวเด็กกลับคืนโดยเร็ว
      (2) ยื่นคำร้องพ้น 1 ปีขึ้นไป: ศาลจะสั่งให้ส่งตัวเด็กกลับคืนก็ได้ เว้นแต่เด็กได้ปรับตัวเข้ากับสภาพแวดล้อมใหม่แล้ว
      (3) หากเด็กออกไปจากประเทศไทยแล้ว ศาลอาจสั่งรอการพิจารณาหรือยกคำร้องขอก็ได้
      (4) เหตุที่ศาลอาจยกคำร้องขอส่งตัวเด็กกลับคืน:
          (ก) ผู้มีสิทธิไม่ได้ใช้สิทธิดูแลจริงในขณะเกิดเหตุ หรือได้ยินยอม/ยอมรับในภายหลัง
          (ข) การส่งกลับคืนอาจเป็นอันตรายต่อร่างกายหรือจิตใจของเด็กอย่างร้ายแรง หรือตกอยู่ในสภาวะอันไม่อาจทนได้
          (ค) เด็กคัดค้านการส่งตัวกลับคืน และศาลเห็นว่าเด็กมีอายุและวุฒิภาวะสมควรที่จะรับฟัง
          (ง) ขัดต่อหลักพื้นฐานของไทยเกี่ยวกับการคุ้มครองสิทธิมนุษยชนและเสรีภาพขั้นพื้นฐาน
          (จ) เด็กมีอายุครบ 16 ปีบริบูรณ์
มาตรา 14: หากศาลมิได้มีคำสั่งภายใน 6 สัปดาห์นับแต่วันรับคำร้อง ผู้ประสานงานกลางหรือพนักงานอัยการอาจขอทราบข้อเท็จจริงถึงความล่าช้าจากศาลได้

มาตรา 15: กรณีมีข้อพิพาทเกี่ยวกับสิทธิควบคุมดูแลเด็กด้วย หากศาลสั่งไม่ส่งตัวเด็กกลับคืนแล้ว จึงค่อยพิจารณาเรื่องสิทธิควบคุมดูแลเด็กต่อไป

มาตรา 16: ศาลอาจสั่งให้ผู้ร้องขอไปขอคำวินิจฉัยชี้ขาดจากศาลหรือองค์กรที่มีอำนาจในประเทศถิ่นที่อยู่ปกติของเด็กมาประกอบการพิจารณาได้

มาตรา 17: การร้องขอความช่วยเหลือขอใช้สิทธิในการพบและเยี่ยมเยียนเด็ก ให้นำบทบัญญัติว่าด้วยการส่งตัวเด็กกลับคืนมาใช้บังคับโดยอนุโลม

  [หมวด 3: การขอความช่วยเหลือไปยังต่างประเทศ]

มาตรา 18: ผู้ร้องขอในไทยที่ประสงค์จะขอความช่วยเหลือไปยังต่างประเทศเพื่อใช้สิทธิควบคุมดูแลเด็กและสิทธิพบเยี่ยมเยียน ให้เสนอเรื่องต่อผู้ประสานงานกลาง

  [หมวด 4: บทเบ็ดเตล็ด]
มาตรา 19: ให้ศาลรับฟังคำร้องขอและเอกสารหลักฐานที่ยื่นต่อศาลตามพระราชบัญญัตินี้

มาตรา 20: คำร้องขอหรือเอกสารอื่นที่ยื่นต่อผู้ประสานงานกลาง ต้องทำเป็นภาษาของผู้ร้องขอพร้อมคำแปลภาษาไทย หรือทำคำแปลเป็นภาษาอังกฤษ

มาตรา 21: ไม่ตัดสิทธิผู้มีสิทธิควบคุมดูแลเด็กและสิทธิพบเยี่ยมเยียนเด็กที่จะยื่นคำร้องขอโดยตรงต่อศาล

มาตรา 22: ห้ามเรียกประกัน หลักประกัน หรือมัดจำค่าฤชาธรรมเนียมและค่าใช้จ่ายในการดำเนินคดี

มาตรา 23: ให้สำนักงานอัยการสูงสุดรับผิดชอบค่าใช้จ่ายของผู้ประสานงานกลาง (เว้นแต่ค่าใช้จ่ายในการส่งตัวเด็กกลับคืน)

มาตรา 24: บรรดาค่าใช้จ่ายต่าง ๆ เกี่ยวกับการให้ความช่วยเหลือ ให้เป็นไปตามหลักเกณฑ์ที่กำหนดในกฎกระทรวง

มาตรา 25: ศาลมีอำนาจสั่งให้ผู้พาตัวเด็กมา กักตัวเด็ก หรือขัดขวางการใช้สิทธิพบเด็ก เป็นผู้รับผิดชอบค่าใช้จ่ายที่จำเป็น เช่น ค่าเดินทาง ค่าสืบหาแหล่งที่อยู่ ค่าทนายความ และค่าส่งตัวเด็กกลับคืน

**พระราชบัญญัติส่งเสริมการพัฒนาเด็กและเยาวชนแห่งชาติ พ.ศ. 2550 เเละที่เเก้ไขเพิ่มเติม **


มาตรา 1: พระราชบัญญัตินี้เรียกว่า "พระราชบัญญัติส่งเสริมการพัฒนาเด็กและเยาวชนแห่งชาติ พ.ศ. 2550"

มาตรา 2: พระราชบัญญัตินี้ให้ใช้บังคับเมื่อพ้นกำหนดเก้าสิบวันนับแต่วันประกาศในราชกิจจานุเบกษาเป็นต้นไป

มาตรา 3: ให้ยกเลิกพระราชบัญญัติส่งเสริมและประสานงานเยาวชนแห่งชาติ พ.ศ. 2521

มาตรา 4: ในพระราชบัญญัตินี้
    - "เด็ก" หมายความว่า บุคคลซึ่งมีอายุต่ำกว่าสิบแปดปีบริบูรณ์
    - "เยาวชน" หมายความว่า บุคคลซึ่งมีอายุตั้งแต่สิบแปดปีบริบูรณ์ถึงยี่สิบห้าปีบริบูรณ์
    - "คณะกรรมการ" หมายความว่า คณะกรรมการส่งเสริมการพัฒนาเด็กและเยาวชนแห่งชาติ
    - "คณะบริหาร" หมายความว่า คณะบริหารสภาเด็กและเยาวชนตำบล คณะบริหารสภาเด็กและเยาวชนเทศบาล คณะบริหารสภาเด็กและเยาวชนอำเภอ 
       คณะบริหารสภาเด็กและเยาวชนเขต คณะบริหารสภาเด็กและเยาวชนจังหวัด คณะบริหารสภาเด็กและเยาวชนกรุงเทพมหานคร และคณะบริหารสภาเด็กและเยาวชนแห่งประเทศไทย (แก้ไขเพิ่มเติมโดย พ.ร.บ. ฉบับที่ 2 พ.ศ. 2560)
    - "คณะบริหาร" (ต่อ): คณะบริหารสภาเด็กและเยาวชนเขต คณะบริหารสภาเด็กและเยาวชนจังหวัด คณะบริหารสภาเด็กและเยาวชนกรุงเทพมหานคร และคณะบริหารสภาเด็กและเยาวชนแห่งประเทศไทย
    - "สำนักงาน" หมายความว่า กรมกิจการเด็กและเยาวชน (แก้ไขเพิ่มเติมโดย พ.ร.บ. ฉบับที่ ๒ พ.ศ. ๒๕๖๐)
    - "ผู้อำนวยการ" หมายความว่า อธิบดีกรมกิจการเด็กและเยาวชน (แก้ไขเพิ่มเติมโดย พ.ร.บ. ฉบับที่ ๒ พ.ศ. ๒๕๖๐)
    - "รัฐมนตรี" หมายความว่า รัฐมนตรีผู้รักษาการตามพระราชบัญญัตินี้
มาตรา 5: ให้รัฐมนตรีว่าการกระทรวงการพัฒนาสังคมและความมั่นคงของมนุษย์รักษาการตามพระราชบัญญัตินี้ และให้มีอำนาจออกกฎกระทรวงและระเบียบเพื่อปฏิบัติการตามพระราชบัญญัตินี้ เมื่อได้ประกาศในราชกิจจานุเบกษาแล้วให้ใช้บังคับได้

  [หมวด 1: บททั่วไป]
มาตรา 6: ให้กระทรวงการพัฒนาสังคมและความมั่นคงของมนุษย์มีหน้าที่ในการพัฒนาเด็กและเยาวชน รวมทั้งแก้ไขปัญหาที่อาจมีผลกระทบในทางลบต่อเด็กและเยาวชน โดยมีหลักการ ดังต่อไปนี้
    (1) การพัฒนาเด็กและเยาวชน การบังคับใช้และการปฏิบัติตามบทบัญญัติใด ๆ แห่งพระราชบัญญัตินี้ หรือกฎหมายอื่นที่เกี่ยวข้องกับเด็กและเยาวชน ต้องคำนึงถึงประโยชน์สูงสุดของเด็กและเยาวชนเป็นอันดับแรก
    (2) เด็กและเยาวชนทุกคนมีสิทธิในการได้รับการศึกษา และได้รับการศึกษาขั้นพื้นฐานที่มีคุณภาพสูงสุดตามที่กำหนดไว้ในรัฐธรรมนูญ
    (3) เด็กพิการ เด็กที่มีข้อจำกัดทางการเรียนรู้ และเด็กที่มีความสามารถพิเศษ มีสิทธิในการได้รับการศึกษาที่รัฐจัดให้เป็นพิเศษที่เหมาะสมกับลักษณะเด็กประเภทนั้น ๆ
    (4) เด็กและเยาวชนมีสิทธิในการรับบริการทางการสาธารณสุขที่ได้มาตรฐานสูงสุดเท่าที่มีการให้บริการทางด้านนี้
    (5) เด็กและเยาวชนมีสิทธิในการเล่น มีเวลาพักผ่อน และเข้าร่วมกิจกรรมการละเล่นทางนันทนาการที่เหมาะสมตามวัยของเด็กและเยาวชน และการมีส่วนร่วมอย่างเสรีในทางวัฒนธรรมและศิลปะ
    - การดำเนินการตามวรรคหนึ่ง ให้กระทำโดยมีแนวทาง ดังต่อไปนี้:
      (1) ให้เด็กและเยาวชนมีความผูกพันต่อครอบครัว ภาคภูมิใจในความเป็นไทย มีวิถีชีวิตแบบประชาธิปไตย
      (2) ให้สามารถดำเนินชีวิตได้อย่างปลอดภัย รู้จักเคารพสิทธิและเสรีภาพของผู้อื่น รวมทั้งกฎหมาย กฎเกณฑ์ และกติกาในสังคม
      (3) ให้การสนับสนุนและส่งเสริมความร่วมมือทางการศึกษา ทั้งภายในประเทศและภายนอกประเทศ เพื่อให้เด็กและเยาวชนทุกคนสามารถเข้าถึงการศึกษาได้อย่างเหมาะสม
      (4) ให้การสนับสนุนและส่งเสริมการศึกษาเพื่อพัฒนาเด็กพิการ เด็กที่มีข้อจำกัดทางการเรียนรู้ และเด็กที่มีความสามารถพิเศษ ให้สามารถพึ่งตนเองได้ ให้มีคุณธรรม และมีคุณภาพชีวิตที่ดี สามารถประกอบอาชีพและดำรงชีวิตได้อย่างเป็นอิสระ
      (5) ให้มีสุขภาพพลานามัยที่สมบูรณ์แข็งแรง รู้จักการป้องกันตนเองจากโรคภัยและสิ่งเสพติด
      (6) ให้มีวุฒิภาวะทางอารมณ์ตามสมควรแก่วัย รวมทั้งมีคุณธรรมและจริยธรรม
      (7) ให้มีทักษะและเจตคติที่ดีต่อการทำงาน มีศักดิ์ศรีและภาคภูมิใจในการทำงานที่สุจริต
      (8) ให้รู้จักคิดอย่างมีเหตุผลและมุ่งมั่นพัฒนาตนเองอย่างต่อเนื่อง
      (9) ให้รู้จักช่วยเหลือผู้อื่นโดยมีจิตสำนึกในการให้และการเป็นอาาสมัคร รวมทั้งมีส่วนร่วมในการพัฒนาชุมชนและประเทศชาติ
      (10) ให้มีความรับผิดชอบต่อตนเอง ผู้อื่น และต่อส่วนรวม ตามสมควรแก่วัย
      (11) ให้สามารถแสดงความคิดเห็นหรือแสดงออกอย่างสอดคล้องกับความรู้ความสามารถที่พัฒนาไปตามวัยของเด็กและเยาวชน โดยเฉพาะเรื่องที่มีผลกระทบต่อเด็กและเยาวชน
      (12) ให้สามารถเข้าไปมีส่วนร่วมในกระบวนการยุติธรรมในเรื่องที่มีผลกระทบต่อเด็กและเยาวชนอย่างเหมาะสม ไม่ว่าจะโดยทางตรง หรือผ่านผู้แทนหรือองค์กรเพื่อเด็กและเยาวชน
มาตรา 7: ให้เด็กและเยาวชนทุกคนมีสิทธิได้รับการจดทะเบียนรับรองการเกิด การพัฒนา การยอมรับ การคุ้มครองและโอกาสในการมีส่วนร่วมตามที่บัญญัติในพระราชบัญญัต```python
      (2) ส่งเสริมการดำเนินชีวิตอย่างปลอดภัย เคารพสิทธิและเสรีภาพของผู้อื่น รวมถึงกฎหมายและกติกาในสังคม
      (3) สนับสนุนความร่วมมือทางการศึกษาทั้งในและต่างประเทศ เพื่อให้เด็กและเยาวชนเข้าถึงการศึกษาได้อย่างเหมาะสม
      (4) พัฒนาและส่งเสริมการศึกษาสำหรับเด็กพิการ เด็กที่มีข้อจำกัดทางการเรียนรู้ และเด็กที่มีความสามารถพิเศษ ให้สามารถพึ่งตนเองและประกอบอาชีพได้อย่างมีคุณภาพชีวิตที่ดี
      (5) เสริมสร้างสุขอนามัยและพลานามัยที่สมบูรณ์แข็งแรง รู้วิธีป้องกันตนเองจากโรคภัยและสารเสพติด
      (6) เสริมสร้างวุฒิภาวะทางอารมณ์ คุณธรรม และจริยธรรมที่เหมาะสมตามช่วงวัย
      (7) ปลูกฝังทักษะ เจตคติที่ดี และความภาคภูมิใจในการประกอบอาชีพสุจริต
      (8) ส่งเสริมกระบวนการคิดอย่างมีเหตุผลและการพัฒนาตนเองอย่างต่อเนื่อง
      (9) ปลูกฝังจิตสาธารณะ การเป็นอาสาสมัครช่วยเหลือผู้อื่น และการมีส่วนร่วมพัฒนาชุมชนและประเทศ
      (10) ปลูกฝังความรับผิดชอบต่อตนเอง ครอบครัว และสังคม
      (11) เปิดโอกาสให้แสดงความคิดเห็นและการแสดงออกตามวุฒิภาวะ โดยเฉพาะเรื่องที่มีผลกระทบต่อเด็กและเยาวชน
      (12) ส่งเสริมการมีส่วนร่วมในกระบวนการยุติธรรมในเรื่องที่เกี่ยวข้องกับเด็กและเยาวชนอย่างเหมาะสม ทั้งทางตรงหรือผ่านผู้แทน
  
มาตรา 7: สิทธิเด็กและเยาวชนทุกคนในการจดทะเบียนเกิด การพัฒนา การยอมรับ การคุ้มครอง และการมีส่วนร่วม โดยปราศจากการเลือกปฏิบัติอย่างไม่เป็นธรรม ไม่ว่าจะด้วยเหตุผลทางเพศ เชื้อชาติ ภาษา อายุ ความพิการ สถานะทางเศรษฐกิจ สังคม ความเชื่อ หรือภูมิหลังใดๆ
  
มาตรา 8: ให้กรมกิจการเด็กและเยาวชน หรือสำนักงาน พมจ. ร่วมมือกับองค์กรปกครองส่วนท้องถิ่น (อปท.) 
         ในการจัดทำแผนพัฒนาเด็กและเยาวชนระดับท้องถิ่นให้สอดคล้องกับแผนระดับชาติ โดยให้ อปท. จัดสรรงบประมาณรองรับ และเปิดโอกาสให้ภาคประชาชนและประชาสังคมในท้องถิ่นมีส่วนร่วม

มาตรา 9: เพื่อประโยชน์ในการพัฒนาเด็กและเยาวชน ให้หน่วยงานภาครัฐและภาคเอกชนที่เกี่ยวข้องให้ความร่วมมือ ส่งเสริม และสนับสนุนการดำเนินงานของสภาเด็กและเยาวชนอำเภอ สภาเด็กและเยาวชนจังหวัด สภาเด็กและเยาวชนกรุงเทพมหานคร และสภาเด็กและเยาวชนแห่งประเทศไทย

  [หมวด 2: คณะกรรมการส่งเสริมการพัฒนาเด็กและเยาวชนแห่งชาติ]
มาตรา 10: ให้มีคณะกรรมการส่งเสริมการพัฒนาเด็กและเยาวชนแห่งชาติ ประกอบด้วย
    (1) นายกรัฐมนตรีหรือรองนายกรัฐมนตรีซึ่งนายกรัฐมนตรีมอบหมาย เป็นประธานกรรมการ
    (2) รัฐมนตรีว่าการกระทรวงการพัฒนาสังคมและความมั่นคงของมนุษย์ เป็นรองประธานกรรมการ คนที่หนึ่ง
    (3) รัฐมนตรีว่าการกระทรวงศึกษาธิการ เป็นรองประธานกรรมการ คนที่สอง
    (4) กรรมการโดยตำแหน่ง ได้แก่ ปลัดกระทรวงกลาโหม, ปลัดกระทรวงการท่องเที่ยวและกีฬา, ปลัดกระทรวงการพัฒนาสังคมและความมั่นคงของมนุษย์
        , ปลัดกระทรวงดิจิทัลเพื่อเศรษฐกิจและสังคม, ปลัดกระทรวงมหาดไทย, ปลัดกระทรวงยุติธรรม, ปลัดกระทรวงแรงงาน, ปลัดกระทรวงวัฒนธรรม, ปลัดกระทรวงศึกษาธิการ, ปลัดกระทรวงสาธารณสุข
        , ผู้บัญชาการตำรวจแห่งชาติ, ปลัดกรุงเทพมหานคร, ประธานสภาองค์การพัฒนาเด็กและเยาวชน และประธานสภาเด็กและเยาวชนแห่งประเทศไทย
    (5) กรรมการผู้ทรงคุณวุฒิ ซึ่งนายกรัฐมนตรีแต่งตั้งจากนักจิตวิทยา นักสังคมสงเคราะห์ และบุคคลที่มีความรู้ ความสามารถ ความเชี่ยวชาญ และประสบการณ์ด้านการพัฒนาเด็กและเยาวชนเป็นที่ประจักษ์ 

มาตรา 9: กำหนดให้หน่วยงานภาครัฐและภาคเอกชนที่เกี่ยวข้อง มีหน้าที่ให้ความร่วมมือ ส่งเสริม และสนับสนุนการดำเนินงานของสภาเด็กและเยาวชนในทุกระดับ (ระดับอำเภอ จังหวัด กรุงเทพมหานคร และระดับประเทศ)

  [หมวด 2: คณะกรรมการส่งเสริมการพัฒนาเด็กและเยาวชนแห่งชาติ]
มาตรา 10: โครงสร้างคณะกรรมการส่งเสริมการพัฒนาเด็กและเยาวชนแห่งชาติ ประกอบด้วย:
    (1) นายกรัฐมนตรี หรือรองนายกรัฐมนตรีที่ได้รับมอบหมาย เป็นประธานกรรมการ
    (2) รัฐมนตรีว่าการกระทรวงการพัฒนาสังคมและความมั่นคงของมนุษย์ เป็นรองประธานคนที่ 1
    (3) รัฐมนตรีว่าการกระทรวงศึกษาธิการ เป็นรองประธานคนที่ 2
    (4) กรรมการโดยตำแหน่ง ได้แก่ ปลัดกระทรวงกลาโหม, ปลัดกระทรวงการท่องเที่ยวและกีฬา, ปลัดกระทรวงการพัฒนาสังคมและความมั่นคงของมนุษย์
        , ปลัดกระทรวงดิจิทัลเพื่อเศรษฐกิจและสังคม, ปลัดกระทรวงมหาดไทย, ปลัดกระทรวงยุติธรรม, ปลัดกระทรวงแรงงาน, ปลัดกระทรวงวัฒนธรรม, ปลัดกระทรวงศึกษาธิการ
        , ปลัดกระทรวงสาธารณสุข, ผู้บัญชาการตำรวจแห่งชาติ, ปลัดกรุงเทพมหานคร, ประธานสภาองค์การพัฒนาเด็กและเยาวชน และประธานสภาเด็กและเยาวชนแห่งประเทศไทย
    (5) กรรมการผู้ทรงคุณวุฒิ ไม่เกิน 5 คน ซึ่งนายกรัฐมนตรีแต่งตั้งจากภาคเอกชน (ด้านจิตวิทยา สังคมสงเคราะห์ หรือผู้มีประสบการณ์พัฒนาเด็กและเยาวชน)
    (6) ผู้แทนองค์กรปกครองส่วนท้องถิ่น จำนวน 3 คน
    (7) ผู้แทนเด็กและเยาวชนจากสภาเด็กและเยาวชนแห่งประเทศไทย จำนวน 2 คน (ชาย 1 คน และหญิง 1 คน)
    - ให้อธิบดีกรมกิจการเด็กและเยาวชน ทำหน้าที่เป็นกรรมการและเลขานุการ (พร้อมแต่งตั้งข้าราชการเป็นผู้ช่วยเลขานุการได้ไม่เกิน 2 คน)
    - หลักเกณฑ์และวิธีการแต่งตั้งกรรมการผู้ทรงคุณวุฒิ ให้เป็นไปตามระเบียบที่รัฐมนตรีกำหนด
มาตรา 11: คณะกรรมการ (กดยช.) มีอำนาจหน้าที่ ดังต่อไปนี้
    (1) เสนอนโยบายและแผนพัฒนาเด็กและเยาวชนแห่งชาติต่อคณะรัฐมนตรีเพื่อพิจารณาอนุมัติ โดยต้องคำนึงถึงพันธกรณีระหว่างประเทศที่ประเทศไทยมีอยู่ด้วย
    (2) เสนอแนวทางปรับปรุงกฎหมาย ระเบียบ และข้อบังคับเกี่ยวกับการส่งเสริมการพัฒนาเด็กและเยาวชนต่อคณะรัฐมนตรี
    (3) กำหนดระเบียบและวิธีปฏิบัติเกี่ยวกับการช่วยเหลือ ส่งเสริม สนับสนุน และพัฒนาคุณภาพชีวิตเด็กและเยาวชนแก่หน่วยงานของรัฐและเอกชนที่เกี่ยวข้อง เพื่อให้การช่วยเหลือทางวิชาการ การ```python
มาตรา 11: อำนาจหน้าที่ของคณะกรรมการส่งเสริมการพัฒนาเด็กและเยาวชนแห่งชาติ (กดยช.)
    (1) เสนอนโยบายและแผนพัฒนาเด็กและเยาวชนแห่งชาติต่อ ครม. เพื่อพิจารณาอนุมัติ โดยคำนึงถึงพันธกรณีระหว่างประเทศของไทย
    (2) เสนอแนะการปรับปรุงแก้ไขกฎหมาย ระเบียบ และข้อบังคับด้านการส่งเสริมและพัฒนาเด็กและเยาวชนต่อ ครม.
    (3) กำหนดระเบียบและแนวทางปฏิบัติเกี่ยวกับการสนับสนุน ช่วยเหลือ และพัฒนาคุณภาพชีวิตเด็กและเยาวชน แก่หน่วยงานรัฐและเอกชน (ทั้งด้านวิชาการ วิจัย เงินอุดหนุน และบริการต่างๆ อย่างทั่วถึงเป็นธรรม)
    (4) ส่งเสริมให้จัดสมัชชาการพัฒนาเด็กและเยาวชนแห่งชาติอย่างน้อยปีละ 1 ครั้ง เพื่อทบทวนสถานการณ์และพัฒนากระบวนการทำงาน
    (5) ประเมินผลการดำเนินงาน และจัดทำรายงานเสนอต่อ ครม. และรัฐสภา อย่างน้อยปีละ 1 ครั้ง
    (6) ปฏิบัติหน้าที่อื่นตามที่กฎหมายกำหนดหรือ ครม. มอบหมาย

มาตรา 12: คุณสมบัติและลักษณะต้องห้ามของกรรมการผู้ทรงคุณวุฒิ
    (1) สัญชาติไทย
    (2) อายุไม่ต่ำกว่า 30 ปีบริบูรณ์
    (3) ปฏิบัติงานในภาคเอกชนที่มีความรู้ ความเชี่ยวชาญ และประสบการณ์เด่นชัดด้านการพัฒนาเด็กและเยาวชน
    (4) ไม่เป็นบุคคลล้มละลาย คนไร้ความสามารถ หรือคนเสมือนไร้ความสามารถ
    (5) ไม่เคยได้รับโทษจำคุกโดยคำพิพากษาถึงที่สุด (เว้นแต่ความผิดลหุโทษหรือประมาท)
    (6) ไม่เคยถูกศาลสั่งให้ทรัพย์สินตกเป็นของแผ่นดินเนื่องจากร่ำรวยผิดปกติ
    (7) ไม่เคยถูกไล่ออก ปลดออก หรือเลิกจ้างเพราะทุจริตต่อหน้าที่
    (8) ไม่มีส่วนได้เสียในกิจการที่ทำร่วมกับกรมกิจการเด็กและเยาวชน

มาตรา 13: วาระการดำรงตำแหน่งของกรรมการผู้ทรงคุณวุฒิ
    - ดำรงตำแหน่งคราวละ 3 ปีนับแต่วันแต่งตั้ง
    - สามารถแต่งตั้งซ้ำได้ แต่ต้องไม่เกิน 2 วาระติดต่อกัน
    - หากครบวาระแล้วยังไม่มีการแต่งตั้งใหม่ ให้ปฏิบัติหน้าที่ต่อไปพลางก่อนจนกว่าจะมีผู้รับตำแหน่งใหม่
    * มาตรา 14: นอกจากพ้นจากตำแหน่งตามวาระ กรรมการผู้ทรงคุณวุฒิพ้นจากตำแหน่งเมื่อ
    (1) ตาย
    (2) ลาออก
    (3) นายกรัฐมนตรีให้ออกเพราะบกพร่องต่อหน้าที่ มีความประพฤติเสื่อมเสีย หรือหย่อนความสามารถ
    (4) ขาดคุณสมบัติหรือมีลักษณะต้องห้ามตามมาตรา 12

มาตรา 14/1: ผู้แทนเด็กและเยาวชนในคณะกรรมการส่งเสริมการพัฒนาเด็กและเยาวชนแห่งชาติ ตามมาตรา 10 (7) พ้นจากตำแหน่งเมื่อ
    (1) มีอายุเกินยี่สิบห้าปี
    (2) พ้นจากการเป็นผู้แทนของสภาเด็กและเยาวชนแห่งประเทศไทย

มาตรา 15: ในกรณีที่กรรมการผู้ทรงคุณวุฒิพ้นจากตำแหน่งก่อนวาระ ให้ผู้ได้รับแต่งตั้งดำรงตำแหน่งแทนอยู่ในตำแหน่งเท่ากับวาระที่เหลืออยู่ของผู้ซึ่งตนแทน

มาตรา 16: ให้นำความในมาตรา 13 มาตรา 14 (1) และ (2) และมาตรา 15 มาใช้บังคับแก่การดำรงตำแหน่งของกรรมการตามมาตรา 10 (6) และ (7) โดยอนุโลม
มาตรา 17: การประชุมของคณะกรรมการ ต้องมีกรรมการมาประชุมไม่น้อยกว่ากึ่งหนึ่งของจำนวนกรรมการทั้งหมด จึงจะเป็นองค์ประชุม
    - กรณีประธานไม่อยู่หรือไม่สามารถปฏิบัติหน้าที่ได้ ให้รองประธานคนที่หนึ่งเป็นประธาน หากรองประธานคนที่หนึ่งไม่อยู่หรือไม่สามารถปฏิบัติหน้าที่ได้ ให้รองประธานคนที่สองเป็นประธาน หากทั้งสองคนไม่อยู่หรือไม่สามารถปฏิบัติหน้าที่ได้ ให้กรรมการที่มาประชุมเลือกกรรมการคนหนึ่งขึ้นทำหน้าที่แทน
    - การวินิจฉัยชี้ขาดให้ถือเสียงข้างมาก กรรมการคนหนึ่งมีหนึ่งเสียงในการลงคะแนน ถ้าคะแนนเสียงเท่ากัน ให้ประธานในที่ประชุมออกเสียงเพิ่มขึ้นอีกเสียงหนึ่งเป็นเสียงชี้ขาด
    - ให้มีการประชุมคณะกรรมการอย่างน้อยปีละสี่ครั้ง

มาตรา 18: คณะกรรมการมีอำนาจแต่งตั้งคณะอนุกรรมการหรือคณะทำงาน เพื่อพิจารณาหรือปฏิบัติการตามที่คณะกรรมการมอบหมาย และมีอำนาจแต่งตั้งที่ปรึกษาคณะบริหารสภาเด็กและเยาวชนแห่งประเทศไทยตามที่สภาเด็กและเยาวชนแห่งประเทศไทยเป็นผู้เสนอ (แก้ไขเพิ่มเติมโดย พ.ร.บ. ฉบับที่ ๒ พ.ศ. ๒๕๖๐)
    - ให้นำความในมาตรา 17 มาใช้บังคับแก่การประชุมของคณะอนุกรรมการและคณะทำงานโดยอนุโลม

มาตรา 19: ให้สำนักงานมีอำนาจหน้าที่ดำเนินการส่งเสริมและพัฒนาคุณภาพชีวิตเด็กและเยาวชน และรับผิดชอบงานธุรการและวิชาการของคณะกรรมการ รวมทั้งให้มีอำนาจหน้าที่ดังต่อไปนี้
    (1) จัดทำนโยบายและแผนพัฒนาเด็กและเยาวชนแห่งชาติเสนอต่อคณะกรรมการ
    (2) กำหนดแผนพัฒนาเด็กและเยาวชนในด้านต่าง ๆ ให้สอดคล้องกับนโยบายและแผนพัฒนาเด็กและเยาวชนแห่งชาติ และกำหนดแนวทางปฏิบัติตามนโยบายและแผนดังกล่าว ตลอดจนการประสานงาน ติดตาม และประเมินผล ทั้งในส่วนของรัฐและเอกชนให้มีการปฏิบัติงานตามนโยบายเด็กและเยาวชนแห่งชาติ
    (3) พัฒนาศักยภาพของบุคลากรด้านเด็กและเยาวชน ตลอดจนส่งเสริม สนับสนุน และร่วมมือกับเอกชนในการพัฒนาศักยภาพบุคลากรดังกล่าว
    (4) ศึกษาวิจัยหรือสนับสนุนให้มีการศึกษาวิจัยเกี่ยวกับการพัฒนาเด็กและเยาวชน
    (5) สำรวจ ศึกษา รวบรวมข้อมูล วิเคราะห์ ติดตาม และประเมินผลเกี่ยวกับสิทธิประโยชน์ของเด็กและเยาวชนตามอนุสัญญาว่าด้วยสิทธิเด็ก 
        และความตกลงระหว่างประเทศที่ประเทศไทยเป็นภาคี ตลอดจนกฎหมายภายในประเทศ เพื่อจัดทำระบบฐานข้อมูลและรวบรวมข้อคิดเห็นของเด็กและเยาวชน รวมทั้งจัดทำรายงานเพื่อเป็นแนวนโยบายในการพัฒนาเด็กและเยาวชนต่อไป
    (6) สนับสนุนและประสานงานกับหน่วยงานทั้งในประเทศและต่างประเทศเพื่อร่วมมือกันพัฒนาเด็กและเยาวชน รวมทั้งส่งเสริมการดำเนินกิจการสภาเด็กและเยาวชนในทุกระดับ
    (7) ส่งเสริมสื่อมวลชนและสถานศึกษาในการจัดกระบวนการเรียนรู้เพื่อสร้างจิตสำนึกในการให้และการอาสาสมัครให้แก่เด็กและเยาวชน
    (8) เป็นศูนย์กลางในการประสานงาน เผยแพร่ และประชาสัมพันธ์งานและกิจการเกี่ยวกับการพัฒนาเด็กและเยาวชน
    (9) ศึกษา วิเคราะห์ และวางแผนการงบประมาณและค่าใช้จ่าย เพื่อการพัฒนาเด็กและเยาวชน โดยร่วมกับหน่วยงานอื่น รวมทั้งพิจารณาจัดสรรเงินอุดหนุนให้แก่องค์กรเอกชนหรือองค์กรชุมชนตามมาตรา 42
    (10) ดำเนินการจัดงานสมัชชาเด็กและเยาวชนแห่งชาติร่วมกับสภาเด็กและเยาวชนแห่งประเทศไทยอย่างน้อยปีละครั้ง เพื่อเป็นเวทีแลกเปลี่ยนเรียนรู้สำหรับเด็กและเยาวชนในด้านต่าง ๆ
    (11) ปฏิบัติการอื่นใดตามที่กฎหมายกำหนด ตามมติคณะกรรมการ หรือตามที่คณะรัฐมนตรีมอบหมาย

มาตรา 20: ให้สำนักงานจัดทำรายงานการพัฒนาเด็กและเยาวชนเสนอคณะกรรมการ เพื่อพิจารณาเสนอคณะรัฐมนตรีอย่างน้อยปีละครั้ง โดยมีสาระสำคัญ ดังต่อไปนี้
    (1) การใช้งบประมาณเพื่อการพัฒนาเด็กและเยาวชน
    (2) ผลการดำเนินงานของสภาเด็กและเยาวชนแห่งประเทศไทย
    (3) สภาพการณ์และแนวโน้มของ```python
มาตรา 19: อำนาจหน้าที่ของสำนักงาน (กรมกิจการเด็กและเยาวชน) ในการดำเนินงานส่งเสริมและพัฒนาคุณภาพชีวิตเด็กและเยาวชน และรับผิดชอบงานธุรการและวิชาการของคณะกรรมการ
    (1) จัดทำนโยบายและแผนพัฒนาเด็กและเยาวชนแห่งชาติเสนอต่อคณะกรรมการ
    (2) กำหนดแผนปฏิบัติการ แนวทางขับเคลื่อน ประสานงาน ติดตาม และประเมินผลการดำเนินงานตามนโยบายทั้งภาครัฐและภาคเอกชน
    (3) พัฒนาศักยภาพของบุคลากรด้านเด็กและเยาวชน ร่วมกับภาคเอกชน
    (4) ศึกษาวิจัยหรือสนับสนุนงานวิจัยที่เกี่ยวข้องกับการพัฒนาเด็กและเยาวชน
    (5) สำรวจ ศึกษา รวบรวมข้อมูล วิเคราะห์ ติดตาม และประเมินผลเกี่ยวกับสิทธิประโยชน์ตามอนุสัญญาว่าด้วยสิทธิเด็ก พันธกรณีระหว่างประเทศ และกฎหมายภายในประเทศ จัดทำระบบฐานข้อมูลและรายงานเชิงนโยบาย
    (6) ประสานความร่วมมือกับหน่วยงานทั้งในและต่างประเทศ รวมทั้งส่งเสริมกิจการสภาเด็กและเยาวชนทุกระดับ
    (7) ส่งเสริมสื่อมวลชนและสถานศึกษาจัดกระบวนการเรียนรู้เพื่อสร้างจิตสำนึกสาธารณะและการเป็นอาสาสมัคร
    (8) เป็นศูนย์กลางประสานงาน เผยแพร่ และประชาสัมพันธ์งานด้านการพัฒนาเด็กและเยาวชน
    (9) วิเคราะห์ วางแผนงบประมาณ และพิจารณาจัดสรรเงินอุดหนุนแก่องค์กรเอกชนและองค์กรชุมชนตามมาตรา 42
    (10) ร่วมกับสภาเด็กและเยาวชนแห่งประเทศไทยจัดสมัชชาเด็กและเยาวชนแห่งชาติอย่างน้อยปีละ 1 ครั้ง
    (11) ปฏิบัติการอื่นตามที่กฎหมาย คณะกรรมการ หรือคณะรัฐมนตรีมอบหมาย

มาตรา 20: ให้สำนักงานจัดทำรายงานการพัฒนาเด็กและเยาวชนเสนอต่อคณะกรรมการ เพื่อเสนอต่อคณะรัฐมนตรีอย่างน้อยปีละหนึ่งครั้ง โดยมีสาระสำคัญเกี่ยวกับ:
    (1) การใช้งบประมาณเพื่อการพัฒนาเด็กและเยาวชน
    (2) ผลการดำเนินงานของสภาเด็กและเยาวชนแห่งประเทศไทย
    (3) สภาพการณ์และแนวโน้มของปัญหาเด็กและเยาวชน
    (4) ผลการดำเนินงาน ปัญหา และอุปสรรคในการแก้ไขปัญหาการพัฒนาเด็กและเยาวชน  ตลอดจนปัญหาและอุปสรรคจากการดําเนินงาน
    (5) แนวทางในการแก้ไขปัญหาและการพัฒนาเด็กและเยาวชน

มาตรา 21: เพื่อปฏิบัติการให้เป็นไปตามพระราชบัญญัตินี้ คณะกรรมการ คณะอนุกรรมการ หรือสำนักงาน อาจเชิญบุคคลใดมาให้ข้อเท็จจริง คำอธิบาย คำแนะนำ หรือความเห็นทางวิชาการได้เมื่อเห็นสมควร และอาจขอความร่วมมือจากบุคคลใดเพื่อให้ได้มาซึ่งข้อเท็จจริงหรือเพื่อสำรวจกิจการใดที่อาจมีผลกระทบต่อเด็กและเยาวชนได้

  [หมวด 3: มาตรการส่งเสริมการดำเนินงานเพื่อการพัฒนาเด็กและเยาวชน]
  [ส่วนที่ 1: สภาเด็กและเยาวชน]

มาตรา 22: ให้องค์การบริหารส่วนตำบล เทศบาล โดยคำแนะนำของหัวหน้าบ้านพักเด็กและครอบครัวในแต่ละจังหวัด จัดให้มีสภาเด็กและเยาวชนตำบล สภาเด็กและเยาวชนเทศบาล แล้วแต่กรณี 
          ซึ่งสมาชิกประกอบด้วยเด็กและเยาวชนที่อยู่ในเขตพื้นที่องค์การบริหารส่วนตำบลหรือเทศบาลนั้น (แก้ไขเพิ่มเติมโดย พ.ร.บ. ฉบับที่ 2 พ.ศ. 2560)
    - ให้มีคณะบริหารสภาเด็กและเยาวชนตำบลหรือคณะบริหารสภาเด็กและเยาวชนเทศบาล ประกอบด้วยประธานสภาหนึ่งคน และผู้บริหารอีกไม่เกินยี่สิบคน 
      ซึ่งคัดเลือกกันเองจากสมาชิกสภาเด็กและเยาวชนตำบล หรือสมาชิกสภาเด็กและเยาวชนเทศบาล แล้วแต่กรณี โดยคำนึงถึงผู้พิการและผู้ด้อยโอกาส 
      ให้มีหน้าที่บริหารงานทั่วไปของสภาเด็กและเยาวชน และปรึกษาหารือร่วมกันเพื่อกำหนดแนวทางในการจัดกิจกรรมการพัฒนาเด็กและเยาวชนในเขตพื้นที่ รวมทั้งดำเนินการอื่นใดที่จำเป็นเพื่อให้บรรลุวัตถุประสงค์ของพระราชบัญญัตินี้
    - ให้นายอำเภอ เป็นที่ปรึกษาคณะบริหารสภาเด็กและเยาวชนตำบลหรือคณะบริหารสภาเด็กและเยาวชนเทศบาล และให้แต่งตั้งที่ปรึกษาคณะบริหารสภาเด็กและเยาวชนตำบลหรือคณะบริหารสภาเด็กและเยาวชนเทศบาล 
      จากนายกองค์การบริหารส่วนตำบล นายกเทศมนตรี ปลัดองค์การบริหารส่วนตำบล ปลัดเทศบาล แล้วแต่กรณี ผู้แทนสำนักงานพัฒนาสังคมและความมั่นคงของมนุษย์จังหวัด ผู้แทนบ้านพักเด็กและครอบครัวในแต่ละจังหวัด 
      ผู้แทนสำนักงานส่งเสริมการศึกษานอกระบบและการศึกษาตามอัธยาศัย ผู้แทนสถานศึกษา ผู้แทนหน่วยงานของรัฐหรือเจ้าหน้าที่ของรัฐที่เกี่ยวข้องกับการส่งเสริมการพัฒนาเด็กและเยาวชนที่ตั้งอยู่ในเขตพื้นที่องค์การบริหารส่วนตำบลหรือเทศบาลนั้น และผู้แทนองค์กรภาคประชาสังคมที่มีกิจกรรมหรือผลงานเกี่ยวกับ
    การพัฒนาเด็กและเยาวชน ทั้งนี้ ให้เป็นไปตามที่คณะบริหารสภาเด็กและเยาวชนตำบลหรือคณะบริหารสภาเด็กและเยาวชนเทศบาลเสนอ

มาตรา 23: สภาเด็กและเยาวชนตำบลและสภาเด็กและเยาวชนเทศบาล มีอำนาจหน้าที่ดังต่อไปนี้ (แก้ไขเพิ่มเติมโดย พ.ร.บ. ฉบับที่ 2 พ.ศ. 2560)
    (1) ประสานงานระหว่างสภาเด็กและเยาวชนตำบล สภาเด็กและเยาวชนเทศบาล สภาเด็กและเยาวชนอำเภอ เพื่อแลกเปลี่ยนความรู้และประสบการณ์ในด้านต่าง ๆ ของเด็กและเยาวชน
    (2) ส่งเสริม สนับสนุน และเป็นศูนย์กลางการเรียนรู้ด้านวิชาการ การศึกษา สุขภาพ กีฬา อาชีพ และวัฒนธรรมในท้องถิ่นของเด็กและเยาวชน
    (3) ส่งเสริม สนับสนุน ให้เด็กและเยาวชนได้แสดงความคิดเห็นหรือแสดงออกอย่างสอดคล้องกับความรู้ความสามารถที่พัฒนาไปตามวัยของเด็กหรือเยาวชน โดยเฉพาะเรื่องที่มีผลกระทบต่อเด็กและเยาวชน
    (4) จัดกิจกรรมต่าง ๆ เพื่อส่งเสริมและพัฒนาเด็กและเยาวชนในท้องถิ่นให้มีความรู้ความสามารถ รวมทั้งคุณธรรมและจริยธรรม
    (5) รวบรวมข้อมูล ข้อเสนอแนะ หรือประเมินเรื่องที่มีผลกระทบต่อเด็กและเยาวชนในเขตพื้นที่ เพื่อส่งต่อข้อมูลดังกล่าวให้กับสภาเด็กและเยาวชนอำเภอ
    (6) เสนอความเห็นต่อหน่วยงานที่เกี่ยวข้องกับกิจกรรมการส่งเสริมและพัฒนาเด็กและเยาวชน รวมทั้งการแก้ไขปัญหาที่มีผลกระทบต่อเด็กและเยาวชนในเขตพื้นที่
    (7) เสนอแนะและให้ความเห็นต่อสภาเด็กและเยาวชนอำเภอ เกี่ยวกับการส่งเสริมและพัฒนาเด็กและเยาวชนในท้องถิ่น
    (8) เสนอความเห็นต่อคณะกรรมการเกี่ยวกับการปฏิบัติงานของหน่วยงานของรัฐ และองค์กรเอกชนหรือองค์กรชุมชนที่เกี่ยวข้องกับเด็กและเยาวชนในเขตพื้นที่
    (9) ออกข้อบังคับเกี่ยวกับการประชุมและการดำเนินงานตามอำนาจหน้าที่ โดยให้คณะบริหารสภาเด็กและเยาวชนตำบลหรือคณะบริหารสภาเด็กและเยาวชนเทศบาล แล้วแต่กรณี เป็นผู้เสนอ ทั้งนี้ ให้สอดคล้องกับข้อบังคับของสภาเด็กและเยาวชนแห่งประเทศไทย

มาตรา 24: ให้มีสภาเด็กและเยาวชนอำเภอ ซึ่งสมาชิกประกอบด้วยคณะบริหารสภาเด็กและเยาวชนตำบล และคณะบริหารสภาเด็กและเยาวชนเทศบาล ที่อยู่ในเขตพื้นที่อำเภอนั้น (แก้ไขเพิ่มเติมโดย พ.ร.บ. ฉบับที่ 2 พ.ศ. 2560)
    - ให้มีสภาเด็กและเยาวชนเขต ในกรุงเทพมหานคร ซึ่งสมาชิกประกอบด้วยเด็กและเยาวชนที่อยู่ในเขตพื้นที่กรุงเทพมหานครแต่ละเขตนั้น
    - ให้มีคณะบริหารสภาเด็กและเยาวชนอำเภอและคณะบริหารสภาเด็กและเยาวชนเขต ประกอบด้วยประธานสภาหนึ่งคน และผู้บริหารอีกไม่เกินยี่สิบคน ซึ่งคัดเลือกกันเองจากสมาชิกสภาเด็กและเยาวชนอำเภอหรือสมาชิกสภาเด็กและเยาวชนเขต แล้วแต่กรณี โดยคำนึงถึงผู้พิการและ

ผู้ด้อยโอกาส ให้มีหน้าที่บริหารงานทั่วไปของสภาเด็กและเยาวชน และปรึกษาหารือร่วมกันเพื่อกำหนดแนวทางในการจัดกิจกรรมการพัฒนาเด็กและเยาวชนในเขตพื้นที่ รวมทั้งดำเนินการอื่นใดที่จำเป็นเพื่อให้บรรลุวัตถุประสงค์ของพระราชบัญญัตินี้
    ให้นายอําเภอหรือผู้อํานวยการเขต เป็นที่ปรึกษาคณะบริหารสภาเด็กและเยาวชน
อําเภอหรือคณะบริหารสภาเด็กและเยาวชนเขต แล้วแต่กรณี และให้แต่งตั้งที่ปรึกษาคณะบริหาร
สภาเด็กและเยาวชนอําเภอหรือคณะบริหารสภาเด็กและเยาวชนเขต แล้วแต่กรณี จากพัฒนาสังคม
และความมั่นคงของมนุษย์จังหวัด หัวหน้าบ้านพักเด็กและครอบครัวในแต่ละจังหวัด ผู้แทนสํานักงาน
ส่งเสริมการศึกษานอกระบบและการศึกษาตามอัธยาศัย ผู้แทนสถานศึกษา ผู้แทนหน่วยงานของรัฐ
หรือเจ้าหน้าที่ของรัฐที่เกี่ยวข้องกับการส่งเสริมการพัฒนาเด็กและเยาวชนที่ตั้งอยู่ในเขตพื้นที่อําเภอ
หรือเขตในกรุงเทพมหานคร และผู้แทนองค์กรภาคประชาสังคมที่มีกิจกรรมหรือผลงานเกี่ยวกับการ
พัฒนาเด็กและเยาวชน ทั้งนี้ ให้เป็นไปตามที่คณะบริหารสภาเด็กและเยาวชนอําเภอหรือคณะบริหาร
สภาเด็กและเยาวชนเขตเสนอ

มาตรา 25: ให้สภาเด็กและเยาวชนอำเภอและสภาเด็กและเยาวชนเขต มีอำนาจหน้าที่ดังต่อไปนี้ (แก้ไขเพิ่มเติมโดย พ.ร.บ. ฉบับที่ ๒ พ.ศ. ๒๕๖๐)
    (1) ประสานงานระหว่างสภาเด็กและเยาวชนอำเภอ สภาเด็กและเยาวชนเขต สภาเด็กและเยาวชนจังหวัด และสภาเด็กและเยาวชนกรุงเทพมหานคร เพื่อแลกเปลี่ยนความรู้และประสบการณ์ในด้านต่าง ๆ ของเด็กและเยาวชน
    (2) ส่งเสริม สนับสนุน และเป็นศูนย์กลางการเรียนรู้ด้านวิชาการ การศึกษา สุขภาพ กีฬา อาชีพ และวัฒนธรรมในท้องถิ่นของเด็กและเยาวชน
    (3) ส่งเสริม สนับสนุน ให้เด็กและเยาวชนได้แสดงความคิดเห็นหรือแสดงออกอย่างสอดคล้องกับความรู้ความสามารถที่พัฒนาไปตามวัยของเด็กหรือเยาวชน โดยเฉพาะเรื่องที่มีผลกระทบต่อเด็กและเยาวชน
    (4) จัดกิจกรรมต่าง ๆ เพื่อส่งเสริมและพัฒนาเด็กและเยาวชนในท้องถิ่นให้มีความรู้ความสามารถ รวมทั้งคุณธรรมและจริยธรรม
    (5) รวบรวมข้อมูล ข้อเสนอแนะ หรือประเมินเรื่องที่มีผลกระทบต่อเด็กและเยาวชนในเขตพื้นที่ เพื่อส่งต่อข้อมูลดังกล่าวให้กับสภาเด็กและเยาวชนจังหวัดหรือสภาเด็กและเยาวชนกรุงเทพมหานคร แล้วแต่กรณี
    (6) เสนอความเห็นต่อหน่วยงานที่เกี่ยวข้องกับกิจกรรมการส่งเสริมและพัฒนาเด็กและเยาวชน รวมทั้งการแก้ไขปัญหาที่มีผลกระทบต่อเด็กและเยาวชนในเขตพื้นที่
    (7) เสนอแนะและให้ความเห็นต่อสภาเด็กและเยาวชนจังหวัด สภาเด็กและเยาวชนกรุงเทพมหานคร เกี่ยวกับการส่งเสริมและพัฒนาเด็กและเยาวชนในท้องถิ่น
    (8) เสนอความเห็นต่อคณะกรรมการเกี่ยวกับการปฏิบัติงานของหน่วยงานของรัฐ และองค์กรเอกชนหรือองค์กรชุมชนที่เกี่ยวข้องกับเด็กและเยาวชนในเขตพื้นที่
    (๙) ออกข้อบังคับเกี่ยวกับการประชุมและการดำเนินงานตามอำนาจหน้าที่ โดยให้คณะบริหารสภาเด็กและเยาวชนอำเภอหรือคณะบริหารสภาเด็กและเยาวชนเขต แล้วแต่กรณี เป็นผู้เสนอ ทั้งนี้ ให้สอดคล้องกับข้อบังคับของสภาเด็กและเยาวชนแห่งประเทศไทย

มาตรา ๒๖ ให้มีสภาเด็กและเยาวชนจังหวัด ซึ่งสมาชิกประกอบด้วยประธานสภาเด็กและเยาวชนอำเภอทุกอำเภอ และผู้แทนจากคณะบริหารสภาเด็กและเยาวชนอำเภอแต่ละอำเภอ อำเภอละสี่คน
    - ให้มีคณะบริหารสภาเด็กและเยาวชนจังหวัด ประกอบด้วยประธานสภาหนึ่งคน และผู้บริหารอีกไม่เกินยี่สิบคน ซึ่งคัดเลือกกันเองจากสมาชิกสภาเด็กและเยาวชนจังหวัด 
      ให้มีหน้าที่บริหารงานทั่วไปของสภาเด็กและเยาวชนจังหวัด และปรึกษาหารือร่วมกันเพื่อกำหนดแนวทางในการจัดกิจกรรมการพัฒนาเด็กและเยาวชนในเขตพื้นที่ รวมทั้งดำเนินการอื่นใดที่จำเป็นเพื่อให้บรรลุวัตถุประสงค์ของพระราชบัญญัตินี้
    - ให้ผู้ว่าราชการจังหวัด เป็นที่ปรึกษาคณะบริหารสภาเด็กและเยาวชนจังหวัด และให้แต่งตั้งที่ปรึกษาคณะบริหารสภาเด็กและเยาวชนจังหวัด จากพัฒนาสังคมและความมั่นคงของมนุษย์จังหวัด ผู้อำนวยการสำนักงานเขตพื้นที่การศึกษามัธยมศึกษา 
      นายกองค์การบริหารส่วนจังหวัด หัวหน้าบ้านพักเด็กและครอบครัวในแต่ละจังหวัด ผู้แทนสำนักงานส่งเสริมการศึกษานอกระบบและการศึกษาตามอัธยาศัย ผู้แทนหน่วยงานของรัฐหรือเจ้าหน้าที่ของรัฐที่เกี่ยวข้องกับการส่งเสริมการพัฒนาเด็กและเยาวชน 
      และผู้แทนองค์กรภาคประชาสังคมที่มีกิจกรรมหรือผลงานเกี่ยวกับการพัฒนาเด็กและเยาวชน ทั้งนี้ ให้เป็นไปตามที่คณะบริหารสภาเด็กและเยาวชนจังหวัดเสนอ

มาตรา ๒๗ ให้มีสภาเด็กและเยาวชนกรุงเทพมหานคร ซึ่งสมาชิกประกอบด้วย
    (๑) ประธานสภาเด็กและเยาวชนเขต จากทุกเขตในกรุงเทพมหานคร
    (๒) ผู้แทนกลุ่มเด็กและเยาวชน ประกอบด้วย
    (ก) ผู้แทนจากสถาบันการศึกษาในพื้นที่กรุงเทพมหานคร ระดับมัธยมศึกษา ระดับอาชีวศึกษา และระดับอุดมศึกษา ระดับละสิบเอ็ดคน
    (ข) ผู้แทนเด็กและเยาวชน ซึ่งมาจากการคัดเลือกกันเองจากกลุ่มเด็กและเยาวชนที่ได้ลงทะเบียนไว้ตามระเบียบที่ผู้ว่าราชการกรุงเทพมหานครกำหนด โดยคำนึงถึงความหลากหลายของกลุ่มเด็กและเยาวชน จำนวนสิบสองคน ซึ่งต้องมาจากแต่ละกลุ่มอย่างน้อยกลุ่มละหนึ่งคน
    - ทั้งนี้ การคัดเลือกสมาชิกสภาเด็กและเยาวชนกรุงเทพมหานครให้คำนึงถึงผู้พิการและผู้ด้อยโอกาสด้วย

มาตรา ๒๘ ให้มีคณะบริหารสภาเด็กและเยาวชนกรุงเทพมหานคร ประกอบด้วยประธานสภาหนึ่งคน และผู้บริหารอีกไม่เกินยี่สิบคน ซึ่งคัดเลือกกันเองจากสมาชิกสภาเด็กและ
     เยาวชนกรุงเทพมหานคร ให้มีหน้าที่บริหารงานทั่วไปของสภาเด็กและเยาวชน และปรึกษาหารือร่วมกันเพื่อกำหนดแนวทางในการจัดกิจกรรมการพัฒนาเด็กและเยาวชนในเขตกรุงเทพมหานคร รวมทั้งดำเนินการอื่นใดที่จำเป็นเพื่อให้บรรลุวัตถุประสงค์ของพระราชบัญญัตินี้
    - ให้ผู้ว่าราชการกรุงเทพมหานคร เป็นที่ปรึกษาคณะบริหารสภาเด็กและเยาวชนกรุงเทพมหานคร และให้แต่งตั้งที่ปรึกษาคณะบริหารสภาเด็กและเยาวชนกรุงเทพมหานคร 
      จากผู้อำนวยการสำนักพัฒนาสังคม ผู้อำนวยการสำนักวัฒนธรรม กีฬา และการท่องเที่ยว ผู้อำนวยการสำนักการศึกษา ผู้แทนกรมกิจการเด็กและเยาวชน ผู้แทนหน่วยงานของรัฐหรือเจ้าหน้าที่ของรัฐที่เกี่ยวข้องกับการส่งเสริมการพัฒนาเด็กและเยาวชน 
      และผู้แทนองค์กรภาคประชาสังคมที่มีกิจกรรมหรือผลงานเกี่ยวกับการพัฒนาเด็กและเยาวชน ทั้งนี้ ให้เป็นไปตามที่คณะบริหารสภาเด็กและเยาวชนกรุงเทพมหานครเสนอ

มาตรา ๒๙ สภาเด็กและเยาวชนจังหวัดและสภาเด็กและเยาวชนกรุงเทพมหานคร มีอำนาจหน้าที่ ดังต่อไปนี้
    (๑) ประสานงานระหว่างสภาเด็กและเยาวชนจังหวัด สภาเด็กและเยาวชนกรุงเทพมหานคร และสภาเด็กและเยาวชนแห่งประเทศไทย เพื่อแลกเปลี่ยนความรู้และประสบการณ์ในด้านต่าง ๆ ของเด็กและเยาวชน
    (๒) ส่งเสริม สนับสนุน และเป็นศูนย์กลางการเรียนรู้ด้านวิชาการ การศึกษา สุขภาพ กีฬา อาชีพ และวัฒนธรรมในท้องถิ่นของเด็กและเยาวชน
    (๓) ส่งเสริม สนับสนุน ให้เด็กและเยาวชนได้แสดงความคิดเห็นหรือแสดงออกอย่างสอดคล้องกับความรู้ความสามารถที่พัฒนาไปตามวัยของเด็กหรือเยาวชน โดยเฉพาะเรื่องที่มีผลกระทบต่อเด็กและเยาวชน
    (๔) จัดกิจกรรมต่าง ๆ เพื่อส่งเสริมและพัฒนาเด็กและเยาวชนในท้องถิ่นให้มีความรู้ความสามารถ รวมทั้งคุณธรรมและจริยธรรม
    (๕) รวบรวมข้อมูล ข้อเสนอแนะ หรือประเมินเรื่องที่มีผลกระทบต่อเด็กและเยาวชนในเขตพื้นที่ เพื่อส่งต่อข้อมูลดังกล่าวให้กับสภาเด็กและเยาวชนแห่งประเทศไทย
    (๖) เสนอความเห็นต่อหน่วยงานที่เกี่ยวข้องกับกิจกรรมการส่งเสริมและพัฒนาเด็กและเยาวชน รวมทั้งการแก้ไขปัญหาที่มีผลกระทบต่อเด็กและเยาวชนในเขตพื้นที่
    (๗) เสนอแนะและให้ความเห็นต่อสภาเด็กและเยาวชนแห่งประเทศไทย เกี่ยวกับการส่งเสริมและพัฒนาเด็กและเยาวชนในท้องถิ่น
    (๘) เสนอความเห็นต่อคณะกรรมการเกี่ยวกับการปฏิบัติงานของหน่วยงานของรัฐ และองค์กรเอกชนหรือองค์กรชุมชนที่เกี่ยวข้องกับเด็กและเยาวชนในเขตพื้นที่
    (๙) ออกข้อบังคับเกี่ยวกับการประชุมและการดำเนินงานตามอำนาจหน้าที่ โดยให้คณะบริหารสภาเด็กและเยาวชนจังหวัดหรือคณะบริหารสภาเด็กและเยาวชนกรุงเทพมหานคร แล้วแต่กรณี เป็นผู้เสนอ ทั้งนี้ ให้สอดคล้องกับข้อบังคับของสภาเด็กและเยาวชนแห่งประเทศไทย

มาตรา ๓๐ ให้มีสภาเด็กและเยาวชนแห่งประเทศไทย ซึ่งสมาชิกประกอบด้วย
    (๑) ประธานสภาเด็กและเยาวชนจังหวัดจากทุกจังหวัด
    (๒) ประธานสภาเด็กและเยาวชนกรุงเทพมหานคร
    (๓) ผู้แทนเด็กและเยาวชน ซึ่งมาจากการคัดเลือกกันเองจาก```python
มาตรา ๓๐: การจัดตั้งและองค์ประกอบของสภาเด็กและเยาวชนแห่งประเทศไทย
    - สมาชิกประกอบด้วย:
      (๑) ประธานสภาเด็กและเยาวชนจังหวัดจากทุกจังหวัด
      (๒) ประธานสภาเด็กและเยาวชนกรุงเทพมหานคร
      (๓) ผู้แทนเด็กและเยาวชนที่คัดเลือกกันเองจากกลุ่มที่ลงทะเบียนตามระเบียบที่รัฐมนตรีกำหนด (คำนึงถึงความหลากหลาย ผู้พิการ และผู้ด้อยโอกาส) จำนวน ๓๘ คน
    - ให้มีคณะบริหารสภาเด็กและเยาวชนแห่งประเทศไทย ประกอบด้วย ประธานสภา ๑ คน และผู้บริหารอีกไม่เกิน ๒๕ คน ซึ่งคัดเลือกกันเองจากสมาชิกสภา
    - อำนาจหน้าที่ของคณะบริหาร: บริหารงานทั่วไป เสนอแผนงาน/แนวปฏิบัติการพัฒนาเด็กและเยาวชนต่อกรมกิจการเด็กและเยาวชน เพื่อใช้จัดทำแผนพัฒนาเด็กและเยาวชนแห่งชาติ เป็นผู้แทนหรือพิจารณาคัดเลือกผู้แทนเด็กและเยาวชนในการดำเนินกิจกรรมทั้งในและต่างประเทศ
    - การแต่งตั้งที่ปรึกษาคณะบริหาร: ให้คณะกรรมการแต่งตั้งที่ปรึกษาจากผู้แทนกระทรวงยุติธรรม, ศธ., วธ., สำนักงานอัยการสูงสุด, กรมกิจการเด็กและเยาวชน, หน่วยงานรัฐที่เกี่ยวข้อง และองค์กรภาคประชาสังคม ตามที่คณะบริหารเสนอ

มาตรา ๓๑: อำนาจหน้าที่ของสภาเด็กและเยาวชนแห่งประเทศไทย
    (๑) ทำหน้าที่เป็นศูนย์กลางประสานงานการดำเนินกิจกรรมส่งเสริมและพัฒนาเด็กและเยาวชน
    (๒) ให้ความร่วมมือในการดำเนินงานของภาครัฐ องค์กรเอกชน และองค์กรชุมชน
    (๓) ส่งเสริม สนับสนุนให้เด็กและเยาวชนได้แสดงความคิดเห็นหรือแสดงออกตามวัย โดยเฉพาะเรื่องที่มีผลกระทบต่อตนเอง
    (๔) ให้ความเห็นในการกำหนดแนวทาง นโยบาย แผนงาน และงบประมาณของหน่วยงานรัฐด้านการส่งเสริมและพัฒนาเด็กและเยาวชน
    (๕) รวบรวมข้อมูล ข้อเสนอแนะ หรือประเมินเรื่องที่มีผลกระทบต่อเด็กและเยาวชน และข้อมูลที่ถูกส่งต่อมายังสภาเด็กและเยาวชนแห่งประเทศไทย เพื่อเสนอคณะกรรมการพิจารณาเป็นแนวทางในการส่งเสริมและพัฒนาเด็กและเยาวชน
    (๖) เสนอความเห็นต่อหน่วยงานที่เกี่ยวข้องกับกิจกรรมการส่งเสริมและพัฒนาเด็กและเยาวชน รวมทั้งการแก้ไขปัญหาที่มีผลกระทบต่อเด็กและเยาวชน
    (๗) เสนอความเห็นต่อคณะกรรมการเกี่ยวกับการปฏิบัติงานของหน่วยงานของรัฐ และองค์กรเอกชนหรือองค์กรชุมชนที่เกี่ยวข้องกับเด็กและเยาวชน
    (๘) จัดทำประมวลจริยธรรมของสมาชิกสภาเด็กและเยาวชน
    (๙) ออกข้อบังคับเกี่ยวกับการประชุมและการดำเนินงานตามอำนาจหน้าที่ โดยให้คณะบริหารสภาเด็กและเยาวชนแห่งประเทศไทยเป็นผู้เสนอ
    - สภาเด็กและเยาวชนแห่งประเทศไทยต้องจัดให้มีการประชุมสามัญอย่างน้อยปีละสองครั้ง

มาตรา ๓๒ คณะบริหารต้องมีคุณสมบัติและไม่มีลักษณะต้องห้าม ดังต่อไปนี้
    (๑) มีอายุไม่เกินยี่สิบห้าปี
    (๒) ไม่เป็นผู้ดำรงตำแหน่งในทางการเมือง กรรมการหรือผู้ดำรงตำแหน่งที่รับผิดชอบในการบริหารพรรคการเมือง ที่ปรึกษาพรรคการเมือง เจ้าหน้าที่พรรคการเมือง สมาชิกสภาท้องถิ่น หรือผู้บริหารท้องถิ่น

มาตรา ๓๓ คณะบริหารมีวาระการดำรงตำแหน่งคราวละสองปีนับแต่วันที่ได้รับการคัดเลือก ประธานสภาหรือผู้บริหารในคณะบริหารซึ่งพ้นจากตำแหน่งอาจได้รับการคัดเลือกอีกได้ แต่ต้องดำรงตำแหน่งไม่เกินสองวาระติดต่อกัน
    - กรณีที่คณะบริหารพ้นจากตำแหน่งตามวาระ ให้ดำเนินการคัดเลือกใหม่ภายในหกสิบวันนับแต่วันที่คณะบริหารพ้นจากตำแหน่งตามวาระ แต่ในระหว่างที่ยังมิได้มีการคัดเลือกคณะบริหาร ให้คณะบริหารนั้นปฏิบัติหน้าที่ไปพลางก่อนจนกว่าจะได้มีการคัดเลือกคณะบริหารใหม่
    - ในวาระเริ่มแรก เมื่อคณะบริหารดำรงตำแหน่งครบหนึ่งปี ให้คณะบริหารยกเว้นประธานสภาจับสลากออกกึ่งหนึ่ง และคัดเลือกผู้บริหารใหม่แทนตำแหน่งที่ว่าง โดยผู้ที่ได้รับการคัดเลือกใหม่มีวาระการดำรงตำแหน่งสองปี

มาตรา ๓๔ นอกจากการพ้นจากตำแหน่งตามวาระ คณะบริหารพ้นจากตำแหน่งเมื่อ
    (๑) ตาย
    (๒) ลาออก
    (๓) ขาดคุณสมบัติหรือมีลักษณะต้องห้ามตามมาตรา ๓๒
    (๔) ถูกถอดถอนจากตำแหน่งตามที่กำหนดไว้ในข้อบังคับของสภาเด็กและเยาวชน

มาตรา ๓๕ ในกรณีที่คณะบริหารของสภาเด็กและเยาวชนพ้นจากตำแหน่งก่อนครบวาระ ให้มีการคัดเลือกผู้อื่นแทนตำแหน่งที่ว่าง เว้นแต่วาระของผู้ที่พ้นจากตำแหน่งเหลือไม่ถึงเก้าสิบวัน อาจคัดเลือกผู้อื่นแทนตำแหน่งที่ว่างนั้นก็ได้ และให้ผู้ที่ได้รับการคัดเลือกแทนตำแหน่งที่ว่างอยู่ในตำแหน่งเท่ากับวาระที่เหลืออยู่ของผู้ซึ่งตนแทน

มาตรา ๓๖ ให้กรมกิจการเด็กและเยาวชนดำเนินการส่งเสริม สนับสนุน และประสานงานการจัดตั้งและการดำเนินกิจการของสภาเด็กและเยาวชนตำบล สภาเด็กและเยาวชนเทศบาล สภาเด็กและเยาวชนอำเภอ สภาเด็กและเยาวชนจังหวัด และสภาเด็กและเยาวชนแห่งประเทศไทย
    - ให้กรมกิจการเด็กและเยาวชนร่วมกับกรุงเทพมหานครดำเนินการส่งเสริม สนับสนุน และประสานงานการจัดตั้งและการดำเนินกิจการของสภาเด็กและเยาวชนเขตและสภาเด็กและเยาวชนกรุงเทพมหานคร

มาตรา ๓๗ การประชุมของสภาเด็กและเยาวชน ต้องมีสมาชิกมาประชุมไม่น้อยกว่ากึ่งหนึ่งของจำนวนสมาชิกทั้งหมดจึงจะเป็นองค์ประชุม ทั้งนี้ ให้การประชุมของสภาเด็กและเยาวชนเป็นไปตามระเบียบที่รัฐมนตรีกำหนด
    - การวินิจฉัยชี้ขาดของที่ประชุมให้ถือเสียงข้างมาก สมาชิกสภาเด็กและเยาวชนคนหนึ่งให้มีเสียงหนึ่งในการลงคะแนน ถ้าคะแนนเสียงเท่ากันให้ประธานในที่ประชุมออกเสียงเพิ่มขึ้นอีกเสียงหนึ่งเป็นเสียงชี้ขาด

มาตรา ๓๘ การดำเนินงานของสภาเด็กและเยาวชน และคณะบริหารสภาเด็กและเยาวชน ให้เป็นไปตามข้อบังคับที่สภาเด็กและเยาวชนได้กำหนดไว้ ทั้งนี้ ให้สภาเด็กและเยาวชนจัดให้มีการประชุมสามัญอย่างน้อยปีละหนึ่งครั้ง เว้นแต่สภาเด็กและเยาวชนแห่งประเทศไทยตามมาตรา ๓๑ วรรคสอง และให้คณะบริหารสภาเด็กและเยาวชนจัดให้มีการประชุมอย่างน้อยปีละสองครั้ง

มาตรา ๓๙ (ยกเลิก)

มาตรา ๔๐ (ยกเลิก)
  [ส่วนที่ ๒: การส่งเสริมบทบาทขององค์กรเอกชนหรือองค์กรชุมชนในการพัฒนาเด็กและเยาวชน]

มาตรา ๔๑: การจดทะเบียนองค์กรด้านการพัฒนาเด็กและเยาวชน
    - องค์กรเอกชนหรือองค์กรชุมชนที่มีผลงานด้านเด็กและเยาวชน และไม่มีวัตถุประสงค์ทางการเมืองหรือแสวงหากำไร มีสิทธิขอจดทะเบียนเป็นองค์กรด้านการพัฒนาเด็กและเยาวชนต่อกระทรวง พม. ตามหลักเกณฑ์ในกฎกระทรวง

มาตรา ๔๒: สิทธิประโยชน์และการสนับสนุนจากรัฐสำหรับองค์กรที่จดทะเบียน
    - อาจได้รับเงินอุดหนุน ความช่วยเหลือ หรือการสนับสนุนจากรัฐสำหรับการดำเนินงาน ได้แก่:
      (๑) การจัดให้มีอาสาสมัครช่วยปฏิบัติงานด้านการคุ้มครองและพัฒนาเด็กและเยาวชน
      (๒) การประชาสัมพันธ์และเผยแพร่ข้อมูลข่าวสารเพื่อสร้างจิตสำนึกที่ถูกต้องแก่สาธารณชน
      (๓) การจัดทำหรือดำเนินโครงการ/กิจกรรมเพื่อการพัฒนาเด็กและเยาวชน
      (๔) การศึกษาวิจัยด้านการพัฒนาเด็กและเยาวชน
      (๕) การให้ความช่วยเหลือเด็กและเยาวชนที่ถูกละเมิดสิทธิ (เช่น ทางกฎหมาย การแพทย์ บำบัดฟื้นฟู และการสงเคราะห์)
    - หลักเกณฑ์ วิธีการ และเงื่อนไขในการรับเงินอุดหนุนหรือการสนับสนุน ให้เป็นไปตามระเบียบที่รัฐมนตรีกำหนด

มาตรา ๔๓: หน้าที่ขององค์กรที่ได้รับการสนับสนุน
    - องค์กรเอกชนหรือองค์กรชุมชนที่ได้รับเงินอุดหนุนหรือความช่วยเหลือตามมาตรา ๔๒ มีหน้าที่จัดทำรายงานผลการดำเนินงานเสนอต่อสำนักงานตามระเบียบที่รัฐมนตรีกำหนด

มาตรา ๔๔ องค์กรเอกชนหรือองค์กรชุมชนใดที่ได้จดทะเบียนแล้วดำเนินกิจการที่อาจก่อความวุ่นวายหรือขัดต่อความสงบเรียบร้อยหรือศีลธรรมอันดีของประชาชน 
        ไม่ดำเนินการพัฒนาเด็กและเยาวชนให้เหมาะสม หรือไม่มีผลงานตามมาตรฐานที่รัฐมนตรีกำหนด ให้รัฐมนตรีมีอำนาจสั่งเพิกถอนการจดทะเบียนหรือระงับการให้เงินอุดหนุน ความช่วยเหลือ หรือการสนับสนุนที่ให้แก่องค์กรเอกชนหรือองค์กรชุมชนนั้นได้


มาตรา ๔๕ ในระหว่างที่ยังมิได้แต่งตั้งคณะกรรมการส่งเสริมการพัฒนาเด็กและเยาวชนแห่งชาติตามพระราชบัญญัตินี้ ให้คณะกรรมการส่งเสริมและประสานงานเยาวชนแห่งชาติตามพระราชบัญญัติส่งเสริมและประสานงานเยาวชน

มาตรา 44: อำนาจการเพิกถอนทะเบียนหรือระงับการสนับสนุน
    - หากองค์กรเอกชนหรือองค์กรชุมชนที่จดทะเบียนแล้ว ดำเนินการที่อาจก่อความวุ่นวาย ขัดต่อความสงบเรียบร้อยหรือศีลธรรมอันดี ไม่พัฒนาเด็กและเยาวชนอย่างเหมาะสม หรือไม่มีผลงานตามมาตรฐานที่กำหนด ให้รัฐมนตรีมีอำนาจสั่งเพิกถอนการจดทะเบียน หรือระงับเงินอุดหนุน ความช่วยเหลือ และการสนับสนุนได้

มาตรา 45: การปฏิบัติหน้าที่ชั่วคราวของคณะกรรมการ
    - ในระหว่างที่ยังไม่ได้แต่งตั้งคณะกรรมการส่งเสริมการพัฒนาเด็กและเยาวชนแห่งชาติตาม พ.ร.บ. นี้ ให้คณะกรรมการส่งเสริมและประสานงานเยาวชนแห่งชาติตาม พ.ร.บ. พ.ศ. 2521 เดิม ทำหน้าที่แทนไปพลางก่อนจนกว่าจะมีคณะกรรมการชุดใหม่ ทั้งนี้ ต้องไม่เกิน 300 วันนับแต่วันที่ พ.ร.บ. นี้ใช้บังคับ


** พระราชบัญญัติส่งเสริมการพัฒนาเด็กและเยาวชนแห่งชาติ (ฉบับที่ ๒) พ.ศ. ๒๕๖๐ **

มาตรา ๒ พระราชบัญญัติตัวนี้ให้ใช้บังคับตั้งแต่วันถัดจากวันประกาศในราชกิจจานุเบกษาเป็นต้นไป

มาตรา ๑๐ ในวาระเริ่มแรก ให้มีการดำเนินการดังต่อไปนี้
    (๑) ให้มีสภาเด็กและเยาวชนตำบลหรือสภาเด็กและเยาวชนเทศบาลตามมาตรา ๒๒ ให้แล้วเสร็จภายในหนึ่งร้อยยี่สิบวันนับแต่วันที่พระราชบัญญัติตัวนี้ใช้บังคับ
    (๒) ให้มีสภาเด็กและเยาวชนเขตตามมาตรา ๒๔ ให้แล้วเสร็จภายในหนึ่งร้อยห้าสิบวันนับแต่วันที่พระราชบัญญัติตัวนี้ใช้บังคับ
    (๓) ให้มีสภาเด็กและเยาวชนกรุงเทพมหานครตามมาตรา ๒๘ ให้แล้วเสร็จภายในหนึ่งร้อยแปดสิบวันนับแต่วันที่พระราชบัญญัติตัวนี้ใช้บังคับ

มาตรา ๑๑ ให้สภาเด็กและเยาวชนอำเภอ สภาเด็กและเยาวชนจังหวัด สภาเด็กและเยาวชนกรุงเทพมหานคร และสภาเด็กและเยาวชนแห่งประเทศไทยตามพระราชบัญญัติส่งเสริมการพัฒนาเด็กและเยาวชนแห่งชาติ พ.ศ. ๒๕๕๐ 
         ที่มีอยู่ในวันก่อนวันที่พระราชบัญญัติตัวนี้ใช้บังคับ เป็นสภาเด็กและเยาวชนอำเภอ สภาเด็กและเยาวชนจังหวัด สภาเด็กและเยาวชนกรุงเทพมหานคร และสภาเด็กและเยาวชนแห่งประเทศไทยตามพระราชบัญญัติส่งเสริมการพัฒนาเด็กและเยาวชนแห่งชาติ พ.ศ. ๒๕๕๐ ซึ่งแก้ไขเพิ่มเติมโดยพระราชบัญญัติตัวนี้

มาตรา ๑๒ ให้คณะบริหารสภาเด็กและเยาวชนอำเภอ คณะบริหารสภาเด็กและเยาวชนจังหวัด คณะบริหารสภาเด็กและเยาวชนกรุงเทพมหานคร 
         คณะบริหารสภาเด็กและเยาวชนแห่งประเทศไทยตามพระราชบัญญัติส่งเสริมการพัฒนาเด็กและเยาวชนแห่งชาติ พ.ศ. ๒๕๕๐ ซึ่งดำรงตำแหน่งอยู่ในวันก่อนวันที่พระราชบัญญัติตัวนี้ใช้บังคับ ยังคงปฏิบัติหน้าที่อยู่ต่อไปจนกว่าจะมีการคัดเลือกคณะบริหารสภาเด็กและเยาวชนอำเภอ 
         คณะบริหารสภาเด็กและเยาวชนจังหวัด คณะบริหารสภาเด็กและเยาวชนกรุงเทพมหานคร และคณะบริหารสภาเด็กและเยาวชนแห่งประเทศไทยตามพระราชบัญญัติส่งเสริมการพัฒนาเด็กและเยาวชนแห่งชาติ พ.ศ. ๒๕๕๐ ซึ่งแก้ไขเพิ่มเติมโดยพระราชบัญญัติตัวนี้

มาตรา ๑๓ ให้รัฐมนตรีว่าการกระทรวงการพัฒนาสังคมและความมั่นคงของมนุษย์รักษาการตามพระราชบัญญัติตัวนี้

มาตรา ๑๓: กำหนดให้รัฐมนตรีว่าการกระทรวงการพัฒนาสังคมและความมั่นคงของมนุษย์ เป็นผู้รักษาการตามพระราชบัญญัตินี้


พระราชบัญญัติส่งเสริมการพัฒนาเด็กและเยาวชนแห่งชาติ (ฉบับที่ ๒) พ.ศ. ๒๕๖๐


มาตรา ๑: พระราชบัญญัตินี้เรียกว่า "พระราชบัญญัติส่งเสริมการพัฒนาเด็กและเยาวชนแห่งชาติ (ฉบับที่ ๒) พ.ศ. ๒๕๖๐"

มาตรา ๒: พระราชบัญญัตินี้ให้ใช้บังคับตั้งแต่วันถัดจากวันประกาศในราชกิจจานุเบกษาเป็นต้นไป

มาตรา ๓: ให้ยกเลิกความในบทนิยามคำว่า “คณะบริหาร” “สำนักงาน” และ “ผู้อำนวยการ” ในมาตรา ๔ แห่งพระราชบัญญัติส่งเสริมการพัฒนาเด็กและเยาวชนแห่งชาติ พ.ศ. ๒๕๕๐ และให้ใช้ความต่อไปนี้แทน
    - "คณะบริหาร" หมายความว่า คณะบริหารสภาเด็กและเยาวชนตำบล คณะบริหารสภาเด็กและเยาวชนเทศบาล คณะบริหารสภาเด็กและเยาวชนอำเภอ 
       คณะบริหารสภาเด็กและเยาวชนเขต คณะบริหารสภาเด็กและเยาวชนจังหวัด คณะบริหารสภาเด็กและเยาวชนกรุงเทพมหานคร และคณะบริหารสภาเด็กและเยาวชนแห่งประเทศไทย
    - "สำนักงาน" หมายความว่า กรมกิจการเด็กและเยาวชน
    - "ผู้อำนวยการ" หมายความว่า อธิบดีกรมกิจการเด็กและเยาวชน

มาตรา ๔: ให้ยกเลิกความในวรรคสองของมาตรา ๖ แห่งพระราชบัญญัติส่งเสริมการพัฒนาเด็กและเยาวชนแห่งชาติ พ.ศ. ๒๕๕๐ และให้ใช้ความต่อไปนี้แทน
    “การดำเนินการตามวรรคหนึ่ง ให้กระทำโดยมีแนวทาง ดังต่อไปนี้
    (๑) ให้เด็กและเยาวชนมีความผูกพันต่อครอบครัว ภาคภูมิใจในความเป็นไทย มีวิถีชีวิตแบบประชาธิปไตย
    (๒) ให้สามารถดำเนินชีวิตได้อย่างปลอดภัย รู้จักเคารพสิทธิและเสรีภาพของผู้อื่น รวมทั้งกฎหมาย กฎเกณฑ์ และกติกาในสังคม
    (๓) ให้การสนับสนุนและส่งเสริมความร่วมมือทางการศึกษา ทั้งภายในประเทศและภายนอกประเทศ เพื่อให้เด็กและเยาวชนทุกคนสามารถเข้าถึงการศึกษาได้อย่างเหมาะสม
    (๔) ให้การสนับสนุนและส่งเสริมการศึกษาเพื่อพัฒนาเด็กพิการ เด็กที่มีข้อจำกัดทางการเรียนรู้ และเด็กที่มีความสามารถพิเศษ ให้สามารถพึ่งตนเองได้ ให้มีคุณธรรม และมีคุณภาพชีวิตที่ดี สามารถประกอบอาชีพและดำรงชีวิตได้อย่างเป็นอิสระ
    (๕) ให้มีสุขภาพพลานามัยที่สมบูรณ์แข็งแรง รู้จักการป้องกันตนเองจากโรคภัยและสิ่งเสพติด
    (๖) ให้มีวุฒิภาวะทางอารมณ์ตามสมควรแก่วัย รวมทั้งมีคุณธรรมและจริยธรรม
    (๗) ให้มีทักษะและเจตคติที่ดีต่อการทำงาน มีศักดิ์ศรีและภาคภูมิใจในการทำงานที่สุจริต
    (๘) ให้รู้จักคิดอย่างมีเหตุผลและมุ่งมั่นพัฒนาตนเองอย่างต่อเนื่อง
    (๙) ให้รู้จักช่วยเหลือผู้อื่นโดยมีจิตสำนึกในการให้และการเป็นอาสาสมัคร รวมทั้งมีส่วนร่วมในการพัฒนาชุมชนและประเทศชาติ
    (๑๐) ให้มีความรับผิดชอบต่อตนเอง ผู้อื่น และต่อส่วนรวม ตามสมควรแก่วัย
    (๑๑) ให้สามารถแสดงความคิดเห็นหรือแสดงออกอย่างสอดคล้องกับความรู้ความสามารถที่พัฒนาไปตามวัยของเด็กและเยาวชน โดยเฉพาะเรื่องที่มีผลกระทบต่อเด็กและเยาวชน
    (๑๒) ให้สามารถเข้าไปมีส่วนร่วมในกระบวนการยุติธรรมในเรื่องที่มีผลกระทบต่อเด็กและเยาวชนอย่างเหมาะสม ไม่ว่าจะโดยทางตรง หรือผ่านผู้แทนหรือองค์กรเพื่อเด็กและเยาวชน”

มาตรา ๕: ให้ยกเลิกความใน (๔) ของมาตรา ๑๐ แห่งพระราชบัญญัติส่งเสริมการพัฒนาเด็กและเยาวชนแห่งชาติ พ.ศ. ๒๕๕๐ และให้ใช้ความต่อไปนี้แทน
    “(๔) กรรมการโดยตำแหน่ง ได้แก่ ปลัดกระทรวงกลาโหม ปลัดกระทรวงการท่องเที่ยวและกีฬา ปลัดกระทรวงการพัฒนาสังคมและความมั่นคงของมนุษย์ ปลัดกระทรวงดิจิทัลเพื่อเศรษฐกิจและสังคม 
         ปลัดกระทรวงมหาดไทย ปลัดกระทรวงยุติธรรม ปลัดกระทรวงแรงงาน ปลัดกระทรวงวัฒนธรรม ปลัดกระทรวงศึกษาธิการ ปลัดกระทรวงสาธารณสุข ผู้บัญชาการตำรวจแห่งชาติ ปลัดกรุงเทพมหานคร ประธานสภาองค์การพัฒนาเด็กและเยาวชน และประธานสภาเด็กและเยาวชนแห่งประเทศไทย”

มาตรา ๖: ให้ยกเลิกความใน (๖) ของมาตรา ๑๐ แห่งพระราชบัญญัติส่งเสริมการพัฒนาเด็กและเยาวชนแห่งชาติ พ.ศ. ๒๕๕๐ และให้ใช้ความต่อไปนี้แทน
    “(๖) ผู้แทนองค์กรปกครองส่วนท้องถิ่นซึ่งเลือกกันเอง จำนวนสามคน”

มาตรา ๗: ให้เพิ่มความต่อไปนี้เป็นมาตรา ๑๔/๑ แห่งพระราชบัญญัติส่งเสริมการพัฒนาเด็กและเยาวชนแห่งชาติ พ.ศ. ๒๕๕๐
    “มาตรา ๑๔/๑ ผู้แทนเด็กและเยาวชนในคณะกรรมการส่งเสริมการพัฒนาเด็กและเยาวชนแห่งชาติ ตามมาตรา ๑๐ (๗) พ้นจากตำแหน่งเมื่อ
    (๑) มีอายุเกินยี่สิบห้าปี
    (๒) พ้นจากการเป็นผู้แทนของสภาเด็กและเยาวชนแห่งประเทศไทย”

มาตรา ๘: ให้ยกเลิกความในวรรคหนึ่งของมาตรา ๑๘ แห่งพระราชบัญญัติส่งเสริมการพัฒนาเด็กและเยาวชนแห่งชาติ พ.ศ. ๒๕๕๐ และให้ใช้ความต่อไปนี้แทน
    “มาตรา ๑๘ คณะกรรมการมีอำนาจแต่งตั้งคณะอนุกรรมการหรือคณะทำงานเพื่อพิจารณาหรือปฏิบัติการตามที่คณะกรรมการมอบหมาย และมีอำนาจแต่งตั้งที่ปรึกษาคณะบริหารสภาเด็กและเยาวชนแห่งประเทศไทยตามที่สภาเด็กและเยาวชนแห่งประเทศไทยเป็นผู้เสนอ”

มาตรา ๙: ให้ยกเลิกบทบัญญัติในส่วนที่ ๑ สภาเด็กและเยาวชน ของหมวด ๓ มาตรการส่งเสริมการดำเนินงานเพื่อการพัฒนาเด็กและเยาวชน 
         มาตรา ๒๒ มาตรา ๒๓ มาตรา ๒๔ มาตรา ๒๕ มาตรา ๒๖ มาตรา ๒๗ มาตรา ๒๘ มาตรา ๒๙ มาตรา ๓๐ มาตรา ๓๑ มาตรา ๓๒ มาตรา ๓๓ มาตรา ๓๔ 
         มาตรา ๓๕ มาตรา ๓๖ มาตรา ๓๗ มาตรา ๓๘ มาตรา ๓๙ และมาตรา ๔๐ แห่งพระราชบัญญัติส่งเสริมการพัฒนาเด็กและเยาวชนแห่งชาติ พ.ศ. ๒๕๕๐ และให้ใช้ความต่อไปนี้แทน
    “ส่วนที่ ๑
    สภาเด็กและเยาวชน
    มาตรา ๒๒ ให้องค์การบริหารส่วนตำบล เทศบาล โดยคำแนะนำของหัวหน้าบ้านพักเด็กและครอบครัวในแต่ละจังหวัด จัดให้มีสภาเด็กและเยาวชนตำบล สภาเด็กและเยาวชนเทศบาล แล้วแต่กรณี ซึ่งสมาชิกประกอบด้วยเด็กและเยาวชนที่อยู่ในเขตพื้นที่องค์การบริหารส่วนตำบลหรือเทศบาลนั้น
    ให้มีคณะบริหารสภาเด็กและเยาวชนตำบลหรือคณะบริหารสภาเด็กและเยาวชนเทศบาล ประกอบด้วยประธานสภาหนึ่งคน และผู้บริหารอีกไม่เกินยี่สิบคน ซึ่งคัดเลือกกันเองจากสมาชิกสภาเด็กและเยาวชนตำบล หรือสมาชิกสภาเด็กและเยาวชนเทศบาล แล้วแต่กรณี โดยคำนึงถึงผู้พิการและผู้ด้อยโอกาส ให้มีหน้าที่บริหาร

มาตรา ๖: ปรับปรุงองค์ประกอบกรรมการตามมาตรา ๑๐ (๖) โดยกำหนดให้มีผู้แทนองค์กรปกครองส่วนท้องถิ่นซึ่งคัดเลือกกันเอง จำนวน ๓ คน

มาตรา ๗: เพิ่มเติมบทบัญญัติ มาตรา ๑๔/๑ กำหนดหลักเกณฑ์การพ้นจากตำแหน่งของผู้แทนเด็กและเยาวชนในคณะกรรมการส่งเสริมการพัฒนาเด็กและเยาวชนแห่งชาติ ตามมาตรา ๑๐ (๗) เมื่อ:
    (๑) มีอายุเกินยี่สิบห้าปีบริบูรณ์
    (๒) พ้นจากสมาชิกภาพการเป็นผู้แทนของสภาเด็กและเยาวชนแห่งประเทศไทย

มาตรา ๘: ปรับปรุงความในมาตรา ๑๘ วรรคหนึ่ง กำหนดให้อำนาจคณะกรรมการในการแต่งตั้งคณะอนุกรรมการ คณะทำงาน รวมถึงการแต่งตั้งที่ปรึกษาคณะบริหารสภาเด็กและเยาวชนแห่งประเทศไทยตามข้อเสนอของสภาเด็กและเยาวชนแห่งประเทศไทย

มาตรา ๙: ยกเลิกและปรับปรุงโครงสร้างบทบัญญัติในหมวด ๓ ส่วนที่ ๑ เรื่องสภาเด็กและเยาวชน (ตั้งแต่มาตรา ๒๒ ถึงมาตรา ๔๐) ใหม่ทั้งชุด:
    [ส่วนที่ ๑: สภาเด็กและเยาวชน]

มาตรา ๒๒: ให้อบต. และเทศบาล ร่วมกับหัวหน้าบ้านพักเด็กและครอบครัวประจำจังหวัด จัดตั้งสภาเด็กและเยาวชนระดับตำบลหรือเทศบาล โดยมีสมาชิกเป็นเด็กและเยาวชนในพื้นที่
      - ให้มีคณะบริหารไม่เกิน ๒๑ คน (ประธาน ๑ คน และผู้บริหารไม่เกิน ๒๐ คน) คัดเลือกกันเองจากสมาชิก โดยคำนึงถึงสัดส่วนผู้พิการและผู้ด้อยโอกาส ทำหน้าที่บริหารและจัดกิจกรรมพัฒนาเด็กและเยาวชนในท้องถิ่น
      - ให้นายอำเภอ เป็นที่ปรึกษาคณะบริหารสภาเด็กและเยาวชนตำบลหรือคณะบริหารสภาเด็กและเยาวชนเทศบาล และให้แต่งตั้งที่ปรึกษาคณะบริหารสภาเด็กและเยาวชนตำบลหรือคณะบริหารสภาเด็กและเยาวชนเทศบาล 
        จากนายกองค์การบริหารส่วนตำบล นายกเทศมนตรี ปลัดองค์การบริหารส่วนตำบล ปลัดเทศบาล แล้วแต่กรณี ผู้แทนสำนักงานพัฒนาสังคมและความมั่นคงของมนุษย์จังหวัด ผู้แทนบ้านพักเด็กและครอบครัวในแต่ละจังหวัด 
        ผู้แทนสำนักงานส่งเสริมการศึกษานอกระบบและการศึกษาตามอัธยาศัย ผู้แทนสถานศึกษา ผู้แทนหน่วยงานของรัฐหรือเจ้าหน้าที่ของรัฐที่เกี่ยวข้องกับการส่งเสริมการพัฒนาเด็กและเยาวชนที่ตั้งอยู่ในเขตพื้นที่องค์การบริหารส่วนตำบลหรือเทศบาลนั้น 
        และผู้แทนองค์กรภาคประชาสังคมที่มีกิจกรรมหรือผลงานเกี่ยวกับการพัฒนาเด็กและเยาวชน ทั้งนี้ ให้เป็นไปตามที่คณะบริหารสภาเด็กและเยาวชนตำบลหรือคณะบริหารสภาเด็กและเยาวชนเทศบาลเสนอ

มาตรา ๒๓ สภาเด็กและเยาวชนตำบลและสภาเด็กและเยาวชนเทศบาล มีอำนาจหน้าที่ ดังต่อไปนี้
    (๑) ประสานงานระหว่างสภาเด็กและเยาวชนตำบล สภาเด็กและเยาวชนเทศบาล สภาเด็กและเยาวชนอำเภอ เพื่อแลกเปลี่ยนความรู้และประสบการณ์ในด้านต่าง ๆ ของเด็กและเยาวชน
    (๒) ส่งเสริม สนับสนุน และเป็นศูนย์กลางการเรียนรู้ด้านวิชาการ การศึกษา สุขภาพ กีฬา อาชีพ และวัฒนธรรมในท้องถิ่นของเด็กและเยาวชน
    (๓) ส่งเสริม สนับสนุน ให้เด็กและเยาวชนได้แสดงความคิดเห็นหรือแสดงออกอย่างสอดคล้องกับความรู้ความสามารถที่พัฒนาไปตามวัยของเด็กหรือเยาวชน โดยเฉพาะเรื่องที่มีผลกระทบต่อเด็กและเยาวชน
    (๔) จัดกิจกรรมต่าง ๆ เพื่อส่งเสริมและพัฒนาเด็กและเยาวชนในท้องถิ่นให้มีความรู้ความสามารถ รวมทั้งคุณธรรมและจริยธรรม
    (๕) รวบรวมข้อมูล ข้อเสนอแนะ หรือประเมินเรื่องที่มีผลกระทบต่อเด็กและเยาวชนในเขตพื้นที่ เพื่อส่งต่อข้อมูลดังกล่าวให้กับสภาเด็กและเยาวชนอำเภอ
    (๖) เสนอความเห็นต่อหน่วยงานที่เกี่ยวข้องกับกิจกรรมการส่งเสริมและพัฒนาเด็กและเยาวชน รวมทั้งการแก้ไขปัญหาที่มีผลกระทบต่อเด็กและเยาวชนในเขตพื้นที่
    (๗) เสนอแนะและให้ความเห็นต่อสภาเด็กและเยาวชนอำเภอ เกี่ยวกับการส่งเสริมและพัฒนาเด็กและเยาวชนในท้องถิ่น
    (๘) เสนอความเห็นต่อคณะกรรมการเกี่ยวกับการปฏิบัติงานของหน่วยงานของรัฐและองค์กรเอกชนหรือองค์กรชุมชนที่เกี่ยวข้องกับเด็กและเยาวชนในเขตพื้นที่
    (๙) ออกข้อบังคับเกี่ยวกับการประชุมและการดำเนินงานตามอำนาจหน้าที่ โดยให้คณะบริหารสภาเด็กและเยาวชนตำบลหรือคณะบริหารสภาเด็กและเยาวชนเทศบาล แล้วแต่กรณี เป็นผู้เสนอ ทั้งนี้ ให้สอดคล้องกับข้อบังคับของสภาเด็กและเยาวชนแห่งประเทศไทย

มาตรา ๒๔: ให้มีสภาเด็กและเยาวชนอำเภอ ซึ่งสมาชิกประกอบด้วยคณะบริหารสภาเด็กและเยาวชนตำบล และคณะบริหารสภาเด็กและเยาวชนเทศบาล ที่อยู่ในเขตพื้นที่อำเภอนั้น
    - ให้มีสภาเด็กและเยาวชนเขต ในกรุงเทพมหานคร ซึ่งสมาชิกประกอบด้วยเด็กและเยาวชนที่อยู่ในเขตพื้นที่กรุงเทพมหานครแต่ละเขตนั้น
    - ให้มีคณะบริหารสภาเด็กและเยาวชนอำเภอและคณะบริหารสภาเด็กและเยาวชนเขต ประกอบด้วยประธานสภาหนึ่งคน และผู้บริหารอีกไม่เกินยี่สิบคน ซึ่งคัดเลือกกันเองจากสมาชิกสภาเด็กและเยาวชนอำเภอหรือสมาชิกสภาเด็กและเยาวชนเขต 
      แล้วแต่กรณี โดยคำนึงถึงผู้พิการและผู้ด้อยโอกาส ให้มีหน้าที่บริหารงานทั่วไปของสภาเด็กและเยาวชน และปรึกษาหารือร่วมกันเพื่อกำหนดแนวทางในการจัดกิจกรรมการพัฒนาเด็กและเยาวชนในเขตพื้นที่ รวมทั้งดำเนินการอื่นใดที่จำเป็นเพื่อให้บรรลุวัตถุประสงค์ของพระราชบัญญัตินี้
    - ให้นายอำเภอหรือผู้อำนวยการเขต เป็นที่ปรึกษาคณะบริหารสภาเด็กและเยาวชนอำเภอหรือคณะบริหารสภาเด็กและเยาวชนเขต แล้วแต่กรณี และให้แต่งตั้งที่ปรึกษาคณะบริหารสภาเด็กและเยาวชนอำเภอหรือคณะบริหารสภาเด็กและเยาวชนเขต 
      แล้วแต่กรณี จากพัฒนาสังคมและความมั่นคงของมนุษย์จังหวัด หัวหน้าบ้านพักเด็กและครอบครัวในแต่ละจังหวัด ผู้แทนสำนักงานส่งเสริมการศึกษานอกระบบและการศึกษาตามอัธยาศัย ผู้แทนสถานศึกษา ผู้แทนหน่วยงานของรัฐหรือเจ้าหน้าที่ของรัฐที่เกี่ยวข้องกับการส่งเสริมการพัฒนาเด็กและเยาวชนที่ตั้งอยู่ในเขตพื้นที่อำเภอหรือเขตในกรุงเทพมหานคร 
      และผู้แทนองค์กรภาคประชาสังคมที่มีกิจกรรมหรือผลงานเกี่ยวกับการพัฒนาเด็กและเยาวชน ทั้งนี้ ให้เป็นไปตามที่คณะบริหารสภาเด็กและเยาวชนอำเภอหรือคณะบริหารสภาเด็กและเยาวชนเขตเสนอ

มาตรา ๒๕: ให้สภาเด็กและเยาวชนอำเภอและสภาเด็กและเยาวชนเขต มีอำนาจหน้าที่ดังต่อไปนี้
    (๑) ประสานงานระหว่างสภาเด็กและเยาวชนอำเภอ สภาเด็กและเยาวชนเขต สภาเด็กและเยาวชนจังหวัด และสภาเด็กและเยาวชนกรุงเทพมหานคร เพื่อแลกเปลี่ยนความรู้และประสบการณ์ในด้านต่าง ๆ ของเด็กและเยาวชน
    (๒) ส่งเสริม สนับสนุน และเป็นศูนย์กลางการเรียนรู้ด้านวิชาการ การศึกษา สุขภาพ กีฬา อาชีพ และวัฒนธรรมในท้องถิ่นของเด็กและเยาวชน
    (๓) ส่งเสริม สนับสนุน ให้เด็กและเยาวชนได้แสดงความคิดเห็นหรือแสดงออกอย่างสอดคล้องกับความรู้ความสามารถที่พัฒนาไปตามวัยของเด็กหรือเยาวชน โดยเฉพาะเรื่องที่มีผลกระทบต่อเด็กและเยาวชน
    (๔) จัดกิจกรรมต่าง ๆ เพื่อส่งเสริมและพัฒนาเด็กและเยาวชนในท้องถิ่นให้มีความรู้ความสามารถ รวมทั้งคุณธรรมและจริยธรรม
    (๕) รวบรวมข้อมูล ข้อเสนอแนะ หรือประเมินเรื่องที่มีผลกระทบต่อเด็กและเยาวชนในเขตพื้นที่ เพื่อส่งต่อข้อมูลดังกล่าวให้กับสภาเด็กและเยาวชนจังหวัดหรือสภาเด็กและเยาวชนกรุงเทพมหานคร แล้วแต่กรณี
    (๖) เสนอความเห็นต่อหน่วยงานที่เกี่ยวข้องกับกิจกรรมการส่งเสริมและพัฒนาเด็กและเยาวชน รวมทั้งการแก้ไขปัญหาที่มีผลกระทบต่อเด็กและเยาวชนในเขตพื้นที่
    (๗) เสนอแนะและให้ความเห็นต่อสภาเด็กและเยาวชนจังหวัด สภาเด็กและเยาวชนกรุงเทพมหานคร เกี่ยวกับการส่งเสริมและพัฒนาเด็กและเยาวชนในท้องถิ่น
    (๘) เสนอความเห็นต่อคณะกรรมการเกี่ยวกับการปฏิบัติงานของหน่วยงานของรัฐและองค์กรเอกชนหรือองค์กรชุมชนที่เกี่ยวข้องกับเด็กและเยาวชนในเขตพื้นที่
    (๙) ออกข้อบังคับเกี่ยวกับการประชุมและการดำเนินงานตามอำนาจหน้าที่ โดยให้คณะบริหารสภาเด็กและเยาวชนอำเภอหรือคณะบริหารสภาเด็กและเยาวชนเขต แล้วแต่กรณี เป็นผู้เสนอ ทั้งนี้ ให้สอดคล้องกับข้อบังคับของสภาเด็กและเยาวชนแห่งประเทศไทย

มาตรา ๒๖: ให้มีสภาเด็กและเยาวชนจังหวัด ซึ่งสมาชิกประกอบด้วยประธานสภาเด็กและเยาวชนอำเภอทุกอำเภอ และผู้แทนจากคณะบริหารสภาเด็กและเยาวชนอำเภอแต่ละอำเภอ อำเภอละสี่คน
    - ให้มีคณะบริหารสภาเด็กและเยาวชนจังหวัด ประกอบด้วยประธานสภาหนึ่งคน และผู้บริหารอีกไม่เกินยี่สิบคน ซึ่งคัดเลือกกันเองจากสมาชิกสภาเด็กและเยาวชนจังหวัด ให้มีหน้าที่บริหารงานทั่วไปของสภาเด็กและเยาวชนจังหวัด 
      และปรึกษาหารือร่วมกันเพื่อกำหนดแนวทางในการจัดกิจกรรมการพัฒนาเด็กและเยาวชนในเขตพื้นที่ รวมทั้งดำเนินการอื่นใดที่จำเป็นเพื่อให้บรรลุวัตถุประสงค์ของพระราชบัญญัตินี้
    - ให้ผู้ว่าราชการจังหวัด เป็นที่ปรึกษาคณะบริหารสภาเด็กและเยาวชนจังหวัด และให้แต่งตั้งที่ปรึกษาคณะบริหารสภาเด็กและเยาวชนจังหวัด จากพัฒนาสังคมและความมั่นคงของมนุษย์จังหวัด 
      ผู้อำนวยการสำนักงานเขตพื้นที่การศึกษามัธยมศึกษา นายกองค์การบริหารส่วนจังหวัด หัวหน้าบ้านพักเด็กและครอบครัวในแต่ละจังหวัด ผู้แทนสำนักงานส่งเสริมการศึกษานอกระบบและการศึกษาตามอัธยาศัย 
      ผู้แทนหน่วยงานของรัฐหรือเจ้าหน้าที่ของรัฐที่เกี่ยวข้องกับการส่งเสริมการพัฒนาเด็กและเยาวชน และผู้แทนองค์กรภาคประชาสังคมที่มีกิจกรรมหรือผลงานเกี่ยวกับการพัฒนาเด็กและเยาวชน ทั้งนี้ ให้เป็นไปตามที่คณะบริหารสภาเด็กและเยาวชนจังหวัดเสนอ

มาตรา ๒๗: ให้มีสภาเด็กและเยาวชนกรุงเทพมหานคร ซึ่งสมาชิกประกอบด้วย
    (๑) ประธานสภาเด็กและเยาวชนเขต จากทุกเขตในกรุงเทพมหานคร
    (๒) ผู้แทนกลุ่มเด็กและเยาวชน ประกอบด้วย
      (ก) ผู้แทนจากสถาบันการศึกษาในพื้นที่กรุงเทพมหานคร ระดับมัธยมศึกษา ระดับอาชีวศึกษา และระดับอุดมศึกษา ระดับละสิบเอ็ดคน
      (ข) ผู้แทนเด็กและเยาวชน ซึ่งมาจากการคัดเลือกกันเองจากกลุ่มเด็กและเยาวชนที่ได้ลงทะเบียนไว้ตามระเบียบที่ผู้ว่าราชการกรุงเทพมหานครกำหนด โดยคำนึงถึงความหลากหลายของกลุ่มเด็กและเยาวชน จำนวนสิบสองคน ซึ่งต้องมาจากแต่ละกลุ่มอย่างน้อยกลุ่มละหนึ่งคน
    - ทั้งนี้ การคัดเลือกสมาชิกสภาเด็กและเยาวชนกรุงเทพมหานครให้คำนึงถึงผู้พิการและผู้ด้อยโอกาสด้วย

มาตรา ๒๘: ให้มีคณะบริหารสภาเด็กและเยาวชนกรุงเทพมหานคร ประกอบด้วยประธานสภาหนึ่งคน และผู้บริหารอีกไม่เกินยี่สิบคน ซึ่งคัดเลือกกันเองจากสมาชิกสภาเด็กและเยาวชนกรุงเทพมหานคร 
          ให้มีหน้าที่บริหารงานทั่วไปของสภาเด็กและเยาวชน และปรึกษาหารือร่วมกันเพื่อกำหนดแนวทางในการจัดกิจกรรมการพัฒนาเด็กและเยาวชนในเขตกรุงเทพมหานคร รวมทั้งดำเนินการอื่นใดที่จำเป็นเพื่อให้บรรลุวัตถุประสงค์ของพระราชบัญญัตินี้
         - ให้ผู้ว่าราชการกรุงเทพมหานคร เป็นที่ปรึกษาคณะบริหารสภาเด็กและเยาวชนกรุงเทพมหานคร และให้แต่งตั้งที่ปรึกษาคณะบริหารสภาเด็กและเยาวชนกรุงเทพมหานคร จากผู้อำนวยการสำนักพัฒนาสังคม ผู้อำนวยการสำนักวัฒนธรรม กีฬา และการท่องเที่ยว
           ผู้อำนวยการสำนักการศึกษา ผู้แทนกรมกิจการเด็กและเยาวชน ผู้แทนหน่วยงานของรัฐหรือเจ้าหน้าที่ของรัฐที่เกี่ยวข้องกับการส่งเสริมการพัฒนาเด็กและเยาวชน และผู้แทนองค์กรภาคประชาสังคมที่มีกิจกรรมหรือผลงานเกี่ยวกับการพัฒนาเด็กและเยาวชน ทั้งนี้ ให้เป็นไปตามที่คณะบริหารสภาเด็กและเยาวชนกรุงเทพมหานครเสนอ

มาตรา ๒๙: สภาเด็กและเยาวชนจังหวัดและสภาเด็กและเยาวชนกรุงเทพมหานคร มีอำนาจหน้าที่ ดังต่อไปนี้
    (๑) ประสานงานระหว่างสภาเด็กและเยาวชนจังหวัด สภาเด็กและเยาวชนกรุงเทพมหานคร และสภาเด็กและเยาวชนแห่งประเทศไทย เพื่อแลกเปลี่ยนความรู้และประสบการณ์ในด้านต่าง ๆ ของเด็กและเยาวชน
    (๒) ส่งเสริม สนับสนุน และเป็นศูนย์กลางการเรียนรู้ด้านวิชาการ การศึกษา สุขภาพ กีฬา อาชีพ และวัฒนธรรมในท้องถิ่นของเด็กและเยาวชน
    (๓) ส่งเสริม สนับสนุน ให้เด็กและเยาวชนได้แสดงความคิดเห็นหรือแสดงออกอย่างสอดคล้องกับความรู้ความสามารถที่พัฒนาไปตามวัยของเด็กหรือเยาวชน โดยเฉพาะเรื่องที่มีผลกระทบต่อเด็กและเยาวชน
    (๔) จัดกิจกรรมต่าง ๆ เพื่อส่งเสริมและพัฒนาเด็กและเยาวชนในท้องถิ่นให้มีความรู้ความสามารถ รวมทั้งคุณธรรมและจริยธรรม
    (๕) รวบรวมข้อมูล ข้อเสนอแนะ หรือประเมินเรื่องที่มีผลกระทบต่อเด็กและเยาวชนในเขตพื้นที่ เพื่อส่งต่อข้อมูลดังกล่าวให้กับสภาเด็กและเยาวชนแห่งประเทศไทย
    (๖) เสนอความเห็นต่อหน่วยงานที่เกี่ยวข้องกับกิจกรรมการส่งเสริมและพัฒนาเด็กและเยาวชน รวมทั้งการแก้ไขปัญหาที่มีผลกระทบต่อเด็กและเยาวชนในเขตพื้นที่
    (๗) เสนอแนะและให้ความเห็นต่อสภาเด็กและเยาวชนแห่งประเทศไทย เกี่ยวกับการส่งเสริมและพัฒนาเด็กและเยาวชนในท้องถิ่น
    (๘) เสนอความเห็นต่อคณะกรรมการเกี่ยวกับการปฏิบัติงานของหน่วยงานของรัฐและองค์กรเอกชนหรือองค์กรชุมชนที่เกี่ยวข้องกับเด็กและเยาวชนในเขตพื้นที่
    (๙) ออกข้อบังคับเกี่ยวกับการประชุมและการดำเนินงานตามอำนาจหน้าที่ โดยให้คณะบริหารสภาเด็กและเยาวชนจังหวัดหรือคณะบริหารสภาเด็กและเยาวชนกรุงเทพมหานคร แล้วแต่กรณี เป็นผู้เสนอ ทั้งนี้ ให้สอดคล้องกับข้อบังคับของสภาเด็กและเยาวชนแห่งประเทศไทย

  
มาตรา ๓๐: การจัดตั้ง โครงสร้าง และที่ปรึกษาสภาเด็กและเยาวชนแห่งประเทศไทย
     องค์ประกอบสมาชิก:
    (๑) ประธานสภาเด็กและเยาวชนจังหวัดจากทุกจังหวัด
    (๒) ประธานสภาเด็กและเยาวชนกรุงเทพมหานคร
    (๓) ผู้แทนเด็กและเยาวชนที่คัดเลือกกันเองจากกลุ่มที่ลงทะเบียนตามระเบียบที่รัฐมนตรีกำหนด (คำนึงถึงความหลากหลาย ผู้พิการ และผู้ด้อยโอกาส) จำนวน ๓๘ คน
    คณะบริหาร: มีประธานสภา ๑ คน และผู้บริหารอีกไม่เกิน ๒๕ คน ซึ่งคัดเลือกกันเองจากสมาชิก
    หน้าที่: บริหารงานทั่วไป, เสนอแผนงาน/แนวปฏิบัติต่อกรมกิจการเด็กและเยาวชนเพื่อจัดทำแผนพัฒนาเด็กและเยาวชนแห่งชาติ, ทำหน้าที่เป็นผู้แทนหรือพิจารณาคัดเลือกผู้แทนดำเนินกิจกรรมทั้งในและต่างประเทศ
    ที่ปรึกษาคณะบริหาร: คณะกรรมการแต่งตั้งตามที่คณะบริหารเสนอ จากผู้แทนหน่วยงานต่าง ๆ ได้แก่ กระทรวงยุติธรรม, กระทรวงศึกษาธิการ, กระทรวงวัฒนธรรม, สำนักงานอัยการสูงสุด, กรมกิจการเด็กและเยาวชน, หน่วยงานรัฐที่เกี่ยวข้อง และผู้แทนภาคประชาสังคม

มาตรา ๓๑: อำนาจหน้าที่ของสภาเด็กและเยาวชนแห่งประเทศไทย
    (๑) เป็นศูนย์กลางประสานงานเพื่อดำเนินกิจกรรมส่งเสริมและพัฒนาเด็กและเยาวชน
    (๒) ให้ความร่วมมือในการดำเนินงานของภาครัฐ องค์กรเอกชน และองค์กรชุมชน
    (๓) ส่งเสริม สนับสนุนให้เด็กและเยาวชนได้แสดงความคิดเห็นหรือแสดงออกอย่างเหมาะสมตามวัย โดยเฉพาะเรื่องที่มีผลกระทบต่อตนเอง
    (๔) ให้ความเห็นในการกำหนดแนวทาง นโยบาย แผนงาน และงบประมาณของหน่วยงานของรัฐเพื่อการส่งเสริมและพัฒนาเด็กและเยาวชน
    (๕) รวบรวมข้อมูล ข้อเสนอแนะ หรือประเมินเรื่องที่มีผลกระทบต่อเด็กและเยาวชน และข้อมูลที่ถูกส่งต่อมายังสภาเด็กและเยาวชนแห่งประเทศไทย เพื่อเสนอคณะกรรมการพิจารณาเป็นแนวทางในการส่งเสริมและพัฒนาเด็กและเยาวชน
    (๖) เสนอความเห็นต่อหน่วยงานที่เกี่ยวข้องกับกิจกรรมการส่งเสริมและพัฒนาเด็กและเยาวชน รวมทั้งการแก้ไขปัญหาที่มีผลกระทบต่อเด็กและเยาวชน
    (๗) เสนอความเห็นต่อคณะกรรมการเกี่ยวกับการปฏิบัติงานของหน่วยงานของรัฐและองค์กรเอกชนหรือองค์กรชุมชนที่เกี่ยวข้องกับเด็กและเยาวชน
    (๘) จัดทำประมวลจริยธรรมของสมาชิกสภาเด็กและเยาวชน
    (๙) ออกข้อบังคับเกี่ยวกับการประชุมและการดำเนินงานตามอำนาจหน้าที่ โดยให้คณะบริหารสภาเด็กและเยาวชนแห่งประเทศไทยเป็นผู้เสนอ
    - สภาเด็กและเยาวชนแห่งประเทศไทยต้องจัดให้มีการประชุมสามัญอย่างน้อยปีละสองครั้ง

มาตรา ๓๒: คณะบริหารต้องมีคุณสมบัติและไม่มีลักษณะต้องห้าม ดังต่อไปนี้
    (๑) มีอายุไม่เกินยี่สิบห้าปี
    (๒) ไม่เป็นผู้ดำรงตำแหน่งในทางการเมือง กรรมการหรือผู้ดำรงตำแหน่งที่รับผิดชอบในการบริหารพรรคการเมือง ที่ปรึกษาพรรคการเมือง เจ้าหน้าที่พรรคการเมือง สมาชิกสภาท้องถิ่นหรือผู้บริหารท้องถิ่น

มาตรา ๓๓: คณะบริหารมีวาระการดำรงตำแหน่งคราวละสองปีนับแต่วันที่ได้รับการคัดเลือก ประธานสภาหรือผู้บริหารในคณะบริหารซึ่งพ้นจากตำแหน่งอาจได้รับการคัดเลือกอีกได้ แต่ต้องดำรงตำแหน่งไม่เกินสองวาระติดต่อกัน
    - กรณีที่คณะบริหารพ้นจากตำแหน่งตามวาระ ให้ดำเนินการคัดเลือกใหม่ภายในหกสิบวันนับแต่วันที่คณะบริหารพ้นจากตำแหน่งตามวาระ แต่ในระหว่างที่ยังมิได้มีการคัดเลือกคณะบริหาร ให้คณะบริหารนั้นปฏิบัติหน้าที่ไปพลางก่อนจนกว่าจะได้มีการคัดเลือกคณะบริหารใหม่
    - ในวาระเริ่มแรก เมื่อคณะบริหารดำรงตำแหน่งครบหนึ่งปี ให้คณะบริหารยกเว้นประธานสภาจับสลากออกกึ่งหนึ่ง และคัดเลือกผู้บริหารใหม่แทนตำแหน่งที่ว่าง โดยผู้ที่ได้รับการคัดเลือกใหม่มีวาระการดำรงตำแหน่งสองปี

มาตรา ๓๔: นอกจากการพ้นจากตำแหน่งตามวาระ คณะบริหารพ้นจากตำแหน่ง เมื่อ
    (๑) ตาย
    (๒) ลาออก
    (๓) ขาดคุณสมบัติหรือมีลักษณะต้องห้ามตามมาตรา ๓๒
    (๔) ถูกถอดถอนจากตำแหน่งตามที่กำหนดไว้ในข้อบังคับของสภาเด็กและเยาวชน

มาตรา ๓๕: ในกรณีที่คณะบริหารของสภาเด็กและเยาวชนพ้นจากตำแหน่งก่อนครบวาระ ให้มีการคัดเลือกผู้อื่นแทนตำแหน่งที่ว่าง 
          เว้นแต่วาระของผู้ที่พ้นจากตำแหน่งเหลือไม่ถึงเก้าสิบวัน อาจคัดเลือกผู้อื่นแทนตำแหน่งที่ว่างนั้นก็ได้ และให้ผู้ที่ได้รับการคัดเลือกแทนตำแหน่งที่ว่าง อยู่ในตำแหน่งเท่ากับวาระที่เหลืออยู่ของผู้ซึ่งตนแทน

มาตรา ๓๖: ให้กรมกิจการเด็กและเยาวชนดำเนินการส่งเสริม สนับสนุน และประสานงานการจัดตั้งและการดำเนินกิจการของสภาเด็กและเยาวชนตำบล สภาเด็กและเยาวชนเทศบาล สภาเด็กและเยาวชนอำเภอ สภาเด็กและเยาวชนจังหวัด และสภาเด็กและเยาวชนแห่งประเทศไทย
    - ให้กรมกิจการเด็กและเยาวชนร่วมกับกรุงเทพมหานครดำเนินการส่งเสริม สนับสนุนและประสานงานการจัดตั้งและการดำเนินกิจการของสภาเด็กและเยาวชนเขตและสภาเด็กและเยาวชนกรุงเทพมหานคร

มาตรา ๓๗: การประชุมของสภาเด็กและเยาวชน ต้องมีสมาชิกมาประชุมไม่น้อยกว่ากึ่งหนึ่งของจำนวนสมาชิกทั้งหมดจึงจะเป็นองค์ประชุม ทั้งนี้ ให้การประชุมของสภาเด็กและเยาวชนเป็นไปตามระเบียบที่รัฐมนตรีกำหนด
    - การวินิจฉัยชี้ขาดของที่ประชุมให้ถือเสียงข้างมาก สมาชิกสภาเด็กและเยาวชนคนหนึ่งให้มีเสียงหนึ่งในการลงคะแนน ถ้าคะแนนเสียงเท่ากันให้ประธานในที่ประชุมออกเสียงเพิ่มขึ้นอีกเสียงหนึ่งเป็นเสียงชี้ขาด

มาตรา ๓๘: การดำเนินงานของสภาเด็กและเยาวชน และคณะบริหารสภาเด็กและเยาวชน ให้เป็นไปตามข้อบังคับที่สภาเด็กและเยาวชนได้กำหนดไว้
          ทั้งนี้ ให้สภาเด็กและเยาวชนจัดให้มีการประชุมสามัญอย่างน้อยปีละหนึ่งครั้ง เว้นแต่สภาเด็กและเยาวชนแห่งประเทศไทยตามมาตรา ๓๑ วรรคสอง และให้คณะบริหารสภาเด็กและเยาวชนจัดให้มีการประชุมอย่างน้อยปีละสองครั้ง”

มาตรา ๑๐: ในวาระเริ่มแรก ให้มีการดำเนินการดังต่อไปนี้
    (๑) ให้มีสภาเด็กและเยาวชนตำบลหรือสภาเด็กและเยาวชนเทศบาลตามมาตรา ๒๒ ให้แล้วเสร็จภายในหนึ่งร้อยยี่สิบวันนับแต่วันที่พระราชบัญญัตินี้ใช้บังคับ
    (๒) ให้มีสภาเด็กและเยาวชนเขตตามมาตรา ๒๔ ให้แล้วเสร็จภายในหนึ่งร้อยห้าสิบวันนับแต่วันที่พระราชบัญญัตินี้ใช้บังคับ
    (๓) ให้มีสภาเด็กและเยาวชนกรุงเทพมหานครตามมาตรา ๒๘ ให้แล้วเสร็จภายในหนึ่งร้อยแปดสิบวันนับแต่วันที่พระราชบัญญัตินี้ใช้บังคับ

มาตรา ๑๑: ให้สภาเด็กและเยาวชนอำเภอ สภาเด็กและเยาวชนจังหวัด สภาเด็กและเยาวชนกรุงเทพมหานคร และสภาเด็กและเยาวชนแห่งประเทศไทยตามพระราชบัญญัติส่งเสริมการพัฒนาเด็กและเยาวชนแห่งชาติ พ.ศ. ๒๕๕๐ 
          ที่มีอยู่ในวันก่อนวันที่พระราชบัญญัตินี้ใช้บังคับ เป็นสภาเด็กและเยาวชนอำเภอ สภาเด็กและเยาวชนจังหวัด สภาเด็กและเยาวชนกรุงเทพมหานคร และสภาเด็กและเยาวชนแห่งประเทศไทยตามพระราชบัญญัติส่งเสริมการพัฒนาเด็กและเยาวชนแห่งชาติ พ.ศ. ๒๕๕๐ ซึ่งแก้ไขเพิ่มเติมโดยพระราชบัญญัตินี้

มาตรา ๑๒: ให้คณะบริหารสภาเด็กและเยาวชนอำเภอ คณะบริหารสภาเด็กและเยาวชนจังหวัด คณะบริหารสภาเด็กและเยาวชนกรุงเทพมหานคร
          คณะบริหารสภาเด็กและเยาวชนแห่งประเทศไทยตามพระราชบัญญัติส่งเสริมการพัฒนาเด็กและเยาวชนแห่งชาติ พ.ศ. ๒๕๕๐ ซึ่งดำรงตำแหน่งอยู่ในวันก่อนวันที่พระราชบัญญัตินี้ใช้บังคับ ยังคงปฏิบัติหน้าที่อยู่ต่อไปจนกว่าจะมีการคัดเลือกคณะบริหารสภาเด็กและเยาวชนอำเภอ 
          คณะบริหารสภาเด็กและเยาวชนจังหวัด คณะบริหารสภาเด็กและเยาวชนกรุงเทพมหานคร และคณะบริหารสภาเด็กและเยาวชนแห่งประเทศไทยตามพระราชบัญญัติส่งเสริมการพัฒนาเด็กและเยาวชนแห่งชาติ พ.ศ. ๒๕๕๐ ซึ่งแก้ไขเพิ่มเติมโดยพระราชบัญญัตินี้

มาตรา ๑๓: ให้รัฐมนตรีว่าการกระทรวงการพัฒนาสังคมและความมั่นคงของมนุษย์รักษาการตามพระราชบัญญัตินี้


**พระราชบัญญัติการรับเด็กเป็นบุตรบุญธรรม (ฉบับที่ 3) พ.ศ. 2553 **

มาตรา 1: พระราชบัญญัตินี้เรียกว่า "พระราชบัญญัติการรับเด็กเป็นบุตรบุญธรรม (ฉบับที่ 3) พ.ศ. 2553"

มาตรา 2: บังคับใช้เมื่อพ้นกำหนด 180 วันนับแต่วันประกาศในราชกิจจานุเบกษาเป็นต้นไป (เริ่มบังคับใช้วันที่ 16 พฤษภาคม 2554)

มาตรา 3: ยกเลิกความในมาตรา 5 เดิม และให้ใช้ความใหม่แทน
    - มาตรา 5: เพื่อคุ้มครองเด็กที่จะเป็นบุตรบุญธรรม การขอรับเด็กเป็นบุตรบุญธรรม การจดทะเบียนรับเด็กเป็นบุตรบุญธรรม และการเลิกรับเด็กเป็นบุตรบุญธรรม ให้เป็นไปตามหลักเกณฑ์ วิธีการ และเงื่อนไขที่กำหนดไว้ในพระราชบัญญัตินี้
    - วรรคสอง: การขอรับเด็กเป็นบุตรบุญธรรมตามวรรคหนึ่ง ต้องจัดให้มีการเตรียมความพร้อมในการรับเด็กเป็นบุตรบุญธรรมแก่ผู้ขอรับเด็กเป็นบุตรบุญธรรมและเด็กที่จะเป็นบุตรบุญธรรมตามหลักเกณฑ์ วิธีการ และเงื่อนไขที่คณะกรรมการกำหนด

มาตรา 4: ให้เพิ่มความต่อไปนี้เป็นมาตรา 5/1
    - มาตรา 5/1: การรับเด็กเป็นบุตรบุญธรรมในต่างประเทศซึ่งเป็นประเทศที่เป็นภาคีแห่งอนุสัญญาว่าด้วยการคุ้มครองเด็กและความร่วมมือในการรับรองบุตรบุญธรรมระหว่างประเทศ 
      โดยหน่วยงานซึ่งมีอำนาจของประเทศดังกล่าวรับรองว่าได้ปฏิบัติตามอนุสัญญาข้างต้นแล้ว และการรับบุตรบุญธรรมนั้นไม่ขัดต่อกฎหมาย หรือความสงบเรียบร้อยหรือศีลธรรมอันดีของประชาชน 
      ให้ถือว่าเป็นการรับเด็กเป็นบุตรบุญธรรมตามพระราชบัญญัตินี้
   
    - วรรคสอง: ให้รัฐมนตรีมีอำนาจประกาศรายชื่อประเทศภาคีแห่งอนุสัญญาว่าด้วยการคุ้มครองเด็กและความร่วมมือในการรับรองบุตรบุญธรรมระหว่างประเทศในราชกิจจานุเบกษา
มาตรา 5: ให้เพิ่มความต่อไปนี้เป็นมาตรา 18/1
    - มาตรา 18/1: ห้ามมิให้ผู้ใดใช้อุบายหลอกลวง ขู่เข็ญ ใช้กำลังประทุษร้าย ใช้อำนาจครอบงำผิดคลองธรรม 
      หรือใช้วิธีข่มขืนใจด้วยประการอื่นใด หรือเป็นคนกลางกระทำการชักจูงโดยให้ค่าจ้างหรือค่าตอบแทนหรือประโยชน์อย่างอื่นอันมิควรได้ เพื่อให้ได้มาซึ่งความยินยอมในการรับเด็กเป็นบุตรบุญธรรม

มาตรา 6: ให้เพิ่มความต่อไปนี้เป็นวรรคสองของมาตรา 21
    - มาตรา 21 วรรคสอง: การสอบคุณสมบัติและข้อเท็จจริงเกี่ยวกับสภาพความเป็นอยู่และความเหมาะสมของบุคคลตามวรรคหนึ่ง ให้เป็นไปตามที่กำหนดในกฎกระทรวง

มาตรา 7: ให้เพิ่มความต่อไปนี้เป็นวรรคสองของมาตรา 29
    - มาตรา 29 วรรคสอง: ในกรณีมีพฤติการณ์พิเศษที่ทำให้ไม่อาจดำเนินการจดทะเบียนภายในกำหนดเวลาตามวรรคหนึ่งได้ 
      ให้ผู้ขอรับเด็กเป็นบุตรบุญธรรมยื่นคำร้องแสดงพฤติการณ์พิเศษต่อคณะกรรมการตามหลักเกณฑ์และวิธีการที่คณะกรรมการกำหนด 
      และคณะกรรมการอาจพิจารณาขยายระยะเวลาการดำเนินการจดทะเบียนรับเด็กเป็นบุตรบุญธรรมออกไปอีกไม่เกิน 3 เดือนนับแต่วันที่พฤติการณ์พิเศษนั้นได้สิ้นสุดลง

มาตรา 8: ให้เพิ่มความต่อไปนี้เป็นมาตรา 31/1
    - มาตรา 31/1: ในกรณีที่ผู้รับบุตรบุญธรรมประสงค์จะเลิกรับบุตรบุญธรรม หากบุตรบุญธรรมนั้นยังเป็นเด็ก
      ก่อนที่จะมีการขอจดทะเบียนเลิกรับบุตรบุญธรรมหรือก่อนที่จะยื่นคำร้องต่อศาลตามมาตรา 1598/31 แห่งประมวลกฎหมายแพ่งและพาณิชย์
      ผู้รับบุตรบุญธรรมจะต้องแจ้งให้พนักงานเจ้าหน้าที่ทราบเพื่อดำเนินการแก้ไขปัญหาและพัฒนาความสัมพันธ์ในเบื้องต้น และจะต้องเข้าสู่กระบวนการให้คำปรึกษาเยียวยาก่อน ทั้งนี้ ตามหลักเกณฑ์และวิธีการที่กำหนดในกฎกระทรวง
    - วรรคสอง: ในกรณีที่มีการเลิกรับบุตรบุญธรรม หากบุตรบุญธรรมนั้นยังเป็นเด็ก และเด็กนั้นเคยอยู่ในความปกครองของสถานสงเคราะห์ในขณะที่มีการจดทะเบียนรับเด็กเป็นบุตรบุญธรรมหรือไม่มีบิดามารดาหรือผู้ปกครองที่จะดูแลเด็กนั้นต่อไป
      ให้พนักงานเจ้าหน้าที่ดำเนินการเพื่อจัดให้เด็กได้รับการสงเคราะห์หรือคุ้มครองสวัสดิภาพตามกฎหมายว่าด้วยการคุ้มครองเด็ก โดยผู้รับบุตรบุญธรรมที่เลิกรับบุตรบุญธรรมนั้นยังคงมีหน้าที่ในการเสียค่าใช้จ่ายในการอุปการะเลี้ยงดูและการศึกษาตามสมควรและความสามารถของตนจนกว่าเด็กนั้นจะบรรลุนิติภาวะ 
      และจำต้องเสียค่าใช้จ่ายในการอุปการะเลี้ยงดูต่อไปหากเด็กนั้นเป็นคนพิการหรือทุพพลภาพและหาเลี้ยงตนเองไม่ได้แม้ว่าจะบรรลุนิติภาวะแล้ว เว้นแต่ในกรณีที่บุตรบุญธรรมกระทำการต้องด้วยมาตรา 1598/33 (1) (2) (3) หรือ (6) แห่งประมวลกฎหมายแพ่งและพาณิชย์ หรือมีผู้รับบุตรบุญธรรมผู้อื่นรับอุปการะเลี้ยงดู 
      บุตรบุญธรรมผู้นั้นไม่มีสิทธิได้ค่าอุปการะเลี้ยงดูตามความในมาตรานี้ ทั้งนี้ ในการเรียกร้องค่าใช้จ่ายในการอุปการะเลี้ยงดูและการศึกษาดังกล่าว ให้พนักงานเจ้าหน้าที่เป็นผู้ดำเนินการและพนักงานอัยการจะฟ้องคดีแทนก็ได้    

มาตรา 9: ให้ยกเลิกความในมาตรา 34 เดิม และให้ใช้ความใหม่แทน
    - มาตรา 34: ผู้ใดฝ่าฝืนมาตรา 6 หรือมาตรา 18 ต้องระวางโทษจำคุกไม่เกิน 3 ปี หรือปรับไม่เกิน 60,000 บาท หรือทั้งจำทั้งปรับ

มาตรา 10: ให้เพิ่มความต่อไปนี้เป็นมาตรา 35/1
    - มาตรา 35/1: ผู้ใดฝ่าฝืนมาตรา 18/1 ต้องระวางโทษจำคุกตั้งแต่ 4 ปี ถึง 20 ปี หรือปรับตั้งแต่ 80,000 บาท ถึง 200,000 บาท หรือทั้งจำทั้งปรับ

มาตรา 11: ให้เพิ่มความต่อไปนี้เป็นมาตรา 38/1
    - มาตรา 38/1: ผู้ใดกระทำความผิดตามที่บัญญัติไว้ในมาตรา 6 มาตรา 18 หรือมาตรา 18/1 นอกราชอาณาจักร โดยรัฐบาลไทยหรือคนไทยเป็นผู้เสียหาย ผู้นั้นต้องรับโทษในราชอาณาจักร และให้นำบทบัญญัติมาตรา 10 แห่งประมวลกฎหมายอาญา มาใช้บังคับโดยอนุโลม

**พระราชบัญญัติการรับเด็กเป็นบุตรบุญธรรม พ.ศ. 2522**

    พระบาทสมเด็จพระปรมินทรมหาภูมิพลอดุลยเดช มีพระบรมราชโองการโปรดเกล้าฯ ให้ประกาศว่า
    โดยที่เป็นการสมควรมีกฎหมายว่าด้วยการรับเด็กเป็นบุตรบุญธรรม
    จึงทรงพระกรุณาโปรดเกล้าฯ ให้ตราพระราชบัญญัติขึ้นไว้โดยคำแนะนำและยินยอมของสภานิติบัญญัติแห่งชาติ ทำหน้าที่รัฐสภา ดังต่อไปนี้

มาตรา 1 พระราชบัญญัตินี้เรียกว่า "พระราชบัญญัติการรับเด็กเป็นบุตรบุญธรรม พ.ศ. 2522"

มาตรา 2 พระราชบัญญัตินี้ให้ใช้บังคับเมื่อพ้นกำหนดหกสิบวันนับแต่วันถัดจากวันประกาศในราชกิจจานุเบกษาเป็นต้นไป

มาตรา 3 บรรดาบทกฎหมาย กฎ และข้อบังคับอื่นในส่วนที่มีบัญญัติไว้แล้วในพระราชบัญญัตินี้ หรือซึ่งขัดหรือแย้งกับบทแห่งพระราชบัญญัตินี้ ให้ใช้พระราชบัญญัตินี้แทน

มาตรา 4 ในพระราชบัญญัตินี้
        "เด็ก" หมายความว่า ผู้เยาว์ตามประมวลกฎหมายแพ่งและพาณิชย์
        "องค์การสวัสดิภาพเด็ก" หมายความว่า มูลนิธิ สมาคม หรือองค์การที่ก่อตั้งขึ้นตามกฎหมายโดยมีวัตถุประสงค์ในการสงเคราะห์เด็ก และปฏิบัติงานเกี่ยวกับการรับเด็กเป็นบุตรบุญธรรม
        "ศาล" หมายความว่า ศาลคดีเด็กและเยาวชนตามกฎหมายว่าด้วยการจัดตั้งศาลคดีเด็กและเยาวชน หรือศาลจังหวัดในท้องที่ที่ไม่มีศาลคดีเด็กและเยาวชน
        "พนักงานเจ้าหน้าที่" หมายความว่า ผู้ซึ่งรัฐมนตรีแต่งตั้งให้ปฏิบัติการตามพระราชบัญญัตินี้
        "อธิบดี" หมายความว่า อธิบดีกรมพัฒนาสังคมและสวัสดิการ*
        "คณะกรรมการ" หมายความว่า คณะกรรมการการรับเด็กเป็นบุตรบุญธรรม
        "รัฐมนตรี" หมายความว่า รัฐมนตรีผู้รักษาการตามพระราชบัญญัตินี้

มาตรา 5 เพื่อคุ้มครองเด็กที่จะเป็นบุตรบุญธรรม การขอรับเด็กเป็นบุตรบุญธรรมและการจดทะเบียนรับเด็กเป็นบุตรบุญธรรม ให้เป็นไปตามหลักเกณฑ์วิธีการและเงื่อนไขที่กำหนดไว้ในพระราชบัญญัตินี้

มาตรา 6: ข้อห้ามในการดำเนินงาน ห้ามมิให้บุคคลใดดำเนินการเกี่ยวกับการรับเด็กเป็นบุตรบุญธรรม ยกเว้นหน่วยงานดังต่อไปนี้:
         - กรมพัฒนาสังคมและสวัสดิการ
         - ส่วนราชการที่ได้รับมอบหมายจากกรมฯ
         - องค์การสวัสดิภาพเด็กที่ได้รับใบอนุญาตจากอธิบดี

มาตรา 7: องค์การสวัสดิภาพเด็กที่ประสงค์จะดำเนินงานด้านนี้ จะต้องยื่นคำขอรับใบอนุญาตจากอธิบดี โดยหลักเกณฑ์และเงื่อนไขการขออนุญาตให้เป็นไปตามกฎกระทรวง

มาตรา 8: การอุทธรณ์และการเพิกถอนใบอนุญาต
         - หากอธิบดีไม่อนุญาต องค์การฯ สามารถอุทธรณ์ต่อรัฐมนตรีได้ภายใน 30 วันนับแต่ได้รับแจ้ง คำสั่งของรัฐมนตรีถือเป็นที่สุด
         - หากองค์การฯ ที่ได้รับอนุญาตฝ่าฝืนเงื่อนไข หรือทำสิ่งที่เป็นภัยต่อความสงบเรียบร้อย อธิบดีมีอำนาจเพิกถอนใบอนุญาตได้ (และสามารถอุทธรณ์ได้เช่นเดียวกัน)

มาตรา 9: ให้มีการตั้ง "คณะกรรมการการรับเด็กเป็นบุตรบุญธรรม" ประกอบด้วย:
        - อธิบดี เป็นประธาน
        - ผู้แทนจากหน่วยงานต่างๆ (กระทรวงต่างประเทศ, กทม., กรมการปกครอง, ตำรวจ, อัยการ)
        - ผู้ทรงคุณวุฒิที่รัฐมนตรีแต่งตั้งอีกไม่เกิน 8 คน (โดยต้องเป็นสตรีไม่น้อยกว่ากึ่งหนึ่ง)
        - ผู้อำนวยการศูนย์อำนวยการรับเด็กเป็นบุตรบุญธรรม เป็นกรรมการและเลขานุการ

มาตรา 10: วาระของคณะกรรมการ
          - กรรมการผู้ทรงคุณวุฒิมีวาระการดำรงตำแหน่งคราวละ 2 ปี
          - หากมีการแต่งตั้งกรรมการเพิ่มหรือแทนตำแหน่งที่ว่าง ให้ผู้ที่ได้รับแต่งตั้งมีวาระเท่ากับเวลาที่เหลืออยู่ของกรรมการชุดนั้น
          - กรรมการที่พ้นจากตำแหน่ง สามารถได้รับการแต่งตั้งให้กลับมาเป็นกรรมการอีกได้


มาตรา 11: กรรมการผู้ทรงคุณวุฒิจะพ้นจากตำแหน่งในกรณีดังต่อไปนี้: 
         (1) เสียชีวิต 
         (2) ลาออกจากตำแหน่ง 
         (3) ตกเป็นบุคคลล้มละลาย 
         (4) กลายเป็นคนไร้ความสามารถ หรือคนเสมือนไร้ความสามารถ 
         (5) ต้องโทษจำคุกตามคำพิพากษาถึงที่สุด (ยกเว้นเป็นความผิดที่เกิดจากความประมาท หรือความผิดลหุโทษ)

มาตรา 12: กฎเกณฑ์การประชุมของคณะกรรมการ มีดังนี้:
         - จะต้องมีกรรมการเข้าร่วมไม่น้อยกว่ากึ่งหนึ่งของจำนวนทั้งหมด จึงจะถือว่าครบองค์ประชุม
         - ในกรณีที่ประธานไม่อยู่ ให้ที่ประชุมเลือกกรรมการท่านหนึ่งขึ้นมาทำหน้าที่เป็นประธานแทน
         - การตัดสินใจให้ยึดถือเสียงข้างมาก (กรรมการ 1 คนต่อ 1 เสียง) หากคะแนนเสียงเท่ากัน ประธานในที่ประชุมสามารถออกเสียงเพิ่มได้อีกหนึ่งเสียงเพื่อเป็นการชี้ขาด

มาตรา 13: คณะกรรมการมีอำนาจในการแต่งตั้ง "คณะอนุกรรมการ" จำนวน 1 คณะหรือหลายคณะก็ได้ เพื่อมอบหมายให้ปฏิบัติหน้าที่เฉพาะอย่างใดอย่างหนึ่ง 
          โดยให้นำหลักเกณฑ์การประชุมตามมาตรา 12 มาใช้บังคับกับคณะอนุกรรมการด้วย

มาตรา 14: คณะกรรมการมีอำนาจและหน้าที่หลัก 4 ประการ ดังนี้:
         (1) ออกระเบียบ ข้อบังคับ และวิธีปฏิบัติเกี่ยวกับการรับเด็กเป็นบุตรบุญธรรม เพื่อเป็นแนวทางให้ศูนย์อำนวยการฯ, องค์การสวัสดิภาพเด็ก, และหน่วยงานที่เกี่ยวข้องนำไปปฏิบัติ
         (2) ทำหน้าที่พิจารณาและลงมติในเรื่องการรับเด็กเป็นบุตรบุญธรรม
         (3) พิจารณาแก้ไขเรื่องที่มีปัญหาเกี่ยวกับการรับเด็กเป็นบุตรบุญธรรม
         (4) คอยให้คำแนะนำด้านการรับบุตรบุญธรรมแก่ศูนย์อำนวยการฯ, องค์การสวัสดิภาพเด็ก, และหน่วยงานอื่นๆ ที่เกี่ยวข้อง

มาตรา 15: กำหนดให้ "ศูนย์อำนวยการรับเด็กเป็นบุตรบุญธรรม" ซึ่งจัดตั้งขึ้นในกรมพัฒนาสังคมและสวัสดิการ ทำหน้าที่เป็นสำนักงานเลขานุการให้แก่คณะกรรมการ

มาตรา 16: เพื่อให้การปฏิบัติงานเป็นไปตามกฎหมาย อธิบดี, ผู้ว่าราชการจังหวัด, หรือพนักงานเจ้าหน้าที่ มีอำนาจดังต่อไปนี้:
         (1) อำนาจการเข้าตรวจสอบและตรวจค้น: สามารถเข้าไปในสถานที่อยู่อาศัยของบิดามารดา, ผู้ปกครอง, ผู้ขอรับบุตรบุญธรรม
            ,สถานสงเคราะห์, สถานรับเลี้ยงเด็ก หรือสำนักงานขององค์การสวัสดิภาพเด็กได้ในเวลากลางวัน (พระอาทิตย์ขึ้นถึงพระอาทิตย์ตก) 
             เพื่อพบปะ, สอบถาม, รวบรวมเอกสาร/หลักฐานเกี่ยวกับสภาพความเป็นอยู่และการเลี้ยงดูเด็ก รวมถึงมีอำนาจตรวจค้นเพื่อหาตัวเด็กหรือนำเด็กกลับคืน 
            *เงื่อนไขสำคัญ:* การตรวจค้นในสถานที่ดังกล่าวต้องมี "หนังสืออนุญาต" จากอธิบดีหรือผู้ว่าราชการจังหวัดมาแสดงให้เจ้าของสถานที่ดูก่อนเสมอ 
            (ยกเว้นกรณีที่อธิบดีหรือผู้ว่าราชการจังหวัดเป็นผู้ลงพื้นที่ตรวจค้นด้วยตนเอง จะไม่ต้องใช้หนังสืออนุญาต)
         (2) อำนาจการสั่งการ: สามารถสั่งเป็นหนังสือให้บิดามารดา, ผู้ปกครอง, ผู้ที่เกี่ยวข้อง, หรือเจ้าหน้าที่ มาให้ถ้อยคำ, ส่งเอกสารหลักฐานที่จำเป็น, หรือสั่งให้นำตัวเด็กมาพบและส่งมอบเด็กคืนได้

มาตรา 17: กำหนดให้พนักงานเจ้าหน้าที่ที่ปฏิบัติงานตามกฎหมายฉบับนี้ มีสถานะเป็น "เจ้าพนักงาน" ตามประมวลกฎหมายอาญา

มาตรา 18: ห้ามมิให้บุคคลใดพาเด็กหรือจัดส่งเด็กออกไปต่างประเทศ โดยมีวัตถุประสงค์เพื่อการรับเด็กเป็นบุตรบุญธรรม ไม่ว่าจะโดยทางตรงหรือทางอ้อมก็ตาม (ยกเว้นว่าจะได้รับอนุญาตจากรัฐมนตรี ตามหลักเกณฑ์และเงื่อนไขที่กำหนดไว้ในกฎกระทรวง)

มาตรา 19: กระบวนการรับเด็กเป็นบุตรบุญธรรม จะต้องผ่าน "การทดลองเลี้ยงดู" และได้รับการอนุมัติให้รับเป็นบุตรบุญธรรมตามกฎหมายเสียก่อน
         *ข้อยกเว้น:* เงื่อนไขเรื่องการทดลองเลี้ยงดู จะไม่นำมาบังคับใช้หากผู้ที่ขอรับอุปการะเด็กเป็นญาติ ได้แก่ พี่ร่วมบิดามารดา, พี่ร่วมบิดาหรือมารดาเดียวกัน
         ,ทวด, ปู่, ย่า, ตา, ยาย, ลุง, ป้า, น้า, อา หรือเป็นผู้ปกครองเดิมของเด็ก หรือเป็นบุคคลอื่นตามที่กฎกระทรวงกำหนดไว้


มาตรา 20: ขั้นตอนและสถานที่ยื่นคำขอรับเด็กเป็นบุตรบุญธรรม
- ผู้ที่มีความประสงค์จะขอรับเด็กเป็นบุตรบุญธรรม จะต้องยื่นคำขอพร้อมกับแนบ "หนังสือแสดงความยินยอม" จากบุคคลที่มีอำนาจตามกฎหมายในการให้ความยินยอมรับเด็กเป็นบุตรบุญธรรม โดยต้องปฏิบัติตามหลักเกณฑ์และเงื่อนไขที่กฎกระทรวงกำหนด
- สถานที่ยื่นคำขอ:
  > หากผู้ยื่นคำขอมีภูมิลำเนาอยู่ในเขต กรุงเทพมหานคร หรือ ต่างประเทศ ให้ยื่นเรื่องต่อ "อธิบดี"
  > หากผู้ยื่นคำขอมีภูมิลำเนาอยู่ใน จังหวัดอื่นๆ ให้ยื่นเรื่องต่อ "ผู้ว่าราชการจังหวัด"

มาตรา 21: การตรวจสอบคุณสมบัติโดยเจ้าหน้าที่
- หลังจากรับคำขอแล้ว พนักงานเจ้าหน้าที่จะต้องทำการตรวจสอบคุณสมบัติและค้นหาข้อเท็จจริงอย่างละเอียด ทั้งในเรื่องสภาพความเป็นอยู่ และความเหมาะสมของบุคคล 3 ฝ่าย ได้แก่: 
  1. ผู้ขอรับเด็กเป็นบุตรบุญธรรม 
  2. ผู้มีอำนาจให้ความยินยอม 
  3. เด็กที่จะไปเป็นบุตรบุญธรรม

มาตรา 22: เมื่ออธิบดีหรือผู้ว่าราชการจังหวัด แล้ว แต่กรณี ได้พิจารณารายงานการสอบคุณสมบัติและข้อเท็จจริงหรือเอกสารแสดงข้อเท็จจริง
ตามมาตรา ๒๐และมาตรา ๒๑ แล้ว ให้พิจารณาว่าจะควรให้ผู้ขอรับเด็กไปทดลองเลี้ยงดูต่อไปหรือไม่
ถ้าอธิบดีหรือผู้ว่าราชการจังหวัดมีคำสั่งว่าไม่ควรให้นำเด็กไปทดลองเลี้ยงดู ผู้ขอรับเด็กเป็นบุตรบุญธรรมอาจอุทธรณ์คำสั่งดังกล่าวโดยทำเป็นคำร้องยื่นต่อ
ศาลภายในหกสิบวันนับแต่วันทราบคำสั่ง คำสั่งของศาลชั้นต้นให้เป็นที่สุด

มาตรา ๒๓ เมื่ออธิบดีหรือผู้ว่าราชการจังหวัดมีคำสั่งให้ทดลองเลี้ยงดูเด็กแล้วให้ผู้ขอรับเด็กรับมอบเด็กที่จะรับเป็นบุตรบุญธรรมไปทดลองเลี้ยงดูได้ในกฎกระทรวง
การทดลองเลี้ยงดูต้องมีระยะเวลาไม่น้อยกว่าหกเดือนหลักเกณฑ์ วิธีการและเงื่อนไขในการทดลองเลี้ยงดูให้เป็นไปตามที่กำหนด


มาตรา ๒๔ ในระหว่างการทดลองเลี้ยงดู ถ้าผู้ขอรับเด็กเป็นบุตร
บุญธรรมถอนคำขอรับเด็กเป็นบุตรบุญธรรม ให้ผู้ขอรับเด็กเป็นบุตรบุญธรรมมอบเด็กคืน แก่บุคคลผู้มีอำนาจให้ความยินยอมในการรับเด็กเป็นบุตรบุญธรรมหรือพนักงานเจ้าหน้าที่
การมอบเด็กคืนตามวรรคหนึ่งต้องกระทำโดยไม่ชักช้า ให้อธิบดีหรือผู้ว่า
ราชการจังหวัด แล้วแต่กรณี มีคำสั่งเป็นหนังสือแจ้งให้ผู้ขอรับเด็กเป็นบุตรบุญธรรมนำเด็ก
ไปมอบคืนตามกำหนดโดยให้คำนึงถึงระยะทาง ความสะดวกในการนำเด็กไปมอบ และ
สวัสดิภาพของเด็ก

มาตรา ๒๕ ในระหว่างการทดลองเลี้ยงดู บิดาหรือมารดาไม่ว่าจะเป็นผู้ให้ความยินยอมหรือไม่อาจขอให้ยกเลิกคำขอรับเด็กเป็นบุตรบุญธรรมนั้นเสียก็ได้โดยยื่น
         คำขอต่ออธิบดี หรือผู้ว่าราชการจังหวัด แล้วแต่กรณี ถ้าอธิบดีหรือผู้ว่าราชการจังหวัดสั่งให้ยกเลิกคำขอรับเด็กเป็นบุตรบุญธรรม ให้ผู้ขอรับเด็กเป็นบุตรบุญธรรมมอบเด็กคืนแก่
         บิดามารดา ซึ่งเป็นผู้ขอยกเลิกและให้นำความในมาตรา ๒๔ วรรคสอง มาใช้บังคับโดยอนุโลม
         ในกรณีที่อธิบดีหรือผู้ว่าราชการจังหวัดเห็นว่าการขอยกเลิกคำขอรับเด็กเป็นบุตรบุญธรรมเป็นปฏิปักษ์ต่อสวัสดิภาพของเด็ก หรือบิดาหรือมารดาที่เป็นผู้ขอยกเลิกนั้น 
         ได้ถูกศาลสั่งถอนอำนาจปกครองแล้ว ให้ผู้ขอรับเด็กเป็นบุตรบุญธรรมทดลองเลี้ยงดู
         เด็กต่อไป ผู้ยื่นคำขอตามวรรคหนึ่งอาจอุทธรณ์คำสั่งของอธิบดีหรือผู้ว่าราชการจังหวัดโดยทำเป็นคำร้องยื่นต่อศาลภายในสามสิบวันนับแต่วันทราบคำสั่งดังกล่าว คำสั่งของศาลชั้นต้นให้เป็นที่สุด

มาตรา ๒๖ ในระหว่างการทดลองเลี้ยงดู ถ้าพนักงานเจ้าหน้าที่ร้องขอต่ออธิบดีหรือผู้ว่าราชการจังหวัด 
         แล้วแต่กรณี ว่าผู้ขอรับเด็กเป็นบุตรบุญธรรมไม่เหมาะสมที่จะรับเด็กเป็นบุตรบุญธรรม 
         เมื่ออธิบดีหรือผู้ว่าราชการจังหวัดมีคำสั่งให้เลิกการทดลองเลี้ยงดูให้ผู้ขอรับเด็กเป็นบุตรบุญธรรมมอบเด็กแก่พนักงานเจ้าหน้าที่ 
         และให้นำความในมาตรา ๒๔ วรรคสอง มาใช้บังคับโดยอนุโลม

          ผู้ขอรับเด็กเป็นบุตรบุญธรรมอาจอุทธรณ์คำสั่งของอธิบดีหรือผู้ว่าราชการจังหวัดตามวรรคหนึ่ง 
          โดยทำเป็นคำร้องยื่นต่อศาลภายในสามสิบวันนับแต่วันได้รับแจ้งคำสั่งดังกล่าว คำสั่งของศาลชั้นต้นตามวรรคสองให้เป็นที่สุด

มาตรา ๒๗ เมื่อได้มีการทดลองเลี้ยงดูครบกำหนดแล้ว ปรากฏว่าผู้ขอรับ เด็กเป็นบุตรบุญธรรมเหมาะสมที่จะรับเด็กเป็นบุตรบุญธรรม และคณะกรรมการสั่งอนุมัติ
         ให้รับเด็กเป็นบุตรบุญธรรม ให้ดำเนินการขอจดทะเบียนรับเด็กเป็นบุตรบุญธรรมได้ตามกฎหมายว่าด้วยการนั้น

         เพื่อประโยชน์ในการดำเนินการขอจดทะเบียนรับเด็กเป็นบุตรบุญธรรม ให้
         ถือว่าความยินยอมของบุคคลผู้มีอำนาจให้ความยินยอมในการรับเด็กเป็นบุตรบุญธรรมที่
         ยื่นตามมาตรา ๒๐ เป็นความยินยอมในการจดทะเบียน

มาตรา ๒๔ เมื่อได้มีการทดลองเลี้ยงดูครบกำหนดแล้ว ปรากฏว่าผู้ขอรับเด็กเป็นบุตรบุญธรรมไม่เหมาะสมที่จะรับเด็กเป็นบุตรบุญธรรม และคณะกรรมการสั่งไม่
         อนุมัติให้รับเด็กเป็นบุตรบุญธรรม ให้อธิบดีหรือผู้ว่าราชการจังหวัด แล้วแต่กรณี สั่งให้ผู้ขอรับเด็กเป็นบุตรบุญธรรมมอบเด็กนั้นคืนแก่บุคคลผู้มีอำนาจให้ความยินยอมในการรับ
         เด็กเป็นบุตรบุญธรรม บิดามารดา ผู้ปกครอง หรือพนักงานเจ้าหน้าที่ ในกรณีเช่นนี้ผู้ขอรับเด็กเป็นบุตรบุญธรรมต้องมอบเด็กคืน และให้นำความในมาตรา ๒๔ วรรคสองมาใช้บังคับ
         โดยอนุโลม       

         ผู้ขอรับเด็กเป็นบุตรบุญธรรมอาจอุทธรณ์คำสั่งของคณะกรรมการตาม วรรคหนึ่งโดยทำเป็นคำร้องยื่นต่อศาลภายในสามสิบวันนับแต่วันได้รับแจ้งคำสั่งดังกล่าว

         ในระหว่างการพิจารณาของศาล ผู้ขอรับเด็กเป็นบุตรบุญธรรมอาจร้องต่อศาลให้เด็กอยู่ในความเลี้ยงดูของผู้ร้องก็ได้

         คำสั่งของศาลชั้นต้นตามวรรคสองและวรรคสามให้เป็นที่สุด

มาตรา ๒๙ เมื่อคณะกรรมการอนุมัติให้รับเด็กเป็นบุตรบุญธรรมตามมาตรา ๒๗ แล้ว หรือในกรณีที่มีการอุทธรณ์คำสั่งของคณะกรรมการตามมาตรา ๒๘ และ
         ศาลมีคำสั่งอนุญาตให้มีการรับบุตรบุญธรรมแล้ว หากผู้ขอรับเด็กเป็นบุตรบุญธรรมไม่ ดำเนินการจดทะเบียนรับเด็กเป็นบุตรบุญธรรมภายในกำหนดหกเดือนนับแต่วันที่ได้รับแจ้งคำอนุมัติของคณะกรรมการ
         หรือนับแต่วันที่ศาลมีคำสั่งให้ถือว่าผู้นั้นสละสิทธิที่จะรับเด็เป็นบุตรบุญธรรม และให้มอบเด็กคืนแก่บุคคลผู้มีอำนาจให้ความยินยอมในการรับเด็กเป็นบุตรบุญธรรมหรือพนักงานเจ้าหน้าที่ และให้นำความในมาตรา ๒๔ วรรคสองมาใช้บังคับโดยอนุโลม

มาตรา ๓๐ เมื่อมีการอุทธรณ์คำสั่งโดยทำเป็นคำร้องยื่นต่อศาลตามพระ ราชบัญญัตินี้ให้ศาลส่งสำเนาคำร้องและแจ้งวันนั่งพิจารณาให้อธิบดี ประธานกรรมการ
         หรือผู้ว่าราชการจังหวัดทราบ แล้วแต่กรณี

มาตรา ๓๑ การพิจารณาคดีและการอ่านคำสั่งศาลเกี่ยวกับการรับเด็กเป็นบุตรบุญธรรมตามพระราชบัญญัตินี้ให้กระทำโดยลับ เฉพาะบุคคลดังต่อไปนี้เท่านั้นอยู่ในห้องพิจารณาได้ คือ
         (๑) บิดามารดา ผู้ปกครอง หรือบุคคลผู้มีอำนาจให้ความยินยอมในการรับเด็กเป็นบุตรบุญธรรม และทนายความ
         (๒) ผู้ขอรับเด็กเป็นบุตรบุญธรรมและทนายความ
         (๓) ผู้คัดค้านและทนายความ
         (๔) พนักงานศาล
         (๕) พนักงานเจ้าหน้าที่และเจ้าหน้าที่ขององค์การสวัสดิภาพเด็กที่เกี่ยวข้อง
         (๖) พยาน ผู้เชี่ยวชาญ และล่าม
         (๗) บุคคลที่ศาลเรียกให้มาแถลงข้อเท็จจริง และบุคคลอื่นที่ศาลเห็นสมควรถ้าศาลเห็นว่าในขณะหนึ่งขณะใด 
             บุคคลบางคนไม่ควรอยู่ในห้องพิจารณา ให้ศาลมีอำนาจสั่งให้บุคคลทั้งหมดหรือบุคคลที่ศาลเห็นว่าไม่สมควรนั้น ออกไปนอกห้องพิจารณาก็ได้

มาตรา ๓๒ ห้ามมิให้ผู้ใดโฆษณารูป ชื่อ หรือข้อความใดซึ่งจะทำให้รู้จักตัวเด็กที่จะเป็นหรือเป็นบุตรบุญธรรม บิดามารดาหรือผู้ปกครองของเด็กที่จะเป็นหรือเป็น
         บุตรบุญธรรม หรือผู้ขอรับหรือรับเด็กเป็นบุตรบุญธรรมและห้ามมิให้โฆษณาคำสั่งศาลตามพระราชบัญญัตินี้ เว้นแต่ในกรณีที่จำเป็นต้องกระทำเพื่อประโยชน์ของทางราชการธรรมเนียมศาล

มาตรา ๓๓ การดำเนินคดีตามพระราชบัญญัตินี้ให้ได้รับยกเว้นค่า

มาตรา ๓๔ ผู้ใดฝ่าฝืนมาตรา 5 หรือมาตรา ๑๘ ต้องระวางโทษจำคุกไม่เกินสามปี หรือปรับไม่เกินสามหมื่นบาท หรือทั้งจำทั้งปรับ

มาตรา ๓๕ ผู้ใดขัดขวางหรือไม่อำนวยความสะดวกแก่ผู้ปฏิบัติหน้าที่ตามมาตรา ๑๖ (๑) หรือไม่ปฏิบัติตามคำสั่งตามมาตรา ๑๖ (๒) ต้องระวางโทษจำคุกไม่เกินสาม
         เดือน หรือปรับไม่เกินสามพันบาท หรือทั้งจำทั้งปรับ

มาตรา ๓๖ ผู้ขอรับเด็กเป็นบุตรบุญธรรมฝ่าฝืนไม่ส่งมอบเด็กคืนตามความในมาตรา ๒๔ มาตรา ๒๕ วรรคหนึ่ง มาตรา ๒๖ วรรคหนึ่ง มาตรา ๒๘ วรรคหนึ่ง
         และมาตรา ๒๙ ต้องระวางโทษจำคุกไม่เกินหกเดือน หรือปรับไม่เกินหนึ่งหมื่นบาท หรือทั้งจำทั้งปรับ

มาตรา ๓๗ ผู้ใดฝ่าฝืนมาตรา ๓๒ ต้องระวางโทษจำคุกไม่เกินหกเดือนหรือปรับไม่เกินหนึ่งหมื่นบาท หรือทั้งจำทั้งปรับ

มาตรา ๓๘ ในกรณีที่ผู้กระทำความผิดซึ่งต้องรับโทษตามพระราช บัญญัตินี้เป็นนิติบุคคล กรรมการผู้จัดการผู้จัดการ หรือผู้แทนของนิติบุคคลนั้น ต้องรับ
          โทษตามที่บัญญัติไว้สำหรับความผิดนั้น ๆ ด้วย เว้นแต่จะพิสูจน์ได้ว่าตนมิได้มีส่วนในการกระทำความผิดของนิติบุคคลนั้น

มาตรา ๓๙ ให้รัฐมนตรีว่าการกระทรวงการพัฒนาสังคมและความมั่นคง
         ของมนุษย์ รักษาการตามพระราชบัญญัตินี้และให้มีอำนาจแต่งตั้งพนักงานเจ้าหน้าที่ กับ ออกกฎกระทรวงเพื่อปฏิบัติการตามพระราชบัญญัตินี้


**พระราชบัญญัติการป้องกันและแก้ไขปัญหาการตั้งครรภ์ในวัยรุ่น พ.ศ. 2559**

มาตรา 1: พระราชบัญญัตินี้เรียกว่า "พระราชบัญญัติการป้องกันและแก้ไขปัญหาการตั้งครรภ์ในวัยรุ่น พ.ศ. 2559"

มาตรา 2: ให้ใช้บังคับเมื่อพ้นกำหนด 120 วัน นับแต่วันประกาศในราชกิจจานุเบกษาเป็นต้นไป

มาตรา 3: บทนิยามศัพท์ที่สำคัญ
           - "วัยรุ่น" หมายความว่า บุคคลอายุเกิน 10 ปีบริบูรณ์ แต่ยังไม่ถึง 20 ปีบริบูรณ์
           - "นักเรียน" หมายความว่า วัยรุ่นซึ่งกำลังรับการศึกษาขั้นพื้นฐาน ระดับประถมศึกษาและมัธยมศึกษา ทั้งประเภทสามัญและอาชีวศึกษาอยู่ในสถานศึกษาของรัฐหรือเอกชน
           - "นักศึกษา" หมายความว่า วัยรุ่นซึ่งกำลังรับการศึกษาระดับอุดมศึกษาอยู่ในสถานศึกษาของรัฐหรือเอกชน
           - "เพศวิถีศึกษา" หมายความว่า กระบวนการเรียนรู้เรื่องเพศที่ครอบคลุมถึงพัฒนาการในแต่ละช่วงวัย การมีสัมพันธภาพ 
              พฤติกรรมทางเพศ สุขภาวะทางเพศ รวมถึงสิทธิการรับรู้ข้อมูลเกี่ยวกับอนามัยการเจริญพันธุ์
           - "อนามัยการเจริญพันธุ์" หมายความว่า ภาวะความแข็งแรงสมบูรณ์ของร่างกายและจิตใจอันเกิดจากระบบสุขภาพทางเพศและการเจริญพันธุ์ตลอดช่วงชีวิต
           - "บริการอนามัยการเจริญพันธุ์" หมายความว่า การให้บริการส่งเสริม ป้องกัน รักษา และฟื้นฟูที่เกี่ยวกับอนามัยการเจริญพันธุ์
           - "การจัดสวัสดิการสังคม" หมายความว่า การจัดสวัสดิการสังคมตามกฎหมายว่าด้วยการส่งเสริมการจัดสวัสดิการสังคม
           - "สถานศึกษา" หมายความว่า สถานศึกษาตามกฎหมายว่าด้วยการศึกษาแห่งชาติ
           - "สถานบริการ" หมายความว่า สถานบริการตามกฎหมายว่าด้วยหลักประกันสุขภาพแห่งชาติ
           - "สถานประกอบกิจการ" หมายความว่า สถานที่ซึ่งผู้ประกอบกิจการใช้เป็นสถานที่ประกอบธุรกิจและมีลูกจ้างทำงานอยู่
           - "หน่วยงานของรัฐ" หมายความว่า กระทรวง ทบวง กรม ราชการส่วนภูมิภาค ราชการส่วนท้องถิ่น รัฐวิสาหกิจ องค์การมหาชน และหน่วยงานอื่นของรัฐ
           - "คณะกรรมการ" หมายความว่า คณะกรรมการป้องกันและแก้ไขปัญหาการตั้งครรภ์ในวัยรุ่น

มาตรา 4: ให้รัฐมนตรีว่าการกระทรวงการพัฒนาสังคมและความมั่นคงของมนุษย์, รัฐมนตรีว่าการกระทรวงการอุดมศึกษาฯ, รัฐมนตรีว่าการกระทรวงมหาดไทย
         ,รัฐมนตรีว่าการกระทรวงแรงงาน, รัฐมนตรีว่าการกระทรวงศึกษาธิการ และรัฐมนตรีว่าการกระทรวงสาธารณสุข รักษาการตามพระราชบัญญัตินี้ 
          และมีอำนาจออกกฎกระทรวงและระเบียบเพื่อปฏิบัติการในส่วนที่เกี่ยวข้องกับกระทรวงนั้น  
          กฎหมายกระทรวงเเละระเบียบนั้น เมื่อได้ประกาสในราชกิจจานุเบกษาเเล้วให้ใช้บังคับได้
 

  [หมวด 2: คณะกรรมการป้องกันและแก้ไขปัญหาการตั้งครรภ์ในวัยรุ่น]

มาตรา 11: ให้มีคณะกรรมการคณะหนึ่ง เรียกว่า "คณะกรรมการป้องกันและแก้ไขปัญหาการตั้งครรภ์ในวัยรุ่น" ประกอบด้วย
         (1) นายกรัฐมนตรี เป็นประธานกรรมการ
         (2) กรรมการโดยตำแหน่ง จำนวน 9 คน ได้แก่ รัฐมนตรีว่าการกระทรวงการพัฒนาสังคมและความมั่นคงของมนุษย์, 
             รัฐมนตรีว่าการกระทรวงศึกษาธิการ, รัฐมนตรีว่าการกระทรวงสาธารณสุข, ปลัดกระทรวงการอุดมศึกษา วิทยาศาสตร์ วิจัยและนวัตกรรม, ปลัดกระทรวงมหาดไทย
             ,ปลัดกระทรวงยุติธรรม, ปลัดกระทรวงแรงงาน, ปลัดกระทรวงวัฒนธรรม และปลัดกรุงเทพมหานคร
         (3) กรรมการผู้ทรงคุณวุฒิ จำนวน 5 คน ซึ่งประธานกรรมการแต่งตั้งจากผู้มีความรู้ ความเชี่ยวชาญ มีผลงาน และมีประสบการณ์เป็นที่ประจักษ์ไม่น้อยกว่า 5 ปี ในด้านการสาธารณสุข
             , ด้านการคุ้มครองสิทธิและเสรีภาพของวัยรุ่น, ด้านการศึกษา, ด้านจิตวิทยา และด้านการสังคมสงเคราะห์ (ด้านละ 1 คน)
         (4) ผู้แทนเด็กและเยาวชน จำนวน 2 คน ซึ่งประธานกรรมการแต่งตั้งจากผู้แทนสภาเด็กและเยาวชนแห่งประเทศไทย (เป็นชาย 1 คน และหญิง 1 คน)
             - ให้อธิบดีกรมอนามัย เป็นกรรมการและเลขานุการ และผู้แทนหน่วยงานที่เกี่ยวข้อง เป็นผู้ช่วยเลขานุการ
             - การแต่งตั้งกรรมการผู้ทรงคุณวุฒิให้เป็นไปตามระเบียบที่รัฐมนตรีว่าการกระทรวงสาธารณสุขกำหนด โดยคำนึงถึงสัดส่วนชายและหญิงที่ใกล้เคียงกัน

มาตรา 12: กรรมการผู้ทรงคุณวุฒิต้องมีคุณสมบัติและไม่มีลักษณะต้องห้าม ดังต่อไปนี้
         (1) มีสัญชาติไทย
         (2) มีอายุไม่ต่ำกว่า 35 ปีบริบูรณ์
         (3) ไม่เป็นบุคคลล้มละลายหรือเคยเป็นบุคคลล้มละลายทุจริต
         (4) ไม่เป็นคนไร้ความสามารถหรือคนเสมือนไร้ความสามารถ
         (5) ไม่ติดยาเสพติดให้โทษ
         (6) ไม่เคยได้รับโทษจำคุกโดยคำพิพากษาถึงที่สุดให้จำคุก (เว้นแต่ความผิดที่ได้กระทำโดยประมาทหรือความผิดลหุโทษ)
         (7) ไม่เคยต้องคำพิพากษาหรือคำสั่งของศาลให้ทรัพย์สินตกเป็นของแผ่นดินเพราะร่ำรวยผิดปกติหรือมีทรัพย์สินเพิ่มขึ้นผิดปกติ
         (8) ไม่เคยถูกไล่ออก ปลดออก ให้ออก หรือเลิกจ้างจากหน่วยงานของรัฐหรือหน่วยงานของเอกชนเพราะทุจริตต่อหน้าที่ ประพฤติชั่วอย่างร้ายแรง หรือถือว่ากระทำการทุจริตและประพฤติมิชอบในวงราชการ

มาตรา 13: วาระการดำรงตำแหน่งของกรรมการผู้ทรงคุณวุฒิ
        - มีวาระการดำรงตำแหน่งคราวละ 3 ปี นับแต่วันที่ได้รับการแต่งตั้ง 
        - ผู้ซึ่งพ้นจากตำแหน่งแล้วอาจได้รับการแต่งตั้งอีกได้ แต่จะดำรงตำแหน่งติดต่อกันเกิน 2 วาระไม่ได้
        - กรณีที่กรรมการพ้นจากตำแหน่งก่อนวาระ ให้ประธานแต่งตั้งผู้ทรงคุณวุฒิด้านเดียวกันแทน และให้อยู่ในตำแหน่งเท่ากับวาระที่เหลืออยู่ 
          (เว้นแต่วาระจะเหลือไม่ถึง 90 วัน ประธานจะไม่แต่งตั้งแทนก็ได้ และให้คณะกรรมการทำงานต่อด้วยจำนวนกรรมการที่เหลืออยู่)
        - เมื่อครบวาระ หากยังมิได้แต่งตั้งกรรมการใหม่ ให้กรรมการเดิมปฏิบัติหน้าที่ต่อไปจนกว่ากรรมการใหม่จะเข้ารับหน้าที่

มาตรา 14: นอกจากการพ้นจากตำแหน่งตามวาระ กรรมการผู้ทรงคุณวุฒิพ้นจากตำแหน่งเมื่อ
         (1) ตาย
         (2) ลาออก
         (3) ประธานกรรมการให้ออก เพราะบกพร่องต่อหน้าที่ มีความประพฤติเสื่อมเสีย หรือหย่อนความสามารถ
         (4) ขาดคุณสมบัติหรือมีลักษณะต้องห้ามตามมาตรา 12  

มาตรา 15: คุณสมบัติและการพ้นจากตำแหน่งของผู้แทนเด็กและเยาวชน
         - ผู้แทนเด็กและเยาวชนตามมาตรา 11 (4) ต้องมีอายุไม่เกิน 25 ปีบริบูรณ์
         - ต้องมีคุณสมบัติตามมาตรา 12 (1) และไม่มีลักษณะต้องห้ามตามมาตรา 12 (3) (4) (5) (6) (7) หรือ (8)
         - ให้นำมาตรา 13 มาใช้บังคับกับการดำรงตำแหน่งกรรมการของผู้แทนเด็กและเยาวชนดังกล่าวโดยอนุโลม
         - นอกจากการพ้นจากตำแหน่งตามวาระ กรรมการซึ่งเป็นผู้แทนเด็กและเยาวชนพ้นจากตำแหน่งเมื่อ ตาย หรือลาออก หรือมีอายุเกิน 25 ปีบริบูรณ์ หรือขาดคุณสมบัติ 
           หรือมีลักษณะต้องห้ามตามมาตรา 12 (1) (3) (4) (5) (6) (7) หรือ (8)

มาตรา 16: การประชุมคณะกรรมการ
         - ต้องมีกรรมการมาประชุมไม่น้อยกว่ากึ่งหนึ่งของจำนวนกรรมการทั้งหมด จึงจะเป็นองค์ประชุม
         - ถ้าประธานกรรมการไม่มาประชุมหรือไม่อาจปฏิบัติหน้าที่ได้ ให้ที่ประชุมเลือกกรรมการคนหนึ่งเป็นประธานในที่ประชุม
         - การวินิจฉัยชี้ขาดของที่ประชุมให้ถือเสียงข้างมาก กรรมการคนหนึ่งให้มีเสียงหนึ่งในการลงคะแนน ถ้าคะแนนเสียงเท่ากันให้ประธานในที่ประชุมออกเสียงเพิ่มขึ้นอีกเสียงหนึ่งเป็นเสียงชี้ขาด
         - ให้มีการประชุมคณะกรรมการอย่างน้อยปีละ 2 ครั้ง

มาตรา 17: อำนาจหน้าที่ของคณะกรรมการ
        (1) เสนอนโยบายและยุทธศาสตร์การป้องกันและแก้ไขปัญหาการตั้งครรภ์ในวัยรุ่นต่อคณะรัฐมนตรีเพื่อพิจารณา
        (2) เสนอแนวทางแก้ไขปรับปรุงกฎหมายเกี่ยวกับการป้องกันและแก้ไขปัญหาการตั้งครรภ์ในวัยรุ่นต่อคณะรัฐมนตรี รวมทั้งเสนอความเห็นต่อรัฐมนตรีในการออกกฎกระทรวงตามพระราชบัญญัตินี้
        (3) เสนอรายงานการป้องกันและแก้ไขปัญหาการตั้งครรภ์ในวัยรุ่นต่อคณะรัฐมนตรีอย่างน้อยปีละ 1 ครั้ง
        (4) กำหนดแนวทางปฏิบัติสำหรับหน่วยงานของรัฐและหน่วยงานของเอกชนเพื่อป้องกัน ช่วยเหลือ แก้ไข 
            และเยียวยาปัญหาการตั้งครรภ์ในวัยรุ่น ปัญหาอนามัยการเจริญพันธุ์ของวัยรุ่น การใช้ความรุนแรงทางเพศและการกระทำความผิดเกี่ยวกับเพศ
        (5) ให้คำปรึกษา แนะนำ และแก้ไขปัญหาข้อขัดข้องในการดำเนินการเกี่ยวกับการป้องกันและแก้ไขปัญหาการตั้งครรภ์ในวัยรุ่นแก่หน่วยงานของรัฐและหน่วยงานของเอกชน
        (6) ปฏิบัติการอื่นใดตามที่กฎหมายกำหนดให้เป็นอำนาจหน้าที่ของคณะกรรมการ หรือตามที่คณะรัฐมนตรีมอบหมาย

มาตรา 18: นโยบายและยุทธศาสตร์การป้องกันและแก้ไขปัญหาการตั้งครรภ์ในวัยรุ่นตามมาตรา 17 (1) อย่างน้อยต้องมีสาระสำคัญในเรื่อง ดังต่อไปนี้
        (1) มาตรการเกี่ยวกับการได้รับข้อมูลข่าวสารและความรู้เกี่ยวกับการป้องกันและแก้ไขปัญหาการตั้งครรภ์ในวัยรุ่น
        (2) มาตรการเกี่ยวกับการให้วัยรุ่นได้รับสิทธิตามมาตรา 5
        (3) มาตรการเกี่ยวกับการป้องกัน ช่วยเหลือ แก้ไข และเยียวยาปัญหาการตั้งครรภ์ในวัยรุ่น
        (4) มาตรการเกี่ยวกับการป้องกันและแก้ไขปัญหาการตั้งครรภ์ในวัยรุ่นในหน่วยงานของรัฐและหน่วยงานของเอกชน ให้สามารถดำเนินการได้อย่างมีเอกภาพและมีประสิทธิภาพ
             - การจัดทำนโยบายและยุทธศาสตร์ ต้องคำนึงถึงหลักการมีส่วนร่วมของประชาชน ประชาสังคม และวัยรุ่นด้วย

มาตรา 19: คณะกรรมการจะแต่งตั้งคณะอนุกรรมการเพื่อพิจารณา หรือปฏิบัติการอย่างใดอย่างหนึ่งตามที่คณะกรรมการมอบหมายก็ได้
            - การประชุมคณะอนุกรรมการ ให้นำมาตรา 16 มาใช้บังคับโดยอนุโลม

มาตรา 20: ในการปฏิบัติหน้าที่ ให้คณะกรรมการและคณะอนุกรรมการมีอำนาจออกคำสั่งเป็นหนังสือเรียกบุคคลใดมาให้ข้อเท็จจริงหรือแสดงความคิดเห็น 
          หรือให้ส่งคำชี้แจง เอกสาร ข้อมูล หลักฐาน หรือวัตถุใดที่เกี่ยวข้องมาเพื่อใช้ประกอบการพิจารณาได้

มาตรา 21: ในกรณีที่ปรากฏว่าสถานศึกษา สถานบริการ สถานประกอบกิจการ หรือหน่วยงานของรัฐไม่ดำเนินการป้องกันและแก้ไขปัญหาการตั้งครรภ์ในวัยรุ่นตามที่กำหนดในพระราชบัญญัตินี้ 
          ให้คณะกรรมการแจ้งต่อรัฐมนตรีผู้รักษาการตามกฎหมายว่าด้วยการนั้น เพื่อให้มีการดำเนินการตามพระราชบัญญัตินี้

มาตรา 22: ให้กรมอนามัย กระทรวงสาธารณสุข รับผิดชอบงานธุรการของคณะกรรมการและคณะอนุกรรมการ และให้มีอำนาจหน้าที่ ดังต่อไปนี้
         (1) จัดทำนโยบาย ยุทธศาสตร์ และรายงานการป้องกันและแก้ไขปัญหาการตั้งครรภ์ในวัยรุ่นเสนอต่อคณะกรรมการ
         (2) ประสานงาน ติดตาม ประเมินผล และร่วมมือกับหน่วยงานของรัฐและหน่วยงานของเอกชนที่เกี่ยวข้องทั้งในประเทศและต่างประเทศ 
             ให้มีการปฏิบัติตามนโยบายและยุทธศาสตร์การป้องกันและแก้ไขปัญหาการตั้งครรภ์ในวัยรุ่น
         (3) ส่งเสริมและสนับสนุนการรณรงค์และสร้างความรู้ความเข้าใจเกี่ยวกับการป้องกันและแก้ไขปัญหาการตั้งครรภ์ในวัยรุ่นและพฤติกรรมทางเพศที่เหมาะสม
         (4) เป็นศูนย์กลางฐานข้อมูลเกี่ยวกับการป้องกันและแก้ไขปัญหาการตั้งครรภ์ในวัยรุ่น และดำเนินการหรือสนับสนุนให้มีการศึกษาวิจัยในเรื่องดังกล่าว
         (5) จัดทำแนวทางปฏิบัติเกี่ยวกับการป้องกัน ช่วยเหลือ แก้ไข และเยียวยาปัญหาการตั้งครรภ์ในวัยรุ่น ปัญหาอนามัยการเจริญพันธุ์ของวัยรุ่น 
             การใช้ความรุนแรงทางเพศและการกระทำความผิดเกี่ยวกับเพศ และเผยแพร่ให้แก่หน่วยงานของรัฐและหน่วยงานของเอกชน
         (6) จัดทำแนวทางการพัฒนาศักยภาพของบุคลากรซึ่งปฏิบัติงานเกี่ยวกับการป้องกันและแก้ไขปัญหาการตั้งครรภ์ในวัยรุ่น
         (7) ปฏิบัติการอื่นใดตามที่คณะรัฐมนตรี คณะกรรมการ หรือคณะอนุกรรมการมอบหมาย หรือตามที่กฎหมายกำหนดให้เป็นอำนาจหน้าที่ของกรมอนามัย กระทรวงสาธารณสุข

    [หมวด 3: บทกำหนดโทษ]

มาตรา 23: ผู้ใดไม่ปฏิบัติตามคำสั่งของคณะกรรมการหรือคณะอนุกรรมการตามมาตรา 20 (เช่น การถูกเรียกมาให้ข้อเท็จจริง หรือให้ส่งเอกสารหลักฐาน) โดยไม่มีเหตุอันสมควร 
          ต้องระวางโทษจำคุกไม่เกิน 1 เดือน หรือปรับไม่เกิน 10,000 บาท หรือทั้งจำทั้งปรับ

    [บทเฉพาะกาล]

มาตรา 24: ในวาระเริ่มแรก ให้คณะกรรมการประกอบด้วยกรรมการเท่าที่มีอยู่ (นายกรัฐมนตรี และกรรมการโดยตำแหน่ง) และให้อธิบดีกรมอนามัยเป็นเลขานุการ ปฏิบัติหน้าที่ไปพลางก่อน 
          จนกว่าจะมีการแต่งตั้งกรรมการผู้ทรงคุณวุฒิและผู้แทนเด็กและเยาวชน ซึ่งต้องดำเนินการให้แล้วเสร็จไม่เกิน 120 วัน นับแต่วันที่พระราชบัญญัตินี้ใช้บังคับ


    ข้อมูลเพิ่มเติมสำหรับ AI (หมายเหตุและบริบทการบังคับใช้)

     1. เจตนารมณ์ของกฎหมาย: เหตุผลในการประกาศใช้ พ.ร.บ. ฉบับนี้ เนื่องจากปัญหาการตั้งครรภ์ในวัยรุ่นของประเทศมีความซับซ้อนและส่งผลกระทบต่อสุขภาพ 
        ครอบครัว ชุมชน สังคม และเศรษฐกิจในภาพรวม การแก้ไขปัญหาไม่อาจอาศัยหน่วยงานใดหน่วยงานหนึ่งได้ จึงต้องสร้างกลไกบูรณาการการทำงานร่วมกันของทุกภาคส่วน 
        ทั้งภาครัฐ เอกชน และประชาสังคม เพื่อให้การป้องกันและแก้ไขปัญหาเป็นรูปธรรมและมีประสิทธิภาพ

     2. การปรับปรุงชื่อหน่วยงาน (พ.ศ. 2562): ตาม พ.ร.บ. ปรับปรุงกระทรวง ทบวง กรม (ฉบับที่ 19) พ.ศ. 2562 ได้มีการจัดตั้งกระทรวงใหม่ 
        ส่งผลให้มีการโอนอำนาจหน้าที่และเปลี่ยนชื่อหน่วยงานที่รับผิดชอบในกฎหมายฉบับนี้ (ที่เกี่ยวกับการอุดมศึกษา) จากเดิม "กระทรวงศึกษาธิการ" ให้เปลี่ยนเป็น "กระทรวงการอุดมศึกษา 
        วิทยาศาสตร์ วิจัยและนวัตกรรม" เพื่อให้สอดคล้องกับโครงสร้างการบริหารราชการแผ่นดินในปัจจุบัน


  **พระราชบัญญัติคุ้มครองเด็ก พ.ศ. 2546**

มาตรา 1: พระราชบัญญัตินี้เรียกว่า "พระราชบัญญัติคุ้มครองเด็ก พ.ศ. 2546"
มาตรา 2: ให้ใช้บังคับเมื่อพ้นกำหนด 180 วันนับแต่วันประกาศในราชกิจจานุเบกษาเป็นต้นไป

มาตรา 4: บทนิยามศัพท์ที่สำคัญ

         [กลุ่มความหมายของ "เด็ก" ประเภทต่างๆ]
        - "เด็ก" หมายความว่า บุคคลซึ่งมีอายุต่ำกว่า 18 ปีบริบูรณ์ (แต่ไม่รวมถึงผู้ที่บรรลุนิติภาวะด้วยการสมรส)
        - "เด็กเร่ร่อน" หมายความว่า เด็กที่ไม่มีบิดามารดาหรือผู้ปกครอง หรือมีแต่ไม่เลี้ยงดูหรือไม่สามารถเลี้ยงดูได้ จนเป็นเหตุให้เด็กต้องเร่ร่อนไปในที่ต่างๆ หรือมีพฤติกรรมใช้ชีวิตเร่ร่อนจนน่าจะเกิดอันตรายต่อสวัสดิภาพ
        - "เด็กกำพร้า" หมายความว่า เด็กที่บิดาหรือมารดาสายเสียชีวิต เด็กที่ไม่ปรากฏบิดามารดาหรือไม่อาจสืบหาบิดามารดาได้
        - "เด็กที่อยู่ในสภาพยากลำบาก" หมายความว่า เด็กที่อยู่ในครอบครัวยากจน บิดามารดาหย่าร้าง ทิ้งร้าง ถูกคุมขัง แยกกันอยู่และได้รับความลำบาก หรือเด็กที่ต้องรับภาระหน้าที่ในครอบครัวเกินวัย หรือเด็กที่ไม่สามารถช่วยเหลือตัวเองได้
        - "เด็กพิการ" หมายความว่า เด็กที่มีความบกพร่องทางร่างกาย สมอง สติปัญญา หรือจิตใจ (ไม่ว่าจะเป็นมาแต่กำเนิดหรือเกิดขึ้นภายหลัง)
        - "เด็กที่เสี่ยงต่อการกระทำผิด" หมายความว่า เด็กที่ประพฤติตนไม่สมควร ประกอบอาชีพหรือคบหาสมาคมกับบุคคลที่น่าจะชักนำไปในทางกระทำผิดกฎหมายหรือขัดต่อศีลธรรมอันดี หรืออยู่ในสภาพแวดล้อมที่อาจชักนำไปในทางเสียหาย

         [กลุ่มบุคคลที่เกี่ยวข้องกับเด็ก]
        - "นักเรียน" หมายความว่า เด็กซึ่งกำลังรับการศึกษาขั้นพื้นฐาน (ประถม-มัธยม) ทั้งสายสามัญและอาชีวศึกษา
        - "นักศึกษา" หมายความว่า เด็กซึ่งกำลังรับการศึกษาระดับอุดมศึกษา
        - "บิดามารดา" หมายความว่า บิดามารดาของเด็กไม่ว่าจะสมรสกันหรือไม่
        - "ผู้ปกครอง" หมายความว่า บิดามารดา, ผู้อนุบาล, ผู้รับบุตรบุญธรรม, พ่อเลี้ยงแม่เลี้ยง, ผู้ปกครองสวัสดิภาพ, นายจ้าง ตลอดจนบุคคลอื่นซึ่งรับเด็กไว้ในความอุปการะเลี้ยงดู
        - "ครอบครัวอุปถัมภ์" หมายความว่า บุคคลที่รับเด็กไว้อุปการะเลี้ยงดูอย่างบุตร

         [กลุ่มพฤติกรรมและการกระทำ]
        - "การเลี้ยงดูโดยมิชอบ" หมายความว่า การไม่ให้การอุปการะเลี้ยงดู อบรมสั่งสอน หรือพัฒนาเด็กตามมาตรฐานขั้นต่ำ จนน่าจะเกิดอันตรายแก่ร่างกายหรือจิตใจของเด็ก
        - "ทารุณกรรม" หมายความว่า การกระทำหรือละเว้นการกระทำจนเป็นเหตุให้เด็กเสื่อมเสียเสรีภาพ เกิดอันตรายแก่ร่างกายหรือจิตใจ การกระทำผิดทางเพศต่อเด็ก 
           การใช้เด็กให้กระทำหรือประพฤติในลักษณะที่น่าจะเป็นอันตราย (ไม่ว่าเด็กจะยินยอมหรือไม่ก็ตาม)
        - "สืบเสาะและพินิจ" หมายความว่า การค้นหาและรวบรวมข้อเท็จจริงเกี่ยวกับบุคคลและนำมาวิเคราะห์วินิจฉัยตามหลักวิชาการทางสังคมสงเคราะห์ แพทย์ จิตวิทยา กฎหมาย ฯลฯ

         [กลุ่มสถานที่และหน่วยงาน]
        - "สถานรับเลี้ยงเด็ก" หมายความว่า สถานรับเลี้ยงและพัฒนาเด็กที่มีอายุไม่เกิน 6 ปีบริบูรณ์ และมีจำนวนตั้งแต่ 6 คนขึ้นไป (ไม่รวมสถานพยาบาลหรือโรงเรียน)
        - "สถานแรกรับ" หมายความว่า สถานที่รับเด็กไว้อุปการะชั่วคราวเพื่อสืบเสาะและพินิจเด็กและครอบครัว
        - "สถานสงเคราะห์" หมายความว่า สถานที่ให้การอุปการะเลี้ยงดูและพัฒนาเด็กที่จำต้องได้รับการสงเคราะห์ (ตั้งแต่ 6 คนขึ้นไป)
        - "สถานคุ้มครองสวัสดิภาพ" หมายความว่า สถานที่ให้การศึกษา อบรม ฝึกอาชีพ เพื่อแก้ไขความประพฤติ บำบัด รักษา และฟื้นฟูสมรรถภาพแก่เด็กที่พึงได้รับการคุ้มครองสวัสดิภาพ
        - "สถานพัฒนาและฟื้นฟู" หมายความว่า สถานที่เพื่อการบำบัดรักษา ฟื้นฟูสมรรถภาพ ตลอดจนการศึกษา แนะแนว และฝึกอาชีพแก่เด็กเป็นกรณีพิเศษ
        - "สถานพินิจ" หมายความว่า สถานพินิจและคุ้มครองเด็กและเยาวชนที่จัดตั้งขึ้นตามกฎหมาย
        - "กองทุน" หมายความว่า กองทุนคุ้มครองเด็ก
        - "คณะกรรมการ" หมายความว่า คณะกรรมการคุ้มครองเด็กแห่งชาติ


มาตรา 5: ให้ศาลที่มีอำนาจพิจารณาพิพากษาคดีเยาวชนและครอบครัวตามกฎหมายว่าด้วยการจัดตั้งศาลเยาวชนและครอบครัวและวิธีพิจารณาคดีเยาวชนและครอบครัว 
         มีอำนาจพิจารณาพิพากษาคดีตามพระราชบัญญัตินี้ เว้นแต่ในจังหวัดใดยังมิได้เปิดทำการศาลเยาวชนและครอบครัวหรือแผนกคดีเยาวชนและครอบครัวขึ้นในศาลจังหวัด 
         ให้ศาลจังหวัดมีอำนาจพิจารณาพิพากษาคดีตามพระราชบัญญัตินี้

มาตรา 6: ให้รัฐมนตรีว่าการกระทรวงการพัฒนาสังคมและความมั่นคงของมนุษย์, รัฐมนตรีว่าการกระทรวงการอุดมศึกษา วิทยาศาสตร์ วิจัยและนวัตกรรม
         ,รัฐมนตรีว่าการกระทรวงมหาดไทย, รัฐมนตรีว่าการกระทรวงศึกษาธิการ และรัฐมนตรีว่าการกระทรวงยุติธรรม รักษาการตามพระราชบัญญัตินี้ และให้รัฐมนตรีแต่ละกระทรวงมีอำนาจแต่งตั้งพนักงานเจ้าหน้าที่ 
          กับออกกฎกระทรวงหรือระเบียบเพื่อปฏิบัติการตามพระราชบัญญัตินี้ ทั้งนี้ ในส่วนที่เกี่ยวกับราชการของกระทรวงนั้น

    [หมวด 1: คณะกรรมการคุ้มครองเด็ก]

มาตรา 7: คณะกรรมการคุ้มครองเด็กแห่งชาติให้มีคณะกรรมการคุ้มครองเด็กแห่งชาติ ประกอบด้วย:
        - รัฐมนตรีว่าการกระทรวงการพัฒนาสังคมและความมั่นคงของมนุษย์ (เป็นประธานกรรมการ)
        - ปลัดกระทรวงการพัฒนาสังคมและความมั่นคงของมนุษย์ (เป็นรองประธานกรรมการ)
        - กรรมการโดยตำแหน่ง: ปลัดกระทรวงมหาดไทย, ปลัดกระทรวงยุติธรรม, ปลัดกระทรวงศึกษาธิการ, อัยการสูงสุด, ผู้บัญชาการตำรวจแห่งชาติ
          ,อธิบดีกรมการปกครอง, อธิบดีกรมพัฒนาสังคมและสวัสดิการ, อธิบดีกรมสุขภาพจิต, อธิบดีผู้พิพากษาศาลเยาวชนและครอบครัวกลาง
          ,ผู้อำนวยการสำนักงานส่งเสริมสวัสดิภาพและพิทักษ์เด็ก เยาวชน ผู้ด้อยโอกาส คนพิการ และผู้สูงอายุ
        - กรรมการผู้ทรงคุณวุฒิ: ซึ่งรัฐมนตรีว่าการกระทรวง พม. แต่งตั้งจากผู้เชี่ยวชาญที่มีประสบการณ์ในวิชาชีพสังคมสงเคราะห์, ครู
          ,จิตวิทยา, กฎหมาย, แพทย์ ไม่น้อยกว่า 7 ปี (วิชาชีพละ 2 คน โดยต้องมีผู้แทนจากภาคเอกชนอย่างน้อยวิชาชีพละ 1 คน) และแต่งตั้งจากผู้มีประสบการณ์ด้านสวัสดิการเด็กมาไม่น้อยกว่า 7 ปี (อีก 2 คน)
          *เงื่อนไข: กรรมการผู้ทรงคุณวุฒิต้องเป็นสตรีไม่น้อยกว่า 1 ใน 3
        - ให้รองปลัดกระทรวง พม. ซึ่งปลัดกระทรวงมอบหมายเป็นกรรมการและเลขานุการ (และสามารถตั้งข้าราชการใน พม. ไม่เกิน 2 คนเป็นผู้ช่วยเลขานุการได้)

มาตรา 8: ให้สำนักงานปลัดกระทรวงการพัฒนาสังคมและความมั่นคงของมนุษย์ ทำหน้าที่เป็นสำนักงานเลขานุการของคณะกรรมการ โดยมีอำนาจหน้าที่ ดังต่อไปนี้
       (1) ปฏิบัติงานธุรการทั่วไปของคณะกรรมการ
       (2) ประสานงานและร่วมมือกับส่วนราชการ หน่วยงานของรัฐ และเอกชนที่เกี่ยวข้อง ในการดำเนินงานเกี่ยวกับการสงเคราะห์ คุ้มครองสวัสดิภาพ และส่งเสริมความประพฤติเด็ก
       (3) พัฒนาระบบ รูปแบบ และวิธีการ ตลอดจนให้บริการด้านสงเคราะห์ คุ้มครองสวัสดิภาพ และส่งเสริมความประพฤติเด็ก
       (4) รวบรวมผลการวิเคราะห์ วิจัย ดำเนินการติดตามและประเมินผลการปฏิบัติตามนโยบายและแผนงาน แล้วรายงานให้คณะกรรมการทราบ
       (5) ปฏิบัติตามมติของคณะกรรมการหรือตามที่คณะกรรมการมอบหมาย

มาตรา 9: วาระของกรรมการผู้ทรงคุณวุฒิ
        - มีวาระอยู่ในตำแหน่งคราวละ 3 ปี
        - ผู้ซึ่งพ้นจากตำแหน่งเพราะครบวาระอาจได้รับการแต่งตั้งอีกได้ แต่ต้องไม่เกิน 2 วาระติดต่อกัน

มาตรา 10: นอกจากการพ้นจากตำแหน่งตามวาระ กรรมการผู้ทรงคุณวุฒิพ้นจากตำแหน่ง เมื่อ
         (1) ตาย
         (2) ลาออก
         (3) รัฐมนตรีให้ออกเพราะบกพร่องหรือไม่สุจริตต่อหน้าที่ มีความประพฤติเสื่อมเสีย หรือหย่อนความสามารถ
         (4) ได้รับโทษจำคุกโดยคำพิพากษาถึงที่สุดให้จำคุก
         (5) เป็นบุคคลล้มละลาย
         (6) เป็นคนไร้ความสามารถหรือคนเสมือนไร้ความสามารถ
         (7) ขาดการประชุมติดต่อกัน 3 ครั้งโดยไม่มีเหตุอันสมควร

มาตรา 11: ในกรณีที่กรรมการผู้ทรงคุณวุฒิพ้นจากตำแหน่งก่อนครบวาระ ให้รัฐมนตรีแต่งตั้งบุคคลซึ่งมีคุณสมบัติเดียวกันเป็นกรรมการแทน และให้อยู่ในตำแหน่งเท่ากับวาระที่เหลืออยู่ของผู้ซึ่งตนแทน

มาตรา 12: ในกรณีที่กรรมการผู้ทรงคุณวุฒิดำรงตำแหน่งครบวาระแล้ว แต่ยังมิได้มีการแต่งตั้งใหม่ ให้กรรมการที่พ้นจากตำแหน่งตามวาระปฏิบัติหน้าที่ไปพลางก่อน

มาตรา 13: การประชุมคณะกรรมการ
         - ต้องมีกรรมการมาประชุมไม่น้อยกว่ากึ่งหนึ่งของจำนวนทั้งหมดจึงจะเป็นองค์ประชุม
         - ให้ประธานกรรมการเป็นประธานในที่ประชุม (หากประธานไม่มาให้รองประธานทำหน้าที่แทน หากรองประธานไม่มาให้ที่ประชุมเลือกกรรมการคนหนึ่งเป็นประธาน)
         - การวินิจฉัยชี้ขาดให้ถือเสียงข้างมาก กรรมการคนหนึ่งมี 1 เสียง ถ้าคะแนนเท่ากันให้ประธานออกเสียงเพิ่มขึ้นอีกเสียงหนึ่งเป็นเสียงชี้ขาด

มาตรา 14: คณะกรรมการมีอำนาจและหน้าที่ ดังต่อไปนี้
         (1) เสนอความเห็นต่อรัฐมนตรีเกี่ยวกับนโยบาย แผนงาน งบประมาณ และมาตรการในการสงเคราะห์ คุ้มครองสวัสดิภาพ และส่งเสริมความประพฤติเด็ก
         (2) เสนอความเห็นต่อรัฐมนตรีในการออกกฎกระทรวงและระเบียบ
         (3) วางระเบียบโดยความเห็นชอบของกระทรวงการคลังเกี่ยวกับการรับ การจ่าย การเก็บรักษาเงิน และการจัดหาผลประโยชน์ของกองทุน
         (4) วางระเบียบเกี่ยวกับวิธีการดำเนินการคุ้มครองสวัสดิภาพเด็กตามมาตรา 47
         (5) วางหลักเกณฑ์ในการแต่งตั้งพนักงานเจ้าหน้าที่
         (6) ให้คำปรึกษา แนะนำ และประสานงานแก่หน่วยงานของรัฐและเอกชนที่ปฏิบัติงานด้านการศึกษา การสงเคราะห์ คุ้มครองสวัสดิภาพ และส่งเสริมความประพฤติเด็ก 
             รวมถึงมีอำนาจเข้าไปตรวจสอบในสถานรับเลี้ยงเด็ก สถานแรกรับ สถานสงเคราะห์ สถานคุ้มครองสวัสดิภาพ สถานพัฒนาและฟื้นฟู สถานพินิจ หรือสถานที่ที่เกี่ยวข้องกับการสงเคราะห์ 
             คุ้มครองสวัสดิภาพ และส่งเสริมความประพฤติเด็กทั้งของรัฐและเอกชน
         (7) ติดตาม ประเมินผล และตรวจสอบการดำเนินงานของคณะกรรมการคุ้มครองเด็กกรุงเทพมหานครและคณะกรรมการคุ้มครองเด็กจังหวัด 
             รวมถึงให้คำแนะนำและเสนอแนะในการป้องกันและแก้ไขปัญหาการสงเคราะห์ คุ้มครองสวัสดิภาพ และส่งเสริมความประพฤติเด็กในกรุงเทพมหานครและระดับจังหวัด
         (8) ดำเนินการอื่นใดที่เกี่ยวกับการสงเคราะห์ คุ้มครองสวัสดิภาพ และส่งเสริมความประพฤติเด็ก

มาตรา 15: คณะกรรมการมีอำนาจแต่งตั้งคณะอนุกรรมการหรือคณะทำงานเพื่อปฏิบัติการตามที่คณะกรรมการมอบหมาย
          - ให้นำบทบัญญัติมาตรา 13 มาใช้บังคับกับการประชุมของคณะอนุกรรมการหรือคณะทำงาน โดยอนุโลม

มาตรา 16: คณะกรรมการคุ้มครองเด็กกรุงเทพมหานครให้มีคณะกรรมการคุ้มครองเด็กกรุงเทพมหานคร ประกอบด้วย:
          - ผู้ว่าราชการกรุงเทพมหานคร (เป็นประธานกรรมการ)
          - ปลัดกรุงเทพมหานคร (เป็นรองประธานกรรมการ)
          - กรรมการโดยตำแหน่ง ได้แก่ ผู้แทนสำนักงานปลัดกระทรวงการอุดมศึกษา วิทยาศาสตร์ วิจัยและนวัตกรรม, ผู้แทนสำนักงานปลัดกระทรวงศึกษาธิการ, ผู้แทนกรมกิจการเด็กและเยาวชน
            ,ผู้แทนกรมพัฒนาสังคมและสวัสดิการ, ผู้แทนสำนักงานอัยการสูงสุด, ผู้แทนกองบัญชาการตำรวจนครบาล, ผู้แทนศาลเยาวชนและครอบครัวกลาง, ผู้แทนสถานพินิจและคุ้มครองเด็กและเยาวชนกรุงเทพมหานคร
            ,ผู้อำนวยการสำนักการแพทย์, ผู้อำนวยการสำนักการศึกษา, ผู้อำนวยการสำนักพัฒนาชุมชน และผู้อำนวยการสำนักอนามัย
          - กรรมการผู้ทรงคุณวุฒิ: ซึ่งผู้ว่าราชการกรุงเทพมหานครแต่งตั้งจากผู้เชี่ยวชาญที่มีประสบการณ์ด้านสังคมสงเคราะห์, ครู, จิตวิทยา, กฎหมาย, แพทย์ วิชาชีพละสองคน
             (โดยต้องมีผู้แทนจากภาคเอกชนอย่างน้อยวิชาชีพละหนึ่งคน) และแต่งตั้งจากผู้มีประสบการณ์ด้านสวัสดิการเด็กอีกสองคน
           *เงื่อนไข: กรรมการผู้ทรงคุณวุฒิต้องเป็นสตรีไม่น้อยกว่า 1 ใน 3
          - ให้ผู้อำนวยการสำนักสวัสดิการสังคม เป็นกรรมการและเลขานุการ (และแต่งตั้งข้าราชการในสำนักสวัสดิการสังคมไม่เกิน 2 คนเป็นผู้ช่วยเลขานุการได้)

มาตรา 17: คณะกรรมการคุ้มครองเด็กจังหวัดให้มีคณะกรรมการคุ้มครองเด็กจังหวัด ประกอบด้วย:
          - ผู้ว่าราชการจังหวัด (เป็นประธานกรรมการ)
          - รองผู้ว่าราชการจังหวัดซึ่งได้รับมอบหมาย (เป็นรองประธานกรรมการ)
          - กรรมการโดยตำแหน่ง ได้แก่ อัยการจังหวัด, พัฒนาการจังหวัด, แรงงานจังหวัด, ผู้อำนวยการเขตพื้นที่การศึกษา, นายแพทย์สาธารณสุขจังหวัด
            ,ผู้บังคับการตำรวจภูธรจังหวัด, ผู้แทนศาลเยาวชนและครอบครัวจังหวัดหรือผู้แทนศาลจังหวัด (ในกรณีที่จังหวัดนั้นไม่มีศาลเยาวชนและครอบครัว)
            ,ผู้แทนสถานพินิจและคุ้มครองเด็กและเยาวชนจังหวัดหรือผู้แทนกระทรวงยุติธรรม ,นายกองค์การบริหารส่วนจังหวัด
          - กรรมการผู้ทรงคุณวุฒิ: ซึ่งผู้ว่าราชการจังหวัดแต่งตั้งจากผู้เชี่ยวชาญที่มีประสบการณ์ด้านสังคมสงเคราะห์, ครู, จิตวิทยา, กฎหมาย
            ,แพทย์ วิชาชีพละสองคน (โดยต้องมีผู้แทนจากภาคเอกชนอย่างน้อยวิชาชีพละหนึ่งคน) และแต่งตั้งจากผู้มีประสบการณ์ด้านสวัสดิการเด็กอีกสองคน
            *เงื่อนไข: กรรมการผู้ทรงคุณวุฒิต้องเป็นสตรีไม่น้อยกว่า 1 ใน 3
          - ให้พัฒนาสังคมและความมั่นคงของมนุษย์จังหวัด เป็นกรรมการและเลขานุการ (และแต่งตั้งข้าราชการในจังหวัดไม่เกิน 2 คนเป็นผู้ช่วยเลขานุการได้)

มาตรา 18: การนำบทบัญญัติมาใช้บังคับกับกรรมการผู้ทรงคุณวุฒิ
          - ให้นำมาตรา 9, มาตรา 10, มาตรา 11 และมาตรา 12 มาใช้บังคับกับการดำรงตำแหน่ง การพ้นจากตำแหน่ง การแต่งตั้งกรรมการแทน 
            และการปฏิบัติหน้าที่ของกรรมการผู้ทรงคุณวุฒิตามมาตรา 16 และมาตรา 17 โดยอนุโลม 
          - *ข้อยกเว้น:* อำนาจของรัฐมนตรีตามมาตรา 10 (3) และมาตรา 11 ให้ถือเป็นอำนาจของ "ผู้ว่าราชการกรุงเทพมหานคร" หรือ "ผู้ว่าราชการจังหวัด" แล้วแต่กรณี

มาตรา 19: ให้นำมาตรา 13 และมาตรา 15 มาใช้บังคับกับการประชุมและการแต่งตั้งคณะอนุกรรมการหรือคณะทำงานของคณะกรรมการคุ้มครองเด็กกรุงเทพมหานครและคณะกรรมการคุ้มครองเด็กจังหวัด โดยอนุโลม

มาตรา 20: อำนาจและหน้าที่ของคณะกรรมการคุ้มครองเด็กกรุงเทพมหานครและคณะกรรมการคุ้มครองเด็กจังหวัด
         (1) เสนอความเห็นต่อคณะกรรมการแห่งชาติเกี่ยวกับนโยบาย แผนงาน งบประมาณ และมาตรการในการสงเคราะห์ คุ้มครองสวัสดิภาพ และส่งเสริมความประพฤติเด็กตามพระราชบัญญัตินี้
         (2) ให้คำปรึกษา แนะนำ และประสานงานแก่หน่วยงานรัฐและเอกชนที่ปฏิบัติงานด้านการศึกษา 
             การสงเคราะห์ คุ้มครองสวัสดิภาพ และส่งเสริมความประพฤติเด็ก รวมถึงมีอำนาจเข้าไปตรวจสอบในสถานรับเลี้ยงเด็ก 
             สถานแรกรับ สถานสงเคราะห์ สถานคุ้มครองสวัสดิภาพ สถานพัฒนาและฟื้นฟู สถานพินิจ หรือสถานที่ที่เกี่ยวข้องฯ ภายในเขต กทม. หรือจังหวัดนั้นๆ
         (3) กำหนดแนวทางการสงเคราะห์ คุ้มครองสวัสดิภาพ และส่งเสริมความประพฤติเด็กในเขต กทม. หรือจังหวัด
         (4) จัดหาทุนเพื่อการสงเคราะห์ คุ้มครองสวัสดิภาพ และส่งเสริมความประพฤติเด็ก และรายงานผลการดำเนินงานต่อคณะกรรมการแห่งชาติและคณะกรรมการบริหารกองทุน
         (5) ตรวจสอบหรือเรียกบุคคลที่เกี่ยวข้องมาชี้แจงกรณีมีการปฏิบัติต่อเด็กโดยมิชอบ
         (6) เรียกเอกสารหรือพยานหลักฐานใด ๆ มาไต่สวนหรือ "แจ้งคำชี้แจง" จากผู้ที่เกี่ยวข้องเพื่อประกอบการวินิจฉัยในการปฏิบัติหน้าที่ตามพระราชบัญญัตินี้
         (7) ติดตาม ประเมินผลและตรวจสอบการดำเนินงานเกี่ยวกับการสงเคราะห์ คุ้มครองสวัสดิภาพ และส่งเสริมความประพฤติเด็กในกรุงเทพมหานครและระดับจังหวัด แล้วรายงานผลต่อคณะกรรมการ
         (8) ดำเนินการอื่นใดตามที่คณะกรรมการมอบหมาย

มาตรา 21: ในการปฏิบัติหน้าที่ตามพระราชบัญญัตินี้ ให้พนักงานเจ้าหน้าที่เป็นเจ้าพนักงานตามประมวลกฎหมายอาญา

    [หมวด 2: การปฏิบัติต่อเด็ก]

มาตรา 22: การปฏิบัติต่อเด็กไม่ว่ากรณีใด ให้คำนึงถึงประโยชน์สูงสุดของเด็กเป็นสำคัญ และต้องไม่เลือกปฏิบัติโดยไม่เป็นธรรม 
          - การกระทำใดๆ เพื่อประโยชน์สูงสุดของเด็ก หรือเป็นการเลือกปฏิบัติที่จะไม่เป็นธรรมต่อเด็ก ให้พิจารณาตามแนวทางที่กำหนดในกฎกระทรวง

มาตรา 23: ผู้ปกครองต้องให้การอุปการะเลี้ยงดู อบรมสั่งสอน และพัฒนาเด็กที่อยู่ในความปกครองของตนตามขนบธรรมเนียมประเพณีและวัฒนธรรมแห่งท้องถิ่น 
          แต่ทั้งนี้ต้องไม่ต่ำกว่ามาตรฐานขั้นต่ำที่กำหนดในกฎกระทรวงและต้องคุ้มครองสวัสดิภาพเด็กที่อยู่ในความปกครองของตนมิให้ตกอยู่ในภาวะอันตรายหรือ ภัยพิบัติทางจิตใจ

มาตรา 24: ปลัดกระทรวง, ผู้ว่าราชการจังหวัด, ผู้อำนวยการเขต, นายอำเภอ, ปลัดอำเภอ, ผู้เป็นหัวหน้าประจำกิ่งอำเภอ หรือผู้บริหารองค์กรส่วนท้องถิ่น 
          มีหน้าที่คุ้มครองสวัสดิภาพเด็กที่อยู่ในเขตพื้นที่รับผิดชอบ ไม่ว่าเด็กจะผู้ปกครองหรือไม่ก็ตาม รวมถึงมีอำนาจและหน้าที่ดูแลและตรวจสอบสถานรับเลี้ยงเด็ก สถานแรกรับ สถานสงเคราะห์ 
          สถานคุ้มครองสวัสดิภาพ สถานพัฒนาและฟื้นฟู สถานพินิจ และสถานที่หรือสถานที่ที่ตั้งอยู่ในเขตอำนาจเพื่อความปลอดภัยของเด็ก คณะกรรมการ คุ้มครองเด็กกรุงเทพมหานคร 
          คณะกรรมการคุ้มครองเด็กจังหวัด และพนักงานเจ้าหน้าที่ เพื่อให้มีอำนาจหน้าที่ชัดเจนกับพนักงานเจ้าหน้าที่ ตามพระราชบัญญัตินี้

มาตรา 25: ผู้ปกครองไม่กระทำการ ดังต่อไปนี้
        (1) ทอดทิ้งเด็กไว้ในสถานรับเลี้ยงเด็กหรือสถานพยาบาลหรือไว้กับบุคคลที่รับจ้างเลี้ยงเด็กหรือสาธารณะหรือสถานที่ใด โดยเจตนาไม่มารับเด็กคืน
        (2) ทิ้งเด็กไว้ ณ สถานที่ใด ๆ โดยไม่มีการป้องกันดูแลสวัสดิภาพหรือให้เลี้ยงดูที่เหมาะสม
        (3) จงใจหรือละเว้นไม่ให้สิ่งที่จำเป็นแก่การดำรงชีวิตหรือสุขภาพอนามัยจนน่าจะเกิดอันตรายแก่ร่างกายหรือจิตใจของเด็ก
        (4) ปฏิบัติต่อเด็กในลักษณะที่เป็นการขัดขวางการเจริญเติบโตหรือพัฒนาการของเด็ก
        (5) ปฏิบัติต่อเด็กในลักษณะที่เป็นการเลี้ยงดูโดยมิชอบ

มาตรา 26: ภายใต้บังคับแห่งกฎหมายอื่น ไม่ว่าเด็กจะยินยอมหรือไม่ ห้ามมิผู้ใดกระทำการ ดังต่อไปนี้
        (1) กระทำหรือละเว้นกระทำอันเป็นการทารุณกรรมต่อร่างกายหรือจิตใจของเด็ก
        (2) จงใจหรือละเว้นไม่ให้สิ่งที่จำเป็นแก่การดำรงชีวิตหรือรักษาพยาบาลแก่เด็กซึ่งอยู่ในความดูแลของตน จนน่าจะเกิดอันตรายแก่ร่างกายหรือจิตใจของเด็ก
        (3) บังคับ ขู่เข็ญ ชักจูง ส่งเสริม หรือยินยอมให้เด็กประพฤติตนไม่สมควร หรือทำให้เด็กมีความประพฤติเสี่ยงต่อการกระทำผิด
        (4) โฆษณาทางสื่อมวลชนหรือเผยแพร่ด้วยประการใด เพื่อสืบค้นหรือเลือกเด็กให้บุคคลอื่นที่มีข้อผูกพันเด็ก แม้จะเป็นการกระทำตามทางราชการหรือได้รับอนุญาตทางราชการแล้ว
        (5) บังคับ ขู่เข็ญ ชักจูง ส่งเสริม หรือกระทำให้เด็กไปเป็นขอทาน หรือใช้เด็กเป็นเครื่องมือในการขอทานหรือการกระทำผิด หรือกระทำให้เด็กบันดาลสภาพทางผลประโยชน์ในลักษณะเร่ร่อนตาม
        (6) ใช้ จ้าง หรือวานเด็กให้ทำงานหรือกระทำการใดอันอาจเป็นอันตรายแก่ร่างกายหรือจิตใจหรือกระทบกระเทือนต่อการเจริญเติบโตของเด็ก
        (7) บังคับ ขู่เข็ญ ใช้ ชักจูง ยุยง ส่งเสริม หรือยินยอมให้เด็กเล่นกีฬาหรือให้กระทำใดเพื่อแสวงหาประโยชน์ทางการค้าอันมีลักษณะเป็นการขัดขวางการเจริญเติบโตหรือพัฒนาการของเด็ก หรือมีลักษณะเป็นการทารุณกรรมเด็ก
        (8) ใช้วิธีสั่งสอนขู่เข็ญเด็กอันเป็นการพินิจหรือขัดขวางเข้าไปในสถานที่แห่งการพนันหรือสถานสถานที่ที่ห้ามมิให้เด็กเข้า
        (9) บังคับ ขู่เข็ญ ใช้ ชักจูง ส่งเสริม หรือยินยอมให้เด็กเสพสุราหรือของมึนเมาอย่างอื่น หรือมีลักษณะนอนถอน ไม่ว่าจะเป็นไปเพื่อดื่มหรือต่างตอบแทนเพื่อการใด
        (10) จำหน่าย แลกเปลี่ยน หรือให้สุราหรือบุหรี่แก่เด็ก เว้นแต่การปฏิบัติทางการแพทย์
            - การกระทำความผิดตามวรรคหนึ่งตามกฎหมายอื่นที่มีโทษหนักกว่าทางโทษ


มาตรา 27 : ห้ามมิให้ผู้ใดโฆษณาหรือเผยแพร่ทางสื่อมวลชนหรือสื่อสารสนเทศประเภทใด ซึ่งข้อมูลเกี่ยวกับตัวเด็กหรือผู้ปกครอง โดยเจตนาที่จะทำให้เกิดความเสียหายแก่จิตใจ 
           ชื่อเสียง เกียรติคุณ หรือสิทธิประโยชน์อื่นใดของเด็ก หรือเพื่อแสวงหาประโยชน์สำหรับตนเองหรือผู้อื่นโดยมิชอบ

มาตรา 28: ในกรณีผู้ปกครองตกอยู่ในสภาพไม่อาจให้การอุปการะเลี้ยงดู อบรมสั่งสอน และพัฒนาเด็กได้ไม่ว่าด้วยเหตุใด หรือผู้ปกครองทำการใดอันน่าจะเกิดอันตรายต่อสวัสดิภาพหรือจิตใจของเด็ก 
          หรือขัดขวางการพัฒนาเด็ก หรือให้การเลี้ยงดูโดยมิชอบ หรือมีเหตุจำเป็นอื่นใดเพื่อประโยชน์ในการสงเคราะห์หรือคุ้มครองสวัสดิภาพ หรือป้องกันมิให้เด็กได้รับความรุนแรงหรือไม่เลือกปฏิบัติโดยไม่เป็นธรรม 
          ผู้ที่มีความรู้ความเข้าใจและมีหน้าที่จะต้องให้การสงเคราะห์หรือคุ้มครองสวัสดิภาพตามพระราชบัญญัตินี้

มาตรา 29: ผู้ใดพบเห็นเด็กตกอยู่ในสภาพจำต้องได้รับการสงเคราะห์หรือคุ้มครองสวัสดิภาพ มาตรา 5, มาตรา 8 จะต้องให้การช่วยเหลือเบื้องต้นและแจ้งต่อพนักงานเจ้าหน้าที่ 
          พนักงานฝ่ายปกครอง หรือผู้ปฏิบัติหน้าที่ผู้ช่วยพนักงานเจ้าหน้าที่ตามมาตรา 34 โดยให้เข้า
          - แพทย์ พยาบาล นักจิตวิทยา นักสังคมสงเคราะห์ หรือเจ้าหน้าที่สาธารณสุข ที่ับตัวเด็กไว้รักษาพยาบาล ครู อาจารย์ หรือนายจ้าง 
            ซึ่งมีหน้าที่ดูแลเด็กที่เป็นเด็กถูกทอดทิ้ง จะต้องรายงานให้พนักงานเจ้าหน้าที่ผู้มีหน้าที่คุ้มครองสวัสดิภาพเด็กตามมาตรา 24 หรือพนักงานฝ่ายปกครองหรือตำรวจทราบโดยเร็ว
          - การแจ้งหรือการรายงานตามมาตรานี้ เมื่อได้กระทำโดยสุจริตได้รับความคุ้มครองและจะไม่ต้องรับผิดทางแพ่ง ทางอาญา หรือทางปกครอง

มาตรา 30: เพื่อประโยชน์ในการปฏิบัติตามพระราชบัญญัตินี้ ให้พนักงานเจ้าหน้าที่มีอำนาจหน้าที่ ดังต่อไปนี้
         (1) เข้าไปในเคหสถาน สถานที่ใด ๆ หรือยานพาหนะใด ๆ ในระหว่างเวลาพระอาทิตย์ขึ้นถึงพระอาทิตย์ตก 
             ในกรณีมีเหตุอันควรสงสัยว่ามีการกระทำทารุณกรรมเด็กหรือการกักขังหน่วงเหนี่ยว หรือในกรณีมีเหตุอันควรเชื่อว่าหากดำเนินการทันทีเด็กจะได้รับอันตรายแก่ร่างกายหรือจิตใจ 
             หรือถูกนำพาไปในสถานที่ซึ่งยากแก่การจัดการช่วยเหลือ ก็ให้มีอำนาจเข้าไปในเคหสถานยานพาหนะดังกล่าวได้
         (2) ซักถามเด็กเมื่อมีเหตุสงสัยว่าเด็กได้รับการสงเคราะห์หรือคุ้มครองสวัสดิภาพ ในกรณีจำเป็นเพื่อประโยชน์ในการสงเคราะห์และคุ้มครองสวัสดิภาพเด็ก 
             นำตัวเด็กไปมีคำสั่งของพนักงานเจ้าหน้าที่ เพื่อสืบเสาะและรวบรวมข้อข้อมูลเกี่ยวกับเด็กและครอบครัว รวมทั้งที่เด็กอาศัย ทั้งนี้ เพื่อกระทำใดเด็กเข้า ผู้ซึ่ไม่มีเด็กกระทำตัวเกินกว่าสิ้นเท่าเงินล้าน 
             และเมื่อในระหว่างกระทำให้อยู่ในการควบคุมดูแลเพื่อการอุปการะเลี้ยงดู และหาทางช่วยเหลือ ได้รับการรักษาพยาบาล
         (3) มีหนังสือเรียกผู้ปกครอง หรือบุคคลอื่นให้มาให้ถ้อยคำหรือจัดส่งข้อเท็จจริงเกี่ยวกับสภาพความเป็นอยู่ ครอบครัว สุขภาพ และความสัมพันธ์ในครอบครัวของเด็ก
         (4) ขอคำสั่งเป็นหนังสือให้ผู้ปกครอง นายจ้าง หรือผู้ประกอบกิจการหรือผู้ปกครองเด็กหรือผู้ทำทำงานค่าจ้าง อาศัยหรือเคยอาศัย อยู่หรือของผู้ปกครองหรือผู้ดูแลสถานศึกษาที่สังกัดสถานศึกษาหรือผู้ปกครองเด็ก 
             ส่งเอกสารหรือหลักฐานเกี่ยวกับความเป็นอยู่ การศึกษา การทำงาน หรือความประพฤติเด็กมาให้
         (5) เข้าไปในสถานที่อยู่อาศัยของผู้ปกครอง สถานที่ประกอบการของนายจ้างศึกษาของเด็ก หน่วยงานที่มีความเกี่ยวข้อง ในระหว่างเวลานพระอาทิตย์ตกเพื่อสอบถามบุคคลที่อยู่ในนั้น ๆ 
             และรวบรวมข้อมูลหรือหลักฐานเกี่ยวกับสภาพความเป็นอยู่ ความสัมพันธ์ในครอบครัว การเลี้ยงดู อุปนิสัย และความประพฤติของเด็ก
         (6) มอบตัวเด็กให้แก่ผู้ปกครองพร้อมกับแนะนำหรือตักเตือนผู้ปกครองให้ดูแลและอุปการะเลี้ยงดูเด็กในทางที่ถูกต้อง เพื่อให้เด็กได้รับการพัฒนาในทางที่เหมาะสม
         (7) ทำรายงานเกี่ยวกับตัวเด็กเพื่อมอบให้แก่สถานแรกรับในกรณีมีการส่งเด็กไปยังสถานแรกรับหรือหน่วยงานที่เกี่ยวข้องเมื่อมีการร้องขอ
             - เด็กที่อยู่ในความดูแลของพนักงานเจ้าหน้าที่ที่จะต้องได้รับการอุปการะเลี้ยงดู และได้รับการศึกษาอย่างเหมาะสม และก่อนที่จะจัดให้เด็กเข้าอยู่ในสถานรับเลี้ยงเด็ก 
               สถานแรกรับ สถานสงเคราะห์ สถานคุ้มครองสวัสดิภาพ และสถานพัฒนาและฟื้นฟู จะต้องปรึกษาผู้เชี่ยวชาญในสาขาวิชาชีพสังคมสงเคราะห์และการแพทย์ก่อนเท่าที่สามารถกระทำได้
             - ในการปฏิบัติหน้าที่ตาม (1) (2) และ (5) พนักงานเจ้าหน้าที่ต้องแสดงบัตรประจำตัวก่อน และให้บุคคลที่เกี่ยวข้องอำนวยความสะดวกตามสมควร 
               บัตรประจำตัวพนักงานเจ้าหน้าที่ให้เป็นไปตามแบบที่รัฐมนตรีหนดโดยประกาศในราชกิจจานุเบกษา

มาตรา 31: ในการปฏิบัติหน้าที่ตามพระราชบัญญัตินี้ ให้พนักงานเจ้าหน้าที่เป็นเจ้าพนักงานตามประมวลกฎหมายอาญา

      [หมวด 3: การสงเคราะห์เด็ก]

มาตรา 32: เด็กที่พึงได้รับการสงเคราะห์ ได้แก่
         (1) เด็กเร่ร่อน หรือเด็กกำพร้า
         (2) เด็กที่ถูกทอดทิ้งหรือพลัดหลง ณ ที่ใดที่หนึ่ง
         (3) เด็กที่ผู้ปกครองไม่สามารถอุปการะเลี้ยงดูได้ด้วยเหตุใด ๆ เช่น ถูกจำคุก กักขัง พิการ ทุพพลภาพ เจ็บป่วยเรื้อรัง ยากจน เป็นผู้เยาว์ หย่า ถูกทิ้งร้าง เป็นโรคจิตหรือโรคประสาท
         (4) เด็กที่ผู้ปกครองมีพฤติกรรมหรือประกอบอาชีพไม่เหมาะสมอันอาจส่งผลกระทบต่อพัฒนาการทางร่างกายหรือจิตใจของเด็กที่อยู่ในความปกครองดูแล
         (5) เด็กที่ได้รับการเลี้ยงดูโดยมิชอบ ถูกใช้เป็นเครื่องมือในการกระทำหรือแสวงหาประโยชน์โดยมิชอบ ถูกทารุณกรรม 
             หรือตกอยู่ในภาวะอื่นใดอันอาจเป็นเหตุให้เด็กมีความประพฤติเสื่อมเสียในทางศีลธรรมอันดีหรือเป็นเหตุให้เกิดอันตรายแก่กายหรือจิตใจ
         (6) เด็กพิการ
         (7) เด็กที่จัดให้ครับ! สำหรับเนื้อหาชุดนี้เดินทางเข้าสู่ **หมวด 3 การสงเคราะห์เด็ก** (มาตรา 32 ถึง มาตรา 37) ซึ่งระบุถึงเกณฑ์ของเด็กที่ "พึงได้รับการสงเคราะห์" รวมถึงวิธีการและมาตรการให้ความช่วยเหลือของพนักงานเจ้าหน้าที่ครับ


มาตรา 33: ในการที่พนักงานเจ้าหน้าที่ผู้มีหน้าที่คุ้มครองสวัสดิภาพเด็กตามมาตรา 24 หรือพนักงานเจ้าหน้าที่อื่นผู้รับมอบหมายตามมาตรา 34 จะดำเนินการสงเคราะห์เด็กตามมาตรา 32 ให้พิจารณาวิธีการสงเคราะห์เด็กที่เหมาะสม ดังต่อไปนี้
         (1) ให้ความช่วยเหลือและสงเคราะห์แก่เด็กและครอบครัวหรือบุคคลซึ่งผู้ปกครองเลี้ยงดูและไม่อาจอปการะเลี้ยงดูเด็กได้ตามมาตรา 34
         (2) มอบตัวเด็กให้อยู่ในความอุปการะของบุคคลที่เหมาะสมและยินยอมรับเด็กไปอุปการะเพื่อดูแลระยะเวลาที่สมควร แต่ต้องไม่เกินหนึ่งปี ในกรณีที่ไม่อาจดำเนินการตาม (1) ได้
         (3) ดำเนินการเพื่อให้จัดได้เป็นบุตรบุญธรรมของบุคคลอื่นตามกฎหมายว่าด้วยการรับเด็กเป็นบุตรบุญธรรม
         (4) ส่งเด็กเข้ารับการอุปการะในครอบครัวอุปถัมภ์หรือสถานรับเลี้ยงเด็กและมีและรับเด็กไร้ผู้อยู่อาศัย
         (5) ส่งเด็กเข้ารับการอุปการะในสถานแรกรับ
         (6) ส่งเด็กเข้ารับการอุปการะในสถานสงเคราะห์
         (7) ส่งเด็กเข้ารับการฝึกหัดจัดหาอาชีพ หรือเด็กเข้าฝึกหัดฟื้นฟูสมรรถภาพ พัฒนาทักษะในสถานพัฒนาและฟื้นฟู หรือส่งเด็กศึกษาต่อตามสถานศึกษาโดยไม่ใช้อุปกรณ์หรือพัฒนาภาษาท่าทางอื่น ๆ ที่จัดแก่วัย
             - วิธีการให้การสงเคราะห์ตามวรรคหนึ่งให้เป็นไปตามกฎกระทรวงกำหนด และไม่ว่าการใด ๆ การดำเนินการให้การสงเคราะห์ตาม (1) (2) 
               หรือ (3) ต้องได้รับความยินยอมจากผู้ปกครอง เว้นแต่การดังกล่าวเป็นหนังสือตามแบบที่กฎกระทรวงกำหนด หรือยินยอมตัววาจาต่อหน้าพนักงานอย่างน้องพบตน 
               ในกรณีที่ผู้ปกครองไม่ให้ความยินยอมไม่มีเหตุผลสมควรหรือไม่สามารถให้ได้ ให้จัดมีติดต่อหรือผู้ว่าราชการจังหวัด แล้วแต่กรณี มีอำนาจสั่งเด็กเข้ารับการสงเคราะห์ตามวิธีการดังกล่าว ทั้งนี้ ปลัดกระทรวงหรือผู้ว่าราช


มาตรา 34: ผู้ปกครองหรือผู้ใช้อำนาจเด็ก อาจนำเด็กไปรับการสงเคราะห์ที่กรมพัฒนาสังคมและสวัสดิการสำนักงานพัฒนาสังคมและความมั่นคงจังหวัด หรือที่สถานแรกรับ สถานสงเคราะห์ หรือสถานพัฒนาและฟื้นฟูของเอกชน เพื่อการสงเคราะห์ได้
           - ในกรณีที่เด็กน่าเชื่อถือต้องการสงเคราะห์ที่กรมพัฒนาสังคมและสวัสดิการสำนักงานพัฒนาสังคมและความมั่นคงจังหวัด หรือสำนักงานพัฒนาสังคมและความมั่นคงจังหวัด 
             ถ้าเป็นจำเป็นต้องให้รับการสงเคราะห์ให้พนักงานเจ้าหน้าที่พิจารณาให้การสงเคราะห์ตามมาตรา 33 แต่ในกรณีที่พนักงานเจ้าหน้าที่ยังไม่สามารถใช้วิธีการสงเคราะห์ที่เหมาะสมแก่เด็กตามมาตรา 33 ได้ จะส่งเด็กไปสถานแรกรับก่อนก็ได้
           - กรณีการนำเด็กมามอบรับการสงเคราะห์ที่สถานแรกรับ สถานสงเคราะห์ หรือสถานพัฒนาและฟื้นฟูเด็กเอกชน ให้ผู้ปกครองสวัสดิภาพรายงานข้อมูลเกี่ยวกับเด็กต่อพนักงานเจ้าหน้าที่เพื่อพิจารณาตรวจสอบการบรรเทาทุกข์


มาตรา 35: เมื่อพนักงานเจ้าหน้าที่หรือผู้มีหน้าที่คุ้มครองสวัสดิภาพเด็กตามมาตรา 24 พบเห็นเด็กที่พึงได้รับการสงเคราะห์
          ตามมาตรา 32 (1) และ (2) หรือได้รับแจ้งจากบุคคลตามมาตรา 29 ให้สอบถามเพื่อทราบข้อมูลเกี่ยวกับเด็ก 
          - หากเด็กเจ็บป่วยหรือจำต้องตรวจสุขภาพหรือเป็นเด็กพิการ ต้องรีบจัดให้มีการตรวจรักษาทางร่างกายและจิตใจทันที 
          - หากเป็นเด็กที่จำเป็นต้องได้รับการสงเคราะห์ก็ให้พิจารณาให้การสงเคราะห์ตามมาตรา 33 และไม่ว่ากรณีใดให้พยายามดำเนินการเพื่อให้เด็กสามารถกลับไปอยู่กับครอบครัวโดยเร็ว 
          - แต่หากปรากฏว่าสภาพครอบครัวหรือสิ่งแวดล้อมไม่เหมาะที่จะให้เด็กกลับไปอยู่กับครอบครัว และมีเหตุจำเป็นที่จะต้องให้การคุ้มครองสวัสดิภาพแก่เด็ก พนักงานเจ้าหน้าที่อาจใช้มาตรการคุ้มครองสวัสดิภาพแก่เด็กตามหมวด 4 ก็ได้

มาตรา 36: ในระหว่างที่เด็กได้รับการสงเคราะห์ตามมาตรา 33 (2), (4) หรือ (6) หากปรากฏว่าเป็นเด็กที่เสี่ยงต่อการกระทำผิดและพึงได้รับการคุ้มครองสวัสดิภาพ 
          ให้ปลัดกระทรวงหรือผู้ว่าราชการจังหวัดแล้วแต่กรณี มีอำนาจสั่งให้ใช้มาตรการคุ้มครองสวัสดิภาพแก่เด็กตามหมวด 4 ได้


มาตรา 37: เมื่อสถานแรกรับ สถานสงเคราะห์ หรือสถานพัฒนาและฟื้นฟู ได้รับตัวเด็กไว้ตามมาตรา 33 (5), (6) หรือ (7) ให้ผู้ปกครองสวัสดิภาพรีบสืบเสาะและพินิจเกี่ยวกับตัวเด็กและครอบครัว 
          และเสนอความเห็นเกี่ยวกับวิธีการสงเคราะห์หรือคุ้มครองสวัสดิภาพเด็กแต่ละคน พร้อมด้วยประวัติไปยังปลัดกระทรวงหรือผู้ว่าราชการจังหวัด แล้วแต่กรณี โดยมิชักช้า และให้ปลัดกระทรวงหรือผู้ว่าราชการจังหวัดสั่งการตามที่เห็นสมควรต่อไป


มาตรา 38: ในกรณีที่ปลัดกระทรวงหรือผู้ว่าราชการจังหวัดสั่งให้เด็กเข้ารับการสงเคราะห์โดยผู้ปกครองไม่ยินยอมตามมาตรา 33 วรรคสอง, กรณีที่ผู้ปกครองของเด็กไม่เห็นด้วยกับกำหนดระยะเวลาตามมาตรา 33 วรรคสาม
          ,หรือกรณีที่ผู้ปกครองยื่นคำร้องขอรับเด็กไปปกครองดูแลเองแต่ได้รับการปฏิเสธจากปลัดกระทรวงหรือผู้ว่าราชการจังหวัดตามมาตรา 33 วรรคสี่ ผู้ปกครองย่อมมีสิทธิอุทธรณ์คดีไปสู่ศาลตามมาตรา 5 ในเขตท้องที่นั้นภายใน 180 วันนับแต่วันรับทราบคำสั่ง

มาตรา 39: ในกรณีที่ผู้ปกครองซึ่งได้รับเด็กกลับมาอยู่ในความดูแล มีพฤติการณ์น่าเชื่อว่าจะให้การเลี้ยงดูโดยมิชอบแก่เด็กอีก ให้พนักงานเจ้าหน้าที่หรือผู้มีหน้าที่คุ้มครองสวัสดิภาพเด็กตามมาตรา 24 ให้คำแนะนำแก่ผู้ปกครอง 
          - หากผู้ปกครองไม่ปฏิบัติตามคำแนะนำ ให้ยื่นคำขอต่อปลัดกระทรวง, ผู้ว่าราชการจังหวัด
            ,นายอำเภอ หรือปลัดอำเภอผู้เป็นหัวหน้าประจำกิ่งอำเภอ แล้วแต่กรณี เพื่อเรียกผู้ปกครองมาทำทัณฑ์บนว่าจะไม่กระทำการใดอันมีลักษณะเป็นการให้การเลี้ยงดูโดยมิชอบแก่เด็กอีก
          - ให้วางประกันไว้เป็นจำนวนเงินตามสมควรแก่ฐานานุรูป (แต่จะเรียกประกันไว้ได้ไม่เกินระยะเวลา 2 ปี) 
          - ถ้ากระทำผิดทัณฑ์บน ให้ริบเงินประกันเป็นของ "กองทุนคุ้มครองเด็ก" ตามมาตรา 69
          - การให้คำแนะนำหรือการเรียกประกัน ต้องคำนึงถึงฐานะทางเศรษฐกิจของผู้ปกครองและประโยชน์สูงสุดของเด็กเป็นสำคัญ

 
   [หมวด 4: การคุ้มครองสวัสดิภาพเด็ก]

มาตรา 40: เด็กที่พึงได้รับการคุ้มครองสวัสดิภาพ ได้แก่
          (1) เด็กที่ถูกทารุณกรรม
          (2) เด็กที่เสี่ยงต่อการกระทำผิด
          (3) เด็กที่อยู่ในสภาพที่จำต้องได้รับการคุ้มครองสวัสดิภาพตามที่กำหนดในกฎกระทรวง

มาตรา 41: ผู้ใดพบเห็นหรือประสบพฤติการณ์ที่น่าเชื่อว่ามีการกระทำทารุณกรรมต่อเด็ก ให้รีบแจ้งหรือรายงานต่อพนักงานเจ้าหน้าที่ พนักงานฝ่ายปกครอง 
          หรือตำรวจ หรือผู้มีหน้าที่คุ้มครองสวัสดิภาพเด็กตามมาตรา 24
          - เมื่อพนักงานเจ้าหน้าที่ พนักงานฝ่ายปกครอง หรือตำรวจ หรือผู้มีหน้าที่คุ้มครองสวัสดิภาพเด็กตามมาตรา 24 ได้รับแจ้งเหตุตามวรรคหนึ่ง 
            หรือเป็นผู้พบเห็นหรือประสบพฤติการณ์ที่น่าเชื่อว่ามีการกระทำทารุณกรรมต่อเด็กในสถานที่ใด ให้มีอำนาจเข้าตรวจค้นและมีอำนาจแยกเด็กจากครอบครัวของเด็กเพื่อคุ้มครองสวัสดิภาพเด็กโดยเร็วที่สุด
          - การแจ้งหรือการรายงานตามมาตรานี้ เมื่อได้กระทำโดยสุจริตย่อมได้รับความคุ้มครองและไม่ต้องรับผิดทั้งทางแพ่ง ทางอาญา หรือทางปกครอง

มาตรา 42: การดำเนินการคุ้มครองสวัสดิภาพเด็กตามมาตรา 41 วรรคสอง ต้องรีบจัดให้มีการตรวจรักษาทางร่างกายและจิตใจทันที 
          ถ้าพนักงานเจ้าหน้าที่เห็นสมควรต้องสืบเสาะและพินิจเกี่ยวกับเด็กและครอบครัวเพื่อหาวิธีการคุ้มครองสวัสดิภาพที่เหมาะสมแก่เด็ก 
          ก็อาจส่งตัวเด็กไปสถานแรกรับก่อนได้หรือถ้าจำเป็นต้องให้การสงเคราะห์ก็ให้พิจารณาให้การสงเคราะห์ตามมาตรา 33 และถ้าจำเป็นต้องให้การฟื้นฟูสภาพจิตใจก็ให้รับเด็กไปยังสถานพัฒนาและฟื้นฟู
          - การส่งเด็กไปสถานแรกรับ สถานพัฒนาและฟื้นฟู หรือสถานที่อื่นตามวรรคหนึ่ง ระหว่างการสืบเสาะและพินิจเพื่อหาวิธีการคุ้มครองสวัสดิภาพที่เหมาะสม ให้กระทำได้ไม่เกิน 7 วัน
          - แต่ในกรณีที่มีเหตุจำเป็นและสมควรเพื่อประโยชน์ของเด็ก พนักงานเจ้าหน้าที่หรือพนักงานอัยการจะยื่นคำร้องต่อศาลตามมาตรา 5 เพื่อมีคำสั่งขยายระยะเวลาออกไปรวมแล้วไม่เกิน 30 วันก็ได้

มาตรา 43: ในกรณีที่ผู้ปกครองหรือญาติของเด็กเป็นผู้กระทำทารุณกรรมต่อเด็ก ถ้ามีการฟ้องคดีอาญาแก่ผู้กระทำผิดและมีเหตุอันควรเชื่อว่าผู้ถูกฟ้องนั้นจะกระทำทารุณกรรมแก่เด็กอีก 
          ก็ให้ศาลที่พิจารณาคดีนั้นมีอำนาจกำหนดมาตรการคุมความประพฤติผู้นั้น ห้ามเข้าเขตกำหนด หรือห้ามเข้าใกล้เด็กในระยะที่ศาลกำหนด เพื่อป้องกันมิให้กระทำการดังกล่าวและจะสั่งให้นำทัณฑ์บนตามวิธีการที่กำหนดไว้
          มาตรา 46 และมาตรา 47 แห่งประมวลกฎหมายอาญาด้วยก็ได้
          - หากยังไม่มีการฟ้องคดีอาญาหรือไม่ฟ้องคดีอาญาแต่มีพฤติการณ์น่าเชื่อว่าจะมีการกระทำทารุณกรรมแก่เด็กอีก ให้พนักงานเจ้าหน้าที่ 
            พนักงานฝ่ายปกครองหรือตำรวจ ผู้มีหน้าที่คุ้มครองสวัสดิภาพเด็กตามมาตรา 24 หรือพนักงานอัยการยื่นคำขอต่อศาลตามมาตรา 5 เพื่อออกคำสั่งมิให้กระทำการดังกล่าวโดยกำหนดมาตรการคุมความประพฤติและเรียกประกันด้วยก็ได้
          - ในกรณีตามวรรคหนึ่งและวรรคสอง หากศาลเห็นว่ามีเหตุจำเป็นเร่งด่วนเพื่อคุ้มครองมิให้เด็กถูกกระทำทารุณกรรมอีก ให้ศาลมีอำนาจออกคำสั่งให้ตำรวจจับกุมผู้ที่เชื่อว่า จะกระทำทารุณกรรมแก่เด็กมากักขังไว้มีกำหนดครั้งละไม่เกิน 30 วัน
          - การพิจารณาออกคำสั่งหรือการเรียกประกันตามมาตรานี้ ให้คำนึงถึงประโยชน์สูงสุดของเด็กเป็นสำคัญ

มาตรา 44: เมื่อพนักงานเจ้าหน้าที่หรือผู้มีหน้าที่คุ้มครองสวัสดิภาพเด็กตามมาตรา 24 พบเห็นหรือได้รับแจ้งจากผู้พบเห็นเด็กที่เสี่ยงต่อการกระทำผิดให้สอบถามเด็กและดำเนินการหาข้อเท็จจริงเกี่ยวกับตัวเด็ก 
          รวมถึงสภาพความสัมพันธ์ภายในครอบครัว ความเป็นอยู่ การเลี้ยงดู อุปนิสัย และความประพฤติของเด็กเพื่อทราบข้อมูลเกี่ยวกับเด็ก และถ้าเห็นว่าจำเป็นต้องคุ้มครองสวัสดิภาพเด็ก 
          โดยวิธีส่งเข้าสถานคุ้มครองสวัสดิภาพหรือสถานพัฒนาและฟื้นฟูก็ให้เสนอประวัติพร้อมความเห็นไปยังปลัดกระทรวงหรือผู้ว่าราชการจังหวัด แล้วแต่กรณี เพื่อพิจารณาสั่งให้ใช้วิธีการคุ้มครองสวัสดิภาพที่เหมาะสมแก่เด็ก
          - ในกรณีพนักงานเจ้าหน้าที่หรือผู้มีหน้าที่คุ้มครองสวัสดิภาพเด็กตามมาตรา 24 เห็นว่า เด็กจำเป็นต้องได้รับการสงเคราะห์ก็ให้พิจารณาให้การสงเคราะห์
            ตามมาตรา 33 แต่ถ้าเห็นว่ายังไม่สมควรส่งตัวเด็กไปยังสถานแรกรับ สถานสงเคราะห์ สถานคุ้มครองสวัสดิภาพ หรือสถานพัฒนาและฟื้นฟู ก็ให้มอบตัวเด็กแก่ผู้ปกครองหรือบุคคลที่ยินยอมรับเด็กไปปกครองดูแล 
            โดยอาจแต่งตั้งผู้คุ้มครองสวัสดิภาพแก่เด็กตามมาตรา 48 หรือไม่ก็ได้ และเมื่อได้ปรึกษาหารือร่วมกับผู้ปกครองหรือบุคคลที่จะรับเด็กไปปกครองดูแลแล้วอาจจะข้อกำหนดเพื่อป้องกันมิให้เด็กมีความประพฤติเสียหายหรือเสี่ยงต่อการกระทำผิด 
            ให้ผู้ปกครองหรือบุคคลที่รับเด็กไปปกครองดูแลต้องปฏิบัติข้อข้อหนึ่งหรือหลายข้อตามความเหมาะสม ดังต่อไปนี้
           (1) ระมัดระวังมิให้เด็กเข้าไปในสถานที่หรือท้องที่ใดอันจะจงใจให้เด็กประพฤติตนไม่สมควร
           (2) ระมัดระวังมิให้เด็กออกนอกสถานที่อยู่อาศัยในเวลากลางคืน เว้นแต่มีเหตุจำเป็นหรือไปกับผู้ปกครอง
           (3) ระมัดระวังมิให้เด็กคบหาสมาคมกับบุคคลหรือคณะบุคคลที่จะชักนำไปในทางเสื่อมเสีย
           (4) ระมัดระวังมิให้เด็กกระทำการอันเป็นเหตุให้เด็กประพฤติเสียหาย
           (5) จัดให้เด็กได้รับการศึกษาอบรมตามควรแก่อายุ สติปัญญา และความสนใจของเด็ก
           (6) จัดให้เด็กได้ประกอบอาชีพที่เหมาะสมกับความถนัดและความสนใจของเด็ก
           (7) จัดให้เด็กกระทำกิจกรรมเพื่อพัฒนาตนเองทางด้านคุณธรรม จริยธรรม และบำเพ็ญประโยชน์ต่อสังคม
              - หากปรากฏชัดว่าผู้ปกครองหรือผู้ที่รับเด็กไปปกครองดูแลไม่ปฏิบัติ ตามข้อกำหนดของพนักงานเจ้าหน้าที่หรือผู้มีหน้าที่คุ้มครองสวัสดิภาพเด็กตามมาตรา 24 ให้พนักงานเจ้าหน้าที่หรือผู้มีหน้าที่คุ้มครองสวัสดิภาพเด็กรับเด็กกลับไปดูแล

มาตรา 45: ห้ามมิให้เด็กซื้อหรือเสพสุราหรือบุหรี่ หรือเข้าไปในสถานที่เฉพาะเพื่อการจำหน่ายหรือเสพสุราหรือบุหรี่
          - หากฝ่าฝืน ให้พนักงานเจ้าหน้าที่สอบถามเด็กเพื่อทราบข้อมูลเกี่ยวกับเด็ก และมีหนังสือเรียกผู้ปกครองมาร่วมประชุมเพื่อปรึกษาหารือ ว่ากล่าวตักเตือน ให้ทำทัณฑ์บน 
            หรือมีข้อตกลงร่วมเกี่ยวกับวิธีการและระยะเวลาในการจัดทำงานบริการสังคมหรือทำงานสาธารณประโยชน์ และอาจวางข้อกำหนดให้ผู้ปกครองปฏิบัติข้อหนึ่งข้อใดตามมาตรา 44 วรรคสอง 
            หรือวางข้อกำหนดอื่นเพื่อแก้ไขหรือป้องกันมิให้เด็กกระทำความผิดขึ้นอีกก็ได้
          - หากปรากฏว่าผู้ปกครองของเด็กฝ่าฝืนบทบัญญัติในวรรคหนึ่ง ให้นำบทบัญญัติมาตรา 39 มาใช้บังคับโดยอนุโลม
          - การว่ากล่าวตักเตือน ทำทัณฑ์บน และจัดให้เด็กทำงานบริการสังคมหรือทำงานสาธารณประโยชน์ตามวรรคหนึ่ง ให้เป็นไปตามหลักเกณฑ์ วิธีการ และเงื่อนไขที่กำหนดในกฎกระทรวง

มาตรา 46: ในกรณีที่ปลัดกระทรวงหรือผู้ว่าราชการจังหวัดสั่งให้ส่งเด็กเข้ารับการคุ้มครองสวัสดิภาพ 
          หรือในกรณีพนักงานเจ้าหน้าที่ออกข้อกำหนดให้เด็กทำงานบริการสังคมหรือทำงานสาธารณประโยชน์ตามมาตรา 45 หากผู้ปกครองไม่เห็นด้วย 
          มีสิทธิยื่นคดีไปสู่ศาลตามมาตรา 5 ภายใน 180 วันนับแต่วันรับทราบคำสั่ง

มาตรา 47: วิธีการดำเนินการคุ้มครองสวัสดิภาพเด็ก นอกจากที่บัญญัติไว้ในหมวดนี้ ให้เป็นไปตามระเบียบที่คณะกรรมการกำหนด


  [หมวด 5: ผู้คุ้มครองสวัสดิภาพเด็ก]

มาตรา 48: ในดำเนินการสงเคราะห์ คุ้มครองสวัสดิภาพ และส่งเสริมความประพฤติเด็กตามพระราชบัญญัตินี้หรือกฎหมายอื่น 
          ถ้าพนักงานเจ้าหน้าที่เห็นว่ามีเหตุสมควรแต่งตั้งผู้คุ้มครองสวัสดิภาพเด็กเพื่อกำกับดูแลเด็กคนใด ให้ยื่นคำขอต่อปลัดกระทรวงหรือผู้ว่าราชการจังหวัด 
          แล้วแต่กรณี ให้แต่งตั้งพนักงานเจ้าหน้าที่ นักสังคมสงเคราะห์ หรือบุคคลที่สมัครใจและมีความเหมาะสมเป็นผู้คุ้มครองสวัสดิภาพเด็ก 
          โดยจะกำหนดสถานที่อยู่อาศัยของเด็กที่อยู่ในการกำกับดูแลของผู้คุ้มครองสวัสดิภาพเด็กด้วยก็ได้
         - กรณีที่เด็กพ้นจากความปกครองของสถานแรกรับ สถานสงเคราะห์ สถานคุ้มครองสวัสดิภาพ และสถานพัฒนาและฟื้นฟูแล้ว 
           ถ้ามีเหตุผลสมควรก็ให้ผู้ปกครองสวัสดิภาพยื่นคำขอต่อปลัดกระทรวงหรือผู้ว่าราชการจังหวัด แล้วแต่กรณี ให้แต่งตั้งพนักงานเจ้าหน้าที่ นักสังคมสงเคราะห์ 
           หรือบุคคลที่สมัครใจและมีความเหมาะสมเป็นผู้คุ้มครองสวัสดิภาพเด็กได้
         - การแต่งตั้งผู้คุ้มครองสวัสดิภาพเด็กให้มีระยะเวลาคราวละไม่เกิน 2 ปี

มาตรา 49: ผู้คุ้มครองสวัสดิภาพเด็กมีอำนาจและหน้าที่ ดังต่อไปนี้
         (1) เยี่ยมเยียน ให้คำปรึกษา แนะนำ และตักเตือนเกี่ยวกับเรื่องความประพฤติ การศึกษา และการประกอบอาชีพแก่เด็กที่อยู่ในการกำกับดูแล
         (2) เยี่ยมเยียน ให้คำปรึกษา และแนะนำแก่ผู้ปกครองเกี่ยวกับเรื่องการอบรมสั่งสอน และเลี้ยงดูเด็กที่อยู่ในการกำกับดูแล
         (3) จัดทำรายงานและความเห็นเกี่ยวกับสภาพความเป็นอยู่ของเด็กและของผู้ปกครองเสนอต่อปลัดกระทรวง ผู้ว่าราชการจังหวัด 
             พนักงานเจ้าหน้าที่ ผู้ปกครองสวัสดิภาพ คณะกรรมการ คณะกรรมการคุ้มครองเด็กกรุงเทพมหานคร หรือคณะกรรมการคุ้มครองเด็กจังหวัด แล้วแต่กรณี เพื่อดำเนินการต่อไป

มาตรา 50: ห้ามมิให้ผู้ปกครองสวัสดิภาพหรือผู้คุ้มครองสวัสดิภาพเด็ก เปิดเผยชื่อตัว ชื่อสกุล ภาพหรือข้อมูลใด ๆ เกี่ยวกับตัวเด็ก ผู้ปกครอง 
          ในลักษณะที่น่าจะเกิดความเสียหายแก่ชื่อเสียง เกียรติคุณ หรือสิทธิประโยชน์อย่างใดอย่างหนึ่งของเด็กหรือผู้ปกครอง
         - บทบัญญัติในวรรคหนึ่งให้ใช้บังคับแก่พนักงานเจ้าหน้าที่ นักสังคมสงเคราะห์ นักจิตวิทยา และผู้มีหน้าที่คุ้มครองสวัสดิภาพเด็กตามมาตรา 24 ซึ่งได้ล่วงรู้ข้อมูลดังกล่าวในการปฏิบัติหน้าที่ของตนด้วย โดยอนุโลม
         - ห้ามมิให้ผู้ใดโฆษณาหรือเผยแพร่ทางสื่อมวลชนหรือสื่อสารสนเทศประเภทใด ซึ่งข้อมูลที่เปิดเผยโดยฝ่าฝืนบทบัญญัติในวรรคหนึ่งหรือวรรคสอง

   [หมวด 6: สถานรับเลี้ยงเด็ก สถานแรกรับ สถานสงเคราะห์ สถานคุ้มครองสวัสดิภาพ และสถานพัฒนาและฟื้นฟู]

มาตรา 51: ปลัดกระทรวงมีอำนาจจัดตั้งสถานรับเลี้ยงเด็ก สถานแรกรับ สถานสงเคราะห์ สถานคุ้มครองสวัสดิภาพ และสถานพัฒนาและฟื้นฟู ได้ทั่วราชอาณาจักร และผู้ว่าราชการจังหวัดมีอำนาจจัดตั้งในเขตจังหวัด

มาตรา 52: ผู้ใดจะตั้งสถานรับเลี้ยงเด็ก สถานแรกรับ สถานสงเคราะห์ สถานคุ้มครองสวัสดิภาพ และสถานพัฒนาและฟื้นฟู ต้องรับใบอนุญาตจากปลัดกระทรวงหรือผู้ว่าราชการจังหวัด แล้วแต่กรณี
          - การขอรับใบอนุญาต การออกใบอนุญาต การขอต่ออายุใบอนุญาต การให้อายุใบอนุญาต การออกใบแทนใบอนุญาต การสั่งทำลาย หรือชำรุด การออกใบแทนใบอนุญาต 
            และการพักถอนใบอนุญาต ให้เป็นไปตามหลักเกณฑ์ วิธีการ และเงื่อนไขที่กำหนดในกฎกระทรวง และให้เสียค่าธรรมเนียมตามที่กำหนดในกฎกระทรวง

มาตรา 53: ให้กระทรวง พม. ผู้ว่าราชการจังหวัด คณะกรรมการ คณะกรรมการคุ้มครองเด็ก กทม. และคณะกรรมการคุ้มครองเด็กจังหวัด 
          กำกับดูแลและส่งเสริมสนับสนุนการดำเนินงานของสถานสงเคราะห์ สถานรับเลี้ยงเด็ก สถานคุ้มครองสวัสดิภาพ และสถานพัฒนาและฟื้นฟูที่อยู่ในเขตพื้นที่ที่รับผิดชอบ

มาตรา 54: สถานแรกรับ สถานสงเคราะห์ สถานคุ้มครองสวัสดิภาพ และสถานพัฒนาและฟื้นฟูที่พึ่งจะต้องดำเนินการในลักษณะแสวงหากำไรมิได้ทางธุรกิจ และต้องมีผู้ปกครองสวัสดิภาพ พนักงานดูแลและบังคับบัญชา
          - การดำเนินงานของสถานที่ตามวรรคหนึ่ง ให้เป็นไปตามกฎกระทรวงที่กำหนด

มาตรา 55: ให้ปลัดกระทรวงและผู้ว่าราชการจังหวัด มีอำนาจแต่งตั้งถอดถอนผู้ปกครองสวัสดิภาพของสถานแรกรับ สถานสงเคราะห์ สถานคุ้มครองสวัสดิภาพ และสถานพัฒนาและฟื้นฟู พนักงานสวัสดิภาพ วิธีการ และเงื่อนไขที่กำหนดในกฎกระทรวง

มาตรา 56: ในสถานแรกรับ สถานสงเคราะห์สถานรับเลี้ยงเด็กมีหลักเกณฑ์ดังต่อไปนี้
         (1) รับตัวเด็กที่จำต้องได้รับการสงเคราะห์หรือคุ้มครองสวัสดิภาพตามที่กำหนดไว้ สืบเสาะและพินิจเด็กและครอบครัววินิจฉัยกำหนดวิธีการที่เหมาะสมในการสงเคราะห์หรือคุ้มครองสวัสดิภาพแก่เด็กก่อน 
             ถ้าจำเป็นต้องให้การอุปการะตัวเด็กไปไม่เกินสามเดือน
         (2) สืบเสาะและพินิจเกี่ยวกับอายุ ประวัติ ความประพฤติ สติปัญญา การศึกษาอบรม สุขภาพ กาย จิตใจ อาชีพ 
             และฐานะของเด็กที่ต้องได้รับความสงเคราะห์หรือคุ้มครองสวัสดิภาพ รวมทั้งชื่อผู้ปกครอง หรือบุคคลที่เด็กอยู่อาศัย ตลอดจนสิ่งแวดล้อมที่เด็กอยู่อาศัยและฐานะของผู้ปกครองและผู้ที่เด็กอยู่ในการปกครองดูแล
         (3) จัดให้มีการพึงสุขภาพกายและสุขภาพจิต พร้อมทั้งดำเนินการรักษาพยาบาลแก่เด็กที่อยู่ในความปกครองดูแล
         (4) จัดที่พักอาศัย ที่หลับนอน เครื่องนุ่งห่ม ให้เหมาะสมและถูกสุขลักษณะ และจัดอาหารให้ถูกอนามัยและเพียงพอแก่เด็กที่อยู่ในความปกครองดูแล
         (5) จัดการศึกษา การกีฬา และนันทนาการให้แก่เด็กที่อยู่ในความปกครองดูแลให้เหมาะสมกับวัยและพัฒนาการทางด้านจิตใจ
         (6) จัดสรรจัดให้ดำเนินการตาม (1) (2) (3) (4) และ (5) ไปยังสถานแรกรับ สถานพัฒนาและฟื้นฟู โรงเรียน หรือสถานที่ที่จัดให้บริการสวัสดิภาพเด็กให้เหมาะสมกับวัยและสุขภาพกายสุขภาพจิตเด็กแตละคน
         (7) มอบตัวเด็กแก่ผู้ปกครอง หรือบุคคลที่เหมาะสมและยินยอมรับเด็กไว้ไปการะเลี้ยงดู และถ้าเห็นสมควรขอให้อำนาจปลัดกระทรวงหรือผู้ว่าราชการจังหวัด แล้วแต่กรณี แต่งตั้งผู้คุ้มครองสวัสดิภาพเด็กตามมาตรา 48
         (8) ให้คำปรึกษา แนะนำ และช่วยเหลือผู้ปกครอง ในกรณีเด็กจำต้องได้รับการสงเคราะห์หรือคุ้มครองสวัสดิภาพ
             - ผู้ปกครองสวัสดิภาพของสถานรับเลี้ยงเด็กดำเนินการให้เด็กสามารถกลับไปอยู่ในผู้ปกครอง ส่วนการจัดให้เด็กไปสถานสงเคราะห์ สถานคุ้มครองสวัสดิภาพ หรือสถานพัฒนาและฟื้นฟู ให้ดำเนินการเป็นปริทุษ

มาตรา 57: ผู้ปกครองสวัสดิภาพและผู้ปกครองสวัสดิภาพของสถานสงเคราะห์และสถานคุ้มครองสวัสดิภาพจัดตั้งขึ้นตามพระราชบัญญัตินี้ตามกฎหมายอื่นหรือควบคุมได้มีวันที่ที่ต้องรับภาระระวังให้เด็กอยู่ในการควบคุมไม่ให้มี 

มาตรา 58: ผู้ปกครองสวัสดิภาพของสถานสงเคราะห์มีอำนาจและหน้าที่ตามมาตรา 56 (1) (2) (3) (4) และ (5) และให้มีอำนาจหน้าที่ ดังต่อไปนี้
         (1) จัดการศึกษา อบรม สั่งสอน และฝึกอาชีพแก่เด็กผู้ที่อยู่ในความปกครองของสถานสงเคราะห์ให้เหมาะสมแก่, เด็กแต่ละคน
         (2) จัด/บริการแนะนำ ให้คำปรึกษา และช่วยเหลือผู้ปกครอง
         (3) สอดส่องและติดตาม ให้คำปรึกษา แนะนำ และช่วยเหลือบุคคลที่ออกจากสถานแรกรับไปแล้ว เพื่อเป็นการพิทักษ์คุ้มครองสวัสดิภาพเด็กที่อยู่ในความดูแลของครอบครัวที่มีกำลังสุขภาพ
             - การสืบเสาะและพินิจตามมาตรา 56 (2) ถ้าเป็นการเด็กที่ถูกส่งมาจากสถานรับยินดีรายงานการสืบเสาะและพินิจ และผลการสืบเสาะและพินิจได้

มาตรา 59: ผู้ปกครองสวัสดิภาพของสถานคุ้มครองสวัสดิภาพมีอำนาจและหน้าที่ ดังต่อไปนี้
         (1) ไปปกครองดูแล ประพฤติไม่พึงประสงค์ของผู้ที่มีผู้คุ้มครองสวัสดิภาพ
         (2) จัดการศึกษา อบรม และฝึกอาชีพแก่เด็กที่อยู่ในสถานคุ้มครองสวัสดิภาพ
         (3) แก้ไขความประพฤติ บำบัดรักษาและฟื้นฟูสมรรถภาพทั้งทางร่างกายและจิตใจแก่เด็กที่อยู่ในสถานคุ้มครองสวัสดิภาพ
         (4) สอดส่องและติดตามให้คำปรึกษา แนะนำ และช่วยเหลือแก่เด็กที่ออกจากสถานคุ้มครองสวัสดิภาพไปแล้ว


มาตรา 60: อำนาจหน้าที่ของผู้ปกครองสวัสดิภาพของสถานพัฒนาและฟื้นฟู
         (1) การรับเด็กกลุ่มที่ต้องได้รับการบำบัดฟื้นฟูสมรรถภาพทางร่างกายหรือจิตใจเข้ามาอยู่ในความดูแล
         (2) การรวบรวมข้อมูลและสืบเสาะข้อเท็จจริงเพื่อวางแผนแนวทางการพัฒนาและฟื้นฟูเด็กเป็นรายบุคคล
         (3) การจัดกิจกรรมการศึกษา ฝึกอบรม บำบัดรักษา และฟื้นฟูสภาพร่างกายและจิตใจให้สอดคล้องกับความจำเป็นของเด็กแต่ละคน

มาตรา 61: ข้อห้ามในการปฏิบัติต่อเด็กในสถานสงเคราะห์หรือสถานรองรับต่างๆ
           - ห้ามมิให้เจ้าของ ผู้ปกครองสวัสดิภาพ หรือเจ้าหน้าที่ผู้ปฏิบัติงานกระทำการทำร้ายร่างกาย จิตใจ กักขัง ทอดทิ้ง หรือลงโทษเด็กด้วยความรุนแรง
           - ข้อยกเว้น: การอบรมสั่งสอนที่กระทำด้วยความเหมาะสมตามขอบเขตและระเบียบที่รัฐมนตรีกำหนดไว้เท่านั้น

มาตรา 62: สถานะทางกฎหมายของผู้ปกครองสวัสดิภาพ
           - ให้ผู้ปกครองสวัสดิภาพมีฐานะเป็น "เจ้าพนักงาน" ตามประมวลกฎหมายอาญา เมื่อต้องปฏิบัติหน้าที่ตามพระราชบัญญัตินี้หรือตามคำสั่งที่ได้รับมอบหมาย

          
   [หมวด 7: การส่งเสริมความประพฤตินักเรียนและนักศึกษา]

มาตรา 63: โรงเรียนและสถานศึกษาต้องจัดให้มีระบบงานและกิจกรรมในการแนะแนว ให้คำปรึกษาและฝึกอบรมแก่นักเรียน นักศึกษา และผู้ปกครอง เพื่อส่งเสริมความประพฤติที่เหมาะสม 
          ความรับผิดชอบต่อสังคม และความปลอดภัยแก่นักเรียนและนักศึกษา ตามหลักเกณฑ์ วิธีการ และเงื่อนไขที่กำหนดในกฎกระทรวง

มาตรา 64: นักเรียนและนักศึกษาต้องประพฤติตนตามระเบียบของโรงเรียนหรือสถานศึกษาและตามที่กำหนดในกฎกระทรวง

มาตรา 65: นักเรียนหรือนักศึกษาผู้ใดฝ่าฝืนมาตรา 64 ให้พนักงานเจ้าหน้าที่ปฏิบัติตามระเบียบที่รัฐมนตรีกำหนด และมีอำนาจนำตัวไปมอบแก่ผู้บริหารโรงเรียนหรือสถานศึกษาของนักเรียนหรือนักศึกษานั้น 
          เพื่อดำเนินการสอบถามและอบรมสั่งสอนหรือลงโทษตามระเบียบ ในกรณีที่ไม่สามารถนำตัวไปได้จะแจ้งด้วยวาจาหรือเป็นหนังสือก็ได้
         - เมื่อได้อบรมสั่งสอนหรือลงโทษนักเรียนหรือนักศึกษาแล้ว ให้พนักงานเจ้าหน้าที่หรือผู้บริหารโรงเรียนหรือสถานศึกษาแจ้งให้ผู้ปกครองว่ากล่าวตักเตือนหรือสั่งสอนเด็กอีกชั้นหนึ่ง
         - การลงโทษนักเรียนหรือนักศึกษาให้กระทำเท่าที่สมควรเพื่อการอบรมสั่งสอนตามระเบียบที่รัฐมนตรีกำหนด

มาตรา 66: พนักงานเจ้าหน้าที่ตามหมวดนี้มีอำนาจดำเนินการเพื่อส่งเสริมความประพฤตินักเรียนและนักศึกษา ดังต่อไปนี้
         (1) สอบถามครู อาจารย์ หรือหัวหน้าสถานศึกษา เกี่ยวกับความประพฤติ การศึกษา นิสัย และสติปัญญาของนักเรียนหรือนักศึกษาที่ฝ่าฝืนมาตรา 64
         (2) เรียกให้ผู้ปกครอง ครู อาจารย์ หรือหัวหน้าสถานศึกษาที่นักเรียนหรือนักศึกษานั้นกำลังศึกษาอยู่มารับตัวนักเรียนหรือนักศึกษา เพื่อกล่าวอบรมสั่งสอนต่อไป
         (3) ให้คำแนะนำแก่ผู้ปกครองในเรื่องการอบรมและสั่งสอนนักเรียนหรือนักศึกษา
         (4) เรียกผู้ปกครองมากล่าวตักเตือน หรือทำทัณฑ์บนว่าจะปกครองดูแลมิให้นักเรียนหรือนักศึกษาฝ่าฝืนมาตรา 64 อีก
         (5) สอดส่องดูแลรวมทั้งรายงานต่อคณะกรรมการเกี่ยวกับพฤติกรรมของบุคคลหรือแหล่งที่ชักจูงนักเรียนหรือนักศึกษาให้ประพฤติในทางมิชอบ
         (6) ประสานงานกับผู้บริหารโรงเรียนหรือสถานศึกษา ครู ผู้ปกครอง ตำรวจ หรือพนักงานเจ้าหน้าที่อื่นเพื่อดำเนินการให้เป็นไปตามหมวดนี้

มาตรา 67: ในกรณีมีเหตุอันควรสงสัยว่ามีการฝ่าฝืนกฎหมายหรือระเบียบเกี่ยวกับความประพฤติของนักเรียนหรือนักศึกษา ให้พนักงานเจ้าหน้าที่ที่มีอำนาจเข้าไปในเคหสถาน สถานที่ 
          หรือยานพาหนะใด ๆ ในระหว่างเวลาพระอาทิตย์ขึ้นถึงพระอาทิตย์ตก หรือในระหว่างเวลาทำการ เพื่อทำการตรวจสอบการฝ่าฝืนดังกล่าว
          - ในการปฏิบัติหน้าที่ตามวรรคหนึ่ง พนักงานเจ้าหน้าที่ต้องแสดงบัตรประจำตัวก่อนและให้บุคคลที่เกี่ยวข้องอำนวยความสะดวกตามสมควร 
            บัตรประจำตัวพนักงานเจ้าหน้าที่ให้เป็นไปตามแบบที่รัฐมนตรีกำหนดโดยประกาศในราชกิจจานุเบกษา

          
      [หมวด 8: กองทุนคุ้มครองเด็ก]

มาตรา 68: ให้รัฐบาลจัดสรรงบประมาณเพื่อจัดตั้งกองทุนขึ้นกองทุนหนึ่งในสำนักงานปลัดกระทรวงการพัฒนาสังคมและความมั่นคงของมนุษย์ เรียกว่า "กองทุนคุ้มครองเด็ก" 
          เพื่อเป็นทุนใช้จ่ายในการสงเคราะห์ คุ้มครองสวัสดิภาพ และส่งเสริมความประพฤติเด็ก รวมทั้งครอบครัวและครอบครัวอุปถัมภ์ของเด็กตามพระราชบัญญัตินี้

มาตรา 69: กองทุนประกอบด้วย
         (1) เงินประเดิมที่รัฐบาลจัดสรรให้
         (2) เงินที่ได้รับจากงบประมาณรายจ่ายประจำปี
         (3) เงินหรือทรัพย์สินที่มีผู้บริจาคหรือมอบให้
         (4) เงินอุดหนุนจากต่างประเทศหรือองค์การระหว่างประเทศ
         (5) เงินหรือทรัพย์สินที่ตกเป็นของกองทุนพึ่งหรือได้ตามกฎหมายหรือพินัยกรรม
         (6) เงินที่ได้จากการประกันผู้ปกครองที่ผิดทัณฑ์บนตามมาตรา 39
         (7) ดอกผลหรือหาผลประโยชน์จากทรัพย์สินของกองทุน

มาตรา 70: เงินและดอกผลของกองทุนไม่ต้องนำส่งกระทรวงการคลังเป็นรายแผ่นดิน

มาตรา 71: ให้มีคณะกรรมการบริหารกองทุนคณะหนึ่ง ประกอบด้วย ปลัดกระทรวงการพัฒนาสังคมและความมั่นคงของมนุษย์ 
          เป็นประธานกรรมการ ปลัดกระทรวงมหาดไทย ปลัดกระทรวงการอุดมศึกษา วิทยาศาสตร์ วิจัยและนวัตกรรม ผู้แทนสำนักงบประมาณ 
          ผู้แทนกระทรวงการคลัง และผู้ทรงคุณวุฒิ ซึ่งคณะกรรมการแต่งตั้งไม่เกินสามคน ในจำนวนนี้ต้องมีผู้แทนภาคเอกชนที่เกี่ยวข้องกับด้านสวัสดิการเด็กไม่น้อยกว่าหนึ่งคน 
          เป็นกรรมการ และให้ปลัดกระทรวงการพัฒนาสังคมและความมั่นคงของมนุษย์ เป็นกรรมการและเลขานุการ

มาตรา 72: ให้นำบทบัญญัติมาตรา 9 มาตรา 10 มาตรา 11 มาตรา 12 และมาตรา 13 มาใช้บังคับกับการดำรงตำแหน่ง การพ้นจากตำแหน่ง และการประชุมของกรรมการบริหารกองทุน และการแต่งตั้งคณะอนุกรรมการกองทุน โดยอนุโลม

มาตรา 73: ให้คณะกรรมการบริหารกองทุนมีอำนาจหน้าที่ ดังต่อไปนี้
          (1) บริหารกองทุนให้เป็นไปตามระเบียบที่คณะกรรมการกำหนด
          (2) พิจารณาอนุมัติการจ่ายเงินเพื่อการสงเคราะห์ คุ้มครองสวัสดิภาพ และส่งเสริมความประพฤติเด็ก รวมทั้งครอบครัวและครอบครัวอุปถัมภ์เด็กตามพระราชบัญญัตินี้ และตามมาตรการที่กำหนดหรือตามคำสั่งศาล
          (3) รายงานสถานะการเงินและการบริหารกองทุนต่อคณะกรรมการตามระเบียบที่คณะกรรมการกำหนด

มาตรา 74: การรับเงิน การจ่ายเงิน การเก็บรักษาเงิน การพัฒนาประโยชน์และการจัดการทุน ให้เป็นไปตามระเบียบที่คณะกรรมการกำหนด

มาตรา 75: ให้คณะกรรมการติดตามและประเมินผลการดำเนินงานของกองทุน ประกอบด้วย ประธานกรรมการ ประกรรมการการผู้ทรงคุณวุฒิผู้มีความรู้ความสามารถด้านการเงิน 
          การสวัสดิการเด็ก และประเมินและให้รองปลัดกระทรวงการพัฒนาสังคมและความมั่นคงของมนุษย์ เป็นกรรมการและเลขานุการ
           - ให้นำบทบัญญัติมาตรา 9 มาตรา 10 มาตรา 11 มาตรา 12 และมาตรา 13 มาใช้บังคับกับการดำรงตำแหน่ง การพ้นจากตำแหน่ง และการประชุมของกรรมการติดตามและประเมินผลตามวรรคหนึ่ง โดยอนุโลม

มาตรา 76: คณะกรรมการติดตามและประเมินผลตามมาตรา 75 มีอำนาจหน้าที่ ดังต่อไปนี้
          (1) ติดตาม ตรวจสอบ และประเมินผลการดำเนินงานของกองทุน
          (2) รายงานผลการปฏิบัติงานพร้อมทั้งข้อเสนอแนะต่อคณะกรรมการ
          (3) มีอำนาจเรียกเอกสารหรือหลักฐานที่เกี่ยวข้องกับกองทุนจากบุคคลใดหรือเรียกบุคคลใดมามาชี้แจงข้อเท็จจริงเพื่อประกอบการพิจารณาประเมินผล

มาตรา 77: ให้คณะกรรมการบริหารกองทุนจัดทำงบดุลและบัญชีทำการส่งผู้บัญชีตรวจสอบภายใน 120 วันนับแต่วันสิ้นปีบัญชีทุกปี
          - ให้สำนักงานการตรวจเงินแผ่นดินเป็นผู้สอบบัญชีของกองทุนทุกรอบปี แล้วทำรายงานผลการสอบและรับรองบัญชีและการเงินของกองทุน
            เสนอต่อคณะกรรมการภายใน 150 วันนับแต่วันสิ้นปีบัญชี เพื่อคณะกรรมการเสนอต่อคณะกรรมการรัฐมนตรีเพื่อทราบ
          - รายงานผลการสอบบัญชีตามวรรคสองให้รัฐมนตรีเสนอ ต่อนายกรัฐมนตรีเพื่อนำเสนอต่อรัฐสภาทราบและจัดให้มีการประกาศในราชกิจจานุเบกษา

        
     [หมวด 9: บทกำหนดโทษ]

มาตรา 78: ผู้ใดฝ่าฝืนมาตรา 66 ต้องระวางโทษจำคุกไม่เกิน 3 เดือน หรือปรับไม่เกิน 30,000 บาท หรือทั้งจำทั้งปรับ

มาตรา 79: ผู้ใดฝ่าฝืนมาตรา 27 มาตรา 50 หรือมาตรา 60 ต้องระวางโทษจำคุกไม่เกิน 6 เดือน หรือปรับไม่เกิน 60,000 บาท หรือทั้งจำทั้งปรับ

มาตรา 80: ผู้ใดขัดขวางไม่ให้พนักงานเจ้าหน้าที่ปฏิบัติตามมาตรา 30 (1) หรือ (5) 
          หรือไม่ยอมส่งเอกสารหรือส่งเอกสารโดยรู้อยู่ว่าเป็นเอกสารเท็จแก่พนักงานเจ้าหน้าที่เมื่อถูกเรียกให้ส่งตามมาตรา 30 (4) ต้องระวางโทษจำคุกไม่เกิน 1 เดือน หรือปรับไม่เกิน 10,000 บาท หรือทั้งจำทั้งปรับ
          - ผู้ใดไม่ยอมมาให้ถ้อยคำ ไม่ยอมให้ถ้อยคำโดยไม่มีเหตุอันสมควร หรือให้ถ้อยคำอันเป็นเท็จต่อพนักงานเจ้าหน้าที่ซึ่งปฏิบัติหน้าที่ตามมาตรา 30 
            (3) ต้องระวางโทษจำคุกไม่เกิน 1 เดือน หรือปรับไม่เกิน 10,000 บาท หรือทั้งจำทั้งปรับ แต่ถ้าผู้ให้ถ้อยคำกลับให้ข้อความจริงในขณะที่การให้ถ้อยคำยังไม่เสร็จสิ้น การดำเนินคดีอาญาต่อบุคคลนั้นให้เป็นอันระงับไป

มาตรา 81: ผู้ใดฝ่าฝืนข้อกำหนดในการคุมความประพฤติ ห้ามเข้าเขตกำหนด หรือห้ามเข้าใกล้เด็กตามมาตรา 43 ต้องระวางโทษจำคุกไม่เกิน 6 เดือน หรือปรับไม่เกิน 60,000 บาท หรือทั้งจำทั้งปรับ

มาตรา 82: ผู้ใดจัดตั้งหรือดำเนินกิจการสถานรับเลี้ยงเด็ก สถานแรกรับ สถานสงเคราะห์ สถานคุ้มครองสวัสดิภาพ 
          หรือสถานพัฒนาและฟื้นฟูตามมาตรา 52 โดยมิได้รับใบอนุญาต หรือใบอนุญาตถูกเพิกถอนหรือหมดอายุ ต้องระวางโทษจำคุกไม่เกิน 1 ปี หรือปรับไม่เกิน 100,000 บาท หรือทั้งจำทั้งปรับ
          - ผู้ฝ่าฝืนในวรรคหนึ่งในกรณีที่สั่งคืนอนุญาตหรือใบอนุญาตในระยะเวลาที่พนักงานเจ้าหน้าที่กำหนด การดำเนินคดีอาญาต่อบุคคลนั้นให้เป็นอันระงับไป

มาตรา 83: เจ้าของหรือผู้ปกครองสวัสดิภาพของสถานรับเลี้ยงเด็ก สถานแรกรับ สถานสงเคราะห์ สถานคุ้มครองสวัสดิภาพ หรือสถานพัฒนาและฟื้นฟูที่เปิดดำเนินการโดยไม่ได้รับใบอนุญาตจากปลัดกระทรวงหรือผู้ว่าราชการจังหวัด 
          หรือไม่ปฏิบัติตามพระราชบัญญัตินี้ หรือผู้ปกครองของเด็ก ฝ่าฝืนหรือไม่ปฏิบัติตามพระราชบัญญัตินี้ ต้องระวางโทษจำคุกไม่เกิน 6 เดือน หรือปรับไม่เกิน 60,000 บาท หรือทั้งจำทั้งปรับ
          -ผู้ฝ่าฝืนบทบัญญัติในวรรคหนึ่งในกรณีที่ปฏิบัติการในระเบียบหรือประกาศพนักงานเจ้าหน้าที่หรือผู้มีหน้าที่คุ้มครองสวัสดิภาพตามมาตรา 24 แก่, การดำเนินคดีอาญาต่อบุคคลนั้นให้เป็นอันระงับไป

มาตรา 84: ผู้กระทำการเป็นผู้ปกครองสวัสดิภาพของสถานแรกรับ สถานสงเคราะห์ สถานคุ้มครองสวัสดิภาพ และสถานพัฒนาและฟื้นฟู ที่ได้รับแต่งตั้งตามมาตรา 55 ต้องระวางโทษจำคุกไม่เกิน 1 เดือน หรือปรับไม่เกิน 10,000 บาท หรือทั้งจำทั้งปรับ

มาตรา 85: ผู้ใดกระทำการอันเป็นการยุยง ส่งเสริม สนับสนุนให้นักเรียนหรือนักศึกษาฝ่าฝืนมาตรา 64 ต้องระวางโทษจำคุกไม่เกิน 3 เดือน หรือปรับไม่เกิน 30,000 บาท หรือทั้งจำทั้งปรับ

มาตรา 86: ผู้ใดไม่ปฏิบัติตามความต้องการของพนักงานเจ้าหน้าที่ผู้ปฏิบัติหน้าที่ตามมาตรา 85 ต้องระวางโทษจำคุกไม่เกิน 1 เดือน หรือปรับไม่เกิน 10,000 บาท หรือทั้งจำทั้งปรับ

[บทเฉพาะกาล]

มาตรา 87: ให้สถานรับเลี้ยงเด็ก สถานแรกรับ สถานสงเคราะห์ สถานคุ้มครองสวัสดิภาพเด็กตามพระราชบัญญัติควบคุมการขอทาน 
          หรือได้รับใบอนุญาตตามกฎหมายว่าด้วยการควบคุมการขอทาน ในวันที่ 29 พฤศจิกายน พ.ศ. 2542 
          ที่ดำเนินการอยู่เดิมในวันใช้บังคับพ.ร.บ. นี้ ให้ถือเป็นสถานรับเลี้ยงเด็ก สถานแรกรับ สถานสงเคราะห์ และสถานคุ้มครองสวัสดิภาพตามพระราชบัญญัตินี้

มาตรา 88: บรรดากฎกระทรวง ข้อบังคับ ระเบียบ ประกาศ หรือคำสั่งที่ออกตามประกาศของคณะปฏิวัติ 
          ฉบับที่ 132 ลงวันที่ 22 เมษายน พ.ศ. 2515 ให้คงใช้บังคับต่อไปเท่าที่ไม่ขัดหรือแย้งกับพระราชบัญญัตินี้ จนกว่าจะมีการออกกฎกระทรวง ข้อบังคับ ระเบียบ ประกาศ หรือคำสั่งตามพระราชบัญญัตินี้


**พระราชบัญญัติหอพัก พ.ศ. 2558**

มาตรา 1: พระราชบัญญัตินี้เรียกว่า "พระราชบัญญัติหอพัก พ.ศ. 2558"

มาตรา 2: พระราชบัญญัตินี้ให้ใช้บังคับเมื่อพ้นกำหนด 180 วัน นับแต่วันประกาศในราชกิจจานุเบกษาเป็นต้นไป

มาตรา 3: ให้ยกเลิกพระราชบัญญัติหอพัก พ.ศ. 2507

มาตรา 4: บทนิยามศัพท์ที่สำคัญในพระราชบัญญัตินี้
        - "หอพัก" หมายความว่า สถานที่ที่จัดตั้งขึ้นตามพระราชบัญญัตินี้เพื่อ 
               (1) ให้ผู้พักอาศัยอยู่โดยมีการเรียกเก็บค่าเช่า
               (2) ให้บริการหรือให้การช่วยเหลือแก่ผู้พักอาศัย
        - "ผู้พัก" หมายความว่า ผู้ซึ่งอยู่ระหว่างการศึกษาในสถานศึกษาในระดับไม่เกินปริญญาตรีและมีอายุไม่เกิน 25 ปี
        - "หอพักสถานศึกษา" หมายความว่า หอพักที่ผู้ประกอบกิจการหอพักเป็นสถานศึกษา
        - "หอพักเอกชน" หมายความว่า หอพักที่ผู้ประกอบกิจการหอพักมิใช่สถานศึกษา
        - "สถานศึกษา" หมายความว่า โรงเรียน วิทยาลัย สถาบัน มหาวิทยาลัย 
           ที่จัดการศึกษาในระบบตามกฎหมายว่าด้วยการศึกษาแห่งชาติ (ไม่หมายความรวมถึงมหาวิทยาลัยและวิทยาลัยที่จัดการศึกษาในระดับอุดมศึกษา)
        - "ผู้รับใบอนุญาตตั้งหอพัก" หมายความว่า ผู้ได้รับใบอนุญาตประกอบกิจการหอพักตามพระราชบัญญัตินี้
        - "ผู้จัดการหอพัก" หมายความว่า ผู้มีหน้าที่ควบคุมดูแลหอพักหรือสถานศึกษาหรือพนักงานตามสถานศึกษาตามพระราชบัญญัตินี้
        - "เงินประกัน" หมายความว่า เงินที่ผู้พักวางไว้กับผู้ประกอบกิจการหอพักเพื่อประกันความเสียหายหรือหนี้สินที่เกิดจากการทำสัญญาเช่าหอพักให้แก่ผู้พักสอย
        - "กฎหมายเกี่ยวกับยาเสพติด" หมายความว่า กฎหมายว่าด้วยยาเสพติดให้โทษ กฎหมายว่าด้วยวัตถุที่ออกฤทธิ์ต่อจิตและประสาท 
           กฎหมายว่าด้วยการป้องกันและปราบปรามการใช้สาระระเหย และกฎหมายอื่นเพื่อการปราบปรามการกระทำความผิดเกี่ยวกับยาเสพติด
        - "องค์กรปกครองส่วนท้องถิ่น" หมายความว่า เทศบาล องค์การบริหารส่วนตำบล กรุงเทพมหานคร เมืองพัทยา และองค์กรส่วนท้องถิ่นอื่นที่มีกฎหมายจัดตั้ง ทั้งนี้ ไม่รวมความถึงองค์การบริหารส่วนจังหวัด
        - "คณะกรรมการ" หมายความว่า คณะกรรมการส่งเสริมกิจการหอพัก
        - "นายทะเบียน" หมายความว่า
               (1) นายกเทศมนตรี สำหรับในเขตเทศบาล
               (2) นายกองค์การบริหารส่วนตำบล สำหรับในเขตองค์การบริหารส่วนตำบล
               (3) ผู้ว่าราชการกรุงเทพมหานคร สำหรับในเขตกรุงเทพมหานคร
               (4) นายกเมืองพัทยา สำหรับในเขตเมืองพัทยา
               (5) ผู้บริหารท้องถิ่นหรือหัวหน้าพนักงานส่วนท้องถิ่นที่มีกฎหมายจัดตั้งสำหรับในเขตองค์กรปกครองส่วนท้องถิ่นอื่นที่มีกฎหมายจัดตั้งสำหรับในเขตองค์กรปกครองส่วนท้องถิ่น
                   - "พนักงานเจ้าหน้าที่" หมายความว่า ผู้ซึ่งรัฐมนตรีแต่งตั้งให้ปฏิบัติการตามพระราชบัญญัตินี้
                   - "รัฐมนตรี" หมายความว่า รัฐมนตรีผู้รักษาการตามพระราชบัญญัตินี้

มาตรา 5: ให้รัฐมนตรีว่าการกระทรวงการพัฒนาสังคมและความมั่นคงของมนุษย์ รัฐมนตรีว่าการกระทรวงการอุดมศึกษา วิทยาศาสตร์ 
         วิจัยและนวัตกรรม รัฐมนตรีว่าการกระทรวงมหาดไทย และรัฐมนตรีว่าการกระทรวงศึกษาธิการ รักษาการตามพระราชบัญญัตินี้ 
         และให้มีอำนาจออกกฎกระทรวงและประกาศเพื่อปฏิบัติการตามพระราชบัญญัตินี้ในส่วนที่เกี่ยวกับอำนาจหน้าที่ของตน

        
  [หมวด 1: บททั่วไป]

มาตรา 6: บุคคลใดจัดสถานที่เพื่อรับผู้พักเข้าพักอาศัยโดยเรียกเก็บค่าเช่า ให้ถือว่าบุคคลนั้นประกอบกิจการหอพัก

มาตรา 7: พระราชบัญญัตินี้ไม่ใช้บังคับแก่หอพักของกระทรวง ทบวง กรม หรือหน่วยงานอื่นของรัฐที่ไม่ใช่สถานศึกษา

มาตรา 8: หอพักมี 2 ประเภท ได้แก่
         (1) หอพักชาย
         (2) หอพักหญิง

มาตรา 9: การรับผู้พัก ผู้ประกอบกิจการหอพักต้องทำสัญญาเช่าเป็นหนังสือ โดยระบุว่าผู้ประกอบกิจการหอพักต้องมีหอพักตามแบบที่คณะกรรมการกำหนด ซึ่งอย่างน้อยมีรายการ ดังต่อไปนี้
         (1) ชื่อและที่อยู่ของผู้ประกอบกิจการและผู้พัก
         (2) วันที่ทำสัญญา
         (3) ระยะเวลาการเข้าพักซึ่งต้องไม่น้อยกว่าหนึ่งภาคการศึกษาหรือตามระยะเวลาที่คณะกรรมการประกาศกำหนด
         (4) ความยินยอมของผู้ปกครองในกรณีที่ผู้พักเป็นผู้เยาว์
         (5) รายการอื่นตามที่คณะกรรมการกำหนด

มาตรา 10: ผู้ประกอบกิจการหอพักจะเรียกเก็บเงินค่าเช่าล่วงหน้าได้ไม่เกินค่าเช่าสามเดือน โดยให้นำค่าเช่าล่วงหน้าดังกล่าวเป็นค่าเช่าเดือนสุดท้ายของสัญญาเช่า
           - ในกรณีที่ผู้พักเลิกสัญญาก่อนครบกำหนดตามสัญญาเช่า ผู้พักจะระงับการเช่าหนี้ผู้ประกอบกิจการหอพักมี

มาตรา 11: ผู้ประกอบกิจการหอพักจะเรียกเก็บเงินประกันไม่ได้ไม่เกินค่าเช่าสี่เดือน
           - ผู้ประกอบกิจการหอพักต้องคืนเงินประกันให้แก่ผู้พักในวันสิ้นสุดสัญญาเช่า ทั้งนี้ ตามจำนวนที่เหลืออยู่หักจากค่าเสียหายที่ทำให้เกิดขึ้นในทรัพย์สินของผู้ประกอบกิจการหอพักไว้ให้แก่ผู้พักสอย

มาตรา 12: บทบัญญัติในมาตรา 10 และมาตรา 11 ไม่ใช้บังคับแก่หอพักของโรงเรียนประจำ

มาตรา 13: บรรดาค่าธรรมเนียม ค่าปรับ และรายได้อื่น ๆ ที่เกี่ยวกับการกิจการหอพักตามพระราชบัญญัตินี้ ให้ตกเป็นรายได้ขององค์กรปกครองส่วนท้องถิ่นที่หอพักนั้นตั้งอยู่

[หมวด 2: คณะกรรมการส่งเสริมกิจการหอพัก]

มาตรา 14: ให้มีคณะกรรมการคณะหนึ่ง เรียกว่า "คณะกรรมการส่งเสริมกิจการหอพัก" ประกอบด้วย
           - รัฐมนตรีว่าการกระทรวงการพัฒนาสังคมและความมั่นคงของมนุษย์ เป็นประธานกรรมการ
           - ปลัดกระทรวงการพัฒนาสังคมและความมั่นคงของมนุษย์ เป็นรองประธานกรรมการ
           - กรรมการโดยตำแหน่ง ได้แก่ ปลัดกระทรวงการคลัง, ปลัดกระทรวงการอุดมศึกษา วิทยาศาสตร์ 
            วิจัยและนวัตกรรม, ปลัดกระทรวงมหาดไทย, ปลัดกระทรวงศึกษาธิการ, เลขาธิการคณะกรรมการการศึกษาขั้นพื้นฐาน
            ,เลขาธิการคณะกรรมการการอาชีวศึกษา, ผู้บัญชาการตำรวจแห่งชาติ, อธิบดีกรมการปกครอง, และอธิบดีกรมส่งเสริมการปกครองท้องถิ่น
           - กรรมการผู้ทรงคุณวุฒิ: จำนวน 3 คน ซึ่งคณะกรรมการแต่งตั้งจากผู้มีความรู้ ความเชี่ยวชาญ มีผลงาน 
             และมีประสบการณ์เป็นที่ประจักษ์ในด้านสวัสดิการสังคมและการหอพัก (โดยต้องมีผู้แทนภาคเอกชนไม่น้อยกว่า 1 คน)
           - ให้ผู้แทนกรมกิจการเด็กและเยาวชน เป็นกรรมการและเลขานุการ และให้ผู้แทนกรมกิจการเด็กและเยาวชนแต่งตั้งข้าราชการในกรมกิจการเด็กและเยาวชนไม่เกิน 2 คน เป็นผู้ช่วยเลขานุการ
           - กรรมการผู้ทรงคุณวุฒิตามวรรคหนึ่ง ให้แต่งตั้งจากผู้ทรงคุณวุฒิที่มีประสบการณ์เกี่ยวข้องกับเรื่องที่ดิน อสังหาริมทรัพย์ หรือการบริหารสำนักงาน และผู้แทนสมาคมผู้ประกอบกิจการหอพักจำนวนหนึ่งคน

มาตรา 15: คณะกรรมการมีอำนาจหน้าที่ ดังต่อไปนี้
           (1) เสนอความเห็นต่อคณะรัฐมนตรีเพื่อให้ความเห็นชอบเกี่ยวกับนโยบาย แผนงาน มาตรการ การส่งเสริมและพัฒนากิจการหอพัก
           (2) เสนอความเห็นต่อคณะรัฐมนตรีในการใช้ประโยชน์ทางภาษีอากรในกิจการหอพักตามพระราชบัญญัตินี้
           (3) เสนอความเห็นและกฎหมายเกี่ยวกับการกำหนดหลักเกณฑ์เงื่อนไขการประกวดหอพัก 
               และการให้การสนับสนุนหอพักที่ได้รับการประกาศเกียรติคุณ รวมทั้งการออกกฎกระทรวงและประกาศตามพระราชบัญญัตินี้
           (4) ออกประกาศกำหนดหลักเกณฑ์เกี่ยวกับหอพักตามพระราชบัญญัตินี้
           (5) ติดตาม บำรุง และตรวจสอบประสิทธิภาพในการบังคับใช้ และเสนอแนะแนวทางในการใช้สิทธิพระราชบัญญัตินี้
           (6) ปฏิบัติการอื่นใดตามที่กฎหมายกำหนดให้เป็นอำนาจหน้าที่ของคณะกรรมการหรือตามที่คณะรัฐมนตรีมอบหมาย

มาตรา 16: กรรมการผู้ทรงคุณวุฒิมีวาระการดำรงตำแหน่งคราวละ 2 ปี
           - เมื่อครบกำหนดตามวาระในวรรคหนึ่ง หากยังมิได้มีการแต่งตั้งกรรมการผู้ทรงคุณวุฒิรายใหม่ 
             ให้กรรมการผู้ทรงคุณวุฒิพ้นจากตำแหน่งมาระยะเวลานั้นอยู่ในตำแหน่งเพื่อดำเนินต่อไปจนกว่ากรรมการผู้ทรงคุณวุฒิที่ได้รับแต่งตั้งใหม่จะเข้ารับหน้าที่
           - กรรมการผู้ทรงคุณวุฒิซึ่งพ้นจากตำแหน่งตามวาระจะได้รับแต่งตั้งใหม่อีกได้ แต่จะดำรงตำแหน่งติดต่อกันเกินสองวาระไม่ได้

มาตรา 17: นอกจากการพ้นจากตำแหน่งตามวาระ กรรมการผู้ทรงคุณวุฒิพ้นจากตำแหน่ง เมื่อ
           (1) ตาย
           (2) ลาออก
           (3) ประธานกรรมการให้ออก เพราะบกพร่องต่อหน้าที่ มีความประพฤติเสื่อมเสีย หรือหย่อนความสามารถ
           (4) ได้รับโทษจำคุกโดยคำพิพากษาถึงที่สุดให้จำคุก
           (5) เป็นบุคคลล้มละลาย
           (6) เป็นคนไร้ความสามารถหรือคนเสมือนไร้ความสามารถ
           (7) พ้นจากการเป็นผู้แทนสมาคมผู้ประกอบกิจการหอพัก ในกรณีที่ได้รับแต่งตั้งให้เป็นกรรมการในฐานะนั้น

มาตรา 18: ในกรณีที่กรรมการผู้ทรงคุณวุฒิพ้นจากตำแหน่งก่อนวาระ ให้ประธานกรรมการแต่งตั้งกรรมการผู้ทรงคุณวุฒิในประเภทเดียวกันเป็นกรรมการแทน 
          และให้ผู้ได้รับแต่งตั้งให้ดำรงตำแหน่งแทนอยู่ในตำแหน่งเท่ากับวาระที่เหลืออยู่ของกรรมการผู้ทรงคุณวุฒิซึ่งตนแทน
           - ในกรณีที่กรรมการผู้ทรงคุณวุฒิพ้นจากตำแหน่งก่อนวาระ ให้คณะกรรมการประกอบด้วยกรรมการเท่าที่มีอยู่จนกว่าจะมีการแต่งตั้งกรรมการผู้ทรงคุณวุฒิแทนในวรรคหนึ่ง

มาตรา 19: การประชุมของคณะกรรมการต้องมีกรรมการมาประชุมไม่น้อยกว่ากึ่งหนึ่งของจำนวนกรรมการทั้งหมดจึงจะเป็นองค์ประชุม
           - ในการประชุมคณะกรรมการ ถ้าประธานกรรมการไม่มาประชุมหรือไม่สามารถปฏิบัติหน้าที่ได้ ให้รองประธานกรรมการเป็นประธาน 
             ถ้าประธานกรรมการไม่มาประชุมและรองประธานกรรมการไม่มาประชุมหรือไม่สามารถปฏิบัติหน้าที่ได้ ให้กรรมการซึ่งมาประชุมเลือกกรรมการคนหนึ่งเป็นประธานในที่ประชุม
           - การวินิจฉัยชี้ขาดของที่ประชุมให้ถือเสียงข้างมาก กรรมการคนหนึ่งให้มีเสียงหนึ่งในการลงคะแนน ถ้าคะแนนเสียงเท่ากัน ให้ประธานในที่ประชุมออกเสียงเพิ่มขึ้นอีกเสียงหนึ่งเป็นเสียงชี้ขาด

มาตรา 20: คณะกรรมการมีอำนาจแต่งตั้งคณะอนุกรรมการเพื่อพิจารณาหรือปฏิบัติการอย่างใดอย่างหนึ่งตามที่คณะกรรมการมอบหมายได้
          - การประชุมคณะอนุกรรมการ ให้นำมาตรา 19 มาใช้บังคับโดยอนุโลม

มาตรา 21: ให้กรมกิจการเด็กและเยาวชนรับผิดชอบงานธุรการ งานประชุม การศึกษาข้อมูลและการกิจการต่าง ๆ ที่เกี่ยวข้องของงานกรรมการและคณะอนุกรรมการที่คณะกรรมการแต่งตั้ง

มาตรา 22: ให้มีคณะกรรมการส่งเสริมกิจการหอพักกรุงเทพมหานคร ประกอบด้วย ผู้ว่าราชการกรุงเทพมหานคร เป็นประธานกรรมการ 
          ผู้แทนสำนักงานปลัดกระทรวงการพัฒนาสังคมและความมั่นคงของมนุษย์ ผู้แทนสำนักงานปลัดกระทรวงการอุดมศึกษา วิทยาศาสตร์ วิจัยและนวัตกรรม ผู้แทนสำนักงานปลัดกระทรวงมหาดไทย 
          ผู้แทนสำนักงานปลัดกระทรวงศึกษาธิการ ผู้แทนกรมกิจการเด็กและเยาวชน อธิบดีกรมส่งเสริมการปกครองท้องถิ่น ผู้แทนกองบัญชาการตำรวจนครบาล อำนวยการสำนักการโยธา ผู้อำนวยการสำนักการศึกษา 
          ผู้อำนวยการสำนักพัฒนาชุมชน ผู้อำนวยการสำนักอนามัย และกรรมการผู้ทรงคุณวุฒิซึ่งผู้ว่าราชการกรุงเทพมหานครแต่งตั้งจากผู้เชี่ยวชาญที่มีประสบการณ์ด้านการศึกษา จิตวิทยา กฎหมาย และกิจการหอพักจำนวนไม่เกินหนึ่งคน เป็นกรรมการ
          - ให้ผู้อำนวยการสำนักพัฒนาสังคม เป็นกรรมการและเลขานุการ และให้ผู้อำนวยการสำนักพัฒนาสังคมแต่งตั้งข้าราชการในสำนักพัฒนาสังคมไม่เกินสองคน เป็นผู้ช่วยเลขานุการ

มาตรา 23: ให้มีคณะกรรมการส่งเสริมกิจการหอพักจังหวัด ประกอบด้วย ผู้ว่าราชการจังหวัด เป็นประธานกรรมการ ปลัดจังหวัด 
          เป็นรองประธานกรรมการ พัฒนาการจังหวัด พัฒนาสังคมและความมั่นคงของมนุษย์จังหวัด โยธาธิการและผังเมืองจังหวัด 
          ผู้อำนวยการสำนักเขตพื้นที่การศึกษาในจังหวัด ผู้ว่าราชการจังหวัดหรือจำนวนตัวแทนคน นายแพทย์สาธารณสุขจังหวัด ผู้บังคับการตำรวจภูธรจังหวัด 
          และกรรมการผู้ทรงคุณวุฒิซึ่งผู้ว่าราชการจังหวัดแต่งตั้งจากผู้เชี่ยวชาญที่มีประสบการณ์ด้านการศึกษา จิตวิทยา กฎหมาย และกิจการหอพักเด็กและเยาวชน ด้านละหนึ่งคน เป็นกรรมการ
            - ให้ท้องถิ่นจังหวัดเป็นกรรมการและเลขานุการ และให้ท้องถิ่นจังหวัดแต่งตั้งข้าราชการในสำนักงานส่งเสริมการปกครองท้องถิ่นจังหวัดไม่เกินสองคนเป็นผู้ช่วยเลขานุการ

มาตรา 24: ให้นำบทบัญญัติมาตรา 16 มาตรา 17 มาตรา 18 และมาตรา 19 มาใช้บังคับกับการดำรงตำแหน่ง การพ้นจากตำแหน่ง 
          การแต่งตั้งกรรมการแทน และการปฏิบัติหน้าที่ของกรรมการผู้ทรงคุณวุฒิตามมาตรา 22 และมาตรา 23 โดยอนุโลม 
          เว้นแต่อำนาจของประธานกรรมการตามมาตรา 17 (3) และมาตรา 18 ให้เป็นอำนาจของผู้ว่าราชการกรุงเทพมหานครหรือผู้ว่าราชการจังหวัด แล้วแต่กรณี

มาตรา 25: ให้นำบทบัญญัติมาตรา 20 และมาตรา 21 มาใช้บังคับกับการประชุมและการแต่งตั้งคณะอนุกรรมการของคณะกรรมการส่งเสริมกิจการหอพักกรุงเทพมหานคร และคณะกรรมการส่งเสริมกิจการหอพักจังหวัดด้วย
          

มาตรา 26: คณะกรรมการส่งเสริมกิจการหอพักกรุงเทพมหานครและคณะกรรมการส่งเสริมกิจการหอพักจังหวัด มีอำนาจหน้าที่ ดังต่อไปนี้
          (1) เสนอความเห็นต่อคณะกรรมการในการดำเนินการมาตรา 15 (1) (2) และ (3)
          (2) เสนอความเห็นต่อคณะกรรมการในการออกประกาศกำหนดหลักเกณฑ์เกี่ยวกับหอพักตามพระราชบัญญัตินี้
          (3) ติดตาม ประเมินผล และตรวจสอบประสิทธิภาพในการบังคับใช้และเสนอแนะแนวทางในการปรับปรุงพระราชบัญญัติต่อคณะกรรมการ
          (4) ดำเนินการอื่นใดตามที่คณะกรรมการมอบหมาย

     [หมวด 3: การประกอบกิจการหอพัก]

     [ส่วนที่ 1: หอพักสถานศึกษา]

มาตรา 27: สถานศึกษาใดประสงค์จะประกอบกิจการหอพัก ต้องได้รับใบอนุญาตจากนายทะเบียน
           - การขอรับใบอนุญาตและการออกใบอนุญาต ให้เป็นไปตามหลักเกณฑ์ วิธีการ และเงื่อนไขที่กำหนดในกฎกระทรวง

มาตรา 28: หอพักสถานศึกษาที่ได้รับใบอนุญาตต้องไปตามหลักเกณฑ์ที่กำหนดในกฎกระทรวง ซึ่งอย่างน้อยต้องประกอบด้วย
           (1) ชื่อและประเภทของหอพัก
           (2) สถานที่ตั้ง สิ่งแวดล้อม และสุขลักษณะของหอพัก
           (3) ห้องนอน ห้องน้ำ และห้องส้วม
           (4) สถานที่สำหรับรับประทานอาหารหรือจัดเตรียมผู้ซื้อเบียน และสิ่งอำนวยความสะดวกสำหรับผู้พัก
           (5) ระบบสาธารณูปโภคและการบริการรักษาพยาบาล
                - ในกรณีที่มีกฎหมายว่าด้วยการควบคุมอาคารหรือกฎหมายอื่นใดได้กำหนดหลักเกณฑ์ไว้แล้ว กฎกระทรวงตามวรรคหนึ่งจะไม่กำหนดหลักเกณฑ์ในเรื่องดังกล่าวซ้ำซ้อนอีก
                - ในกรณีที่มีการกำหนดหลักเกณฑ์ตามวรรคหนึ่ง พนักงานเจ้าหน้าที่ต้องมีอำนาจไม่ต่ำกว่าหลักเกณฑ์ในกฎหมายว่าด้วยการควบคุมอาคารหรือกฎหมายอื่นที่เกี่ยวข้อง

มาตรา 29: หอพักสถานศึกษา ให้ได้รับยกเว้นค่าธรรมเนียมการประกอบกิจการหอพักตามพระราชบัญญัตินี้ และอาจได้รับประโยชน์และการสนับสนุนตามมาตรา 15 ด้วย

มาตรา 30: เพื่อประโยชน์ในการด้านการศึกษา การท่องเที่ยว หรือการกีฬา หอพักสถานศึกษาอาจรับบุคคลทั่วไปเข้าพักเป็นการชั่วคราวในระหว่างภาคการศึกษาที่ไม่มีผู้พัก

มาตรา 31: การโอนใบอนุญาตประกอบกิจการหอพักสถานศึกษา ต้องได้รับใบอนุญาตจากนายทะเบียนและต้องโอนให้แก่วิถานศึกษาเดียวกันเท่านั้น
         - ผู้รับโอนใบอนุญาตตามวรรคหนึ่งต้องรับสิทธิและหน้าที่ของผู้ประกอบกิจการหอพักที่มีอยู่ผู้พัก
         - การโอนใบอนุญาตประกอบกิจการหอพักสถานศึกษา ให้เป็นไปตามหลักเกณฑ์ วิธีการ และเงื่อนไขที่กำหนดในกฎกระทรวง

มาตรา 32: ใบอนุญาตประกอบกิจการหอพักสถานศึกษาสิ้นสุดลงเมื่อผู้ประกอบกิจการหอพักเลิกกิจการในสถานศึกษาหรือเลิกกิจการ
        - ในกรณีที่ผู้ประกอบกิจการหอพักตามวรรคหนึ่งประสงค์จะประกอบกิจการหอพักต่อไป ให้ดำเนินการยื่นคำขอรับใบอนุญาตตามหอพักเอกชน 
          และเมื่อได้รับใบอนุญาตแล้วให้ถือว่าใบอนุญาตประกอบกิจการหอพักสถานศึกษาเป็นอันสิ้นผลทางกฎหมายทะเบียน
        - ในกรณีที่ผู้ประกอบกิจการหอพักตามวรรคหนึ่งไม่ประสงค์จะประกอบกิจการหอพักต่อไป หรือได้รับคําสั่งไม่ออกใบอนุญำตจำกนำยทะเบียน 
          ให้ผู้ชําระบัญชีของสถานศึกษาคืนเงินค่าเช่าล่วงหน้ำหรือเงินประกันให้แก่ผู้พักตามจํานวนที่เหลืออยู่หลังจากกหักเป็นค่าเช่าหรือค่ำเสียหายแล้วแต่กรณี

       [ส่วนที่ 2: หอพักเอกชน]

มาตรา 33: ผู้ประสงค์จะประกอบกิจการหอพักต้องได้รับใบอนุญาตจากนายทะเบียน
           - การขอรับใบอนุญาตและการออกใบอนุญาต ให้เป็นไปตามหลักเกณฑ์ วิธีการ และเงื่อนไขที่กำหนดในกฎกระทรวง

มาตรา 34: หอพักเอกชนที่ได้รับใบอนุญาตต้องไปตามหลักเกณฑ์ที่กำหนดในกฎกระทรวง ซึ่งอย่างน้อยต้องประกอบด้วย
          (1) ชื่อและประเภทของหอพัก
          (2) จำนวนผู้พัก
          (3) สถานที่ตั้ง สิ่งแวดล้อม และสุขลักษณะของหอพัก


มาตรา 35: ผู้รับใบอนุญาตประกอบกิจการหอพักเอกชน ต้องมีคุณสมบัติและไม่มีลักษณะต้องห้าม ดังต่อไปนี้
          (1) คุณสมบัติ:
               - มีสัญชาติไทยหรือมีถิ่นที่อยู่ในราชอาณาจักร
               - มีอายุไม่ต่ำกว่า 20 ปีบริบูรณ์
          (2) ลักษณะต้องห้าม:
               (ก) ไม่เป็นคนไร้ความสามารถหรือคนเสมือนไร้ความสามารถ
               (ข) เป็นผู้มีความประพฤติเสื่อมเสียหรือบกพร่องในศีลธรรมอันดี
               (ค) เคยได้รับโทษจำคุกโดยคำพิพากษาถึงที่สุดให้จำคุก เว้นแต่เป็นโทษสำหรับความผิดที่ได้กระทำโดยประมาทหรือความผิดลหุโทษ
               (ง) เคยต้องคำพิพากษาหรือคำสั่งของศาลให้ทรัพย์สินตกเป็นของแผ่นดินเพราะร่ำรวยผิดปกติ หรือมีทรัพย์สินเพิ่มขึ้นผิดปกติ 
                   หรือไม่เคยต้องคำพิพากษาอันถึงที่สุดว่ากระทำความผิดตามประมวลกฎหมายอาญาเกี่ยวกับความผิดเกี่ยวกับเพศ ความผิดเกี่ยวกับชีวิตและร่างกาย 
                   ความผิดฐานทอดทิ้งเด็กหรือผู้สูงอายุ ความผิดฐานฉ้อโกง ความผิดตามกฎหมายว่าด้วยการป้องกันและปราบปรามการค้ามนุษย์ 
                   ความผิดตามกฎหมายว่าด้วยการป้องกันและปราบปรามการค้าประเวณี หรือความผิดตามกฎหมายเกี่ยวกับยาเสพติด
               (จ) เคยถูกเพิกถอนใบอนุญาตประกอบกิจการหอพักในระยะเวลาไม่เกิน 5 ปี

                   ในกรณีที่ผู้รับใบอนุญาตเป็นห้างหุ้นส่วนหรือนิติบุคคล ผู้จัดการ ผู้ประกอบกิจการหอพักนั้นต้องมีคุณสมบัติและไม่มีลักษณะต้องห้ามตามวรรคหนึ่ง 
                   และต้องไม่เป็นหุ้นส่วน ผู้จัดการ หรือผู้มีอำนาจหรือบุคคลที่เคยถูกเพิกถอนใบอนุญาตตามวรรคหนึ่งด้วย

มาตรา 36: หอพักเอกชน ให้รับผู้พักได้เฉพาะผู้ซึ่งอยู่ในระหว่างการศึกษาในระดับอุดมศึกษาที่ไม่สูงกว่าปริญญาตรี 
          เว้นแต่หอพักนักเรียนที่ได้รับใบอนุญาตให้รับผู้พักซึ่งอยู่ในระหว่างการศึกษาขั้นพื้นฐานได้
          - การขึ้นทะเบียนหอพักเอกชนไว้กับสถานศึกษา ให้เป็นไปตามหลักเกณฑ์ วิธีการ และเงื่อนไขที่คณะกรรมการกำหนดประกาศในราชกิจจานุเบกษา

มาตรา 37: ใบอนุญาตประกอบกิจการหอพักเอกชน ให้มีอายุสามปีนับแต่วันออกใบอนุญาต
          - การขอต่ออายุใบอนุญาต ให้ยื่นคำขอก่อนนายทะเบียนในวันหมดอายุใบอนุญาต เมื่อได้ยื่นคำขอแล้วให้ถือว่าผู้คำขออยู่ในฐานะผู้ขอใบอนุญาตจนกว่าจะมีคำสั่งไม่ให้ต่ออายุใบอนุญาต
          - การขอต่ออายุใบอนุญาตและการออกใบอนุญาต ให้เป็นไปตามหลักเกณฑ์ วิธีการ และเงื่อนไขที่กำหนดในกฎกระทรวง

มาตรา 38: การโอนใบอนุญาตประกอบกิจการหอพักเอกชน ต้องได้รับใบอนุญาตจากนายทะเบียน
          - การโอนใบอนุญาตตามวรรคหนึ่งต้องโอนให้แก่บุคคลที่มีคุณสมบัติและไม่มีลักษณะต้องห้ามตามมาตรา 35 หรือสถานศึกษา
          - ในกรณีที่โอนใบอนุญาตให้แก่สถานศึกษา ให้ นายทะเบียนเปลี่ยนใบอนุญาตของหอพักดังกล่าวเป็นใบอนุญาตประกอบกิจการหอพักสถานศึกษา
          - ให้นำบทบัญญัติมาตรา 31 วรรคสอง มาใช้บังคับกับการโอนใบอนุญาตตามวรรคหนึ่งโดยอนุโลม
          - การโอนใบอนุญาตและการออกใบอนุญาต ให้เป็นไปตามหลักเกณฑ์ วิธีการ และเงื่อนไขที่กำหนดในกฎกระทรวง

มาตรา 39: ในกรณีที่ผู้ประกอบกิจการหอพักเอกชนมีความตาย และทายาทมีความประสงค์จะประกอบกิจการหอพักต่อไป 
          ให้ทายาทแจ้งต่อนายทะเบียนภายใน 120 วันนับแต่วันตายหรือในกรณีที่ทายาทหย่อนความสามารถให้นายทะเบียนแต่งตั้งผู้แทนโดยชอบธรรมดูแลแทนจนกว่าจะบรรลุนิติภาวะ 
          และให้ผู้ประกอบกิจการหอพักแจ้งต่อนายทะเบียนเพื่อเปลี่ยนแปลงแก้ไขในใบอนุญาต และให้ผู้แจ้งยื่นคำขอต่อทะเบียนภายใน 30 วันนับแต่วันได้รับแจ้งจากนายทะเบียน 
          ทั้งนี้ ผู้ประกอบกิจการหอพักอาจจะมีการโอนย้ายไปยังใบอนุญาตประกอบกิจการหอพักในระเบียบผู้ประกอบกิจการหอพักคืนเงินค่าเช่าล่วงหน้าหรือเงินประกันให้แก่ผู้พักจำนวนที่เหลืออยู่หลังจากหักค่าเช่าค่าเสียหาย แล้วแด่กรณี

มาตรา 40: ในกรณีที่ผู้ประกอบกิจการหอพักเอกชนเป็นห้างหุ้นส่วนนิติบุคคล ให้หุ้นส่วนผู้จัดการหรือพนักงานผู้มีอำนาจกระทำการแทนนิติบุคคลนั้นมีความตายหรือพ้นจากสภาพความเป็นนิติบุคคล 
          ให้ผู้มีอำนาจของนิติบุคคลนั้นคืนเงินค่าเช่าล่วงหน้าหรือเงินประกันให้แก่ผู้พักจำนวนที่เหลืออยู่หลังจากหักค่าเช่าค่าเสียหาย แล้วแด่กรณี

มาตรา 41: พนักงานเจ้าหน้าที่ผู้ได้รับการประเมินคุณงามความดีและวิชาการ ให้รับสิทธิประโยชน์และการสนับสนุน ดังต่อไปนี้
           (1) สิทธิที่จะได้รับลดหย่อนหรือยกเว้นภาษีเงินได้เป็นกรณีพิเศษจากการประกอบกิจการหอพักโดยตราเป็นพระราชกฤษฎีกาตามประมวลรัษฎากร
           (2) ลดหย่อนหรือยกเว้นภาษีโรงเรือนและที่ดิน ภาษีป้าย หรือภาษีเงินในทำนองเดียวกัน ทั้งนี้ ตามกฎหมายว่าด้วยการนั้นกําหนด
           (3) การสนับสนุนด้านการเงินหรือวัสดุอุปกรณ์
           (4) การสนับสนุนด้านอื่น ๆ ตามที่กำหนดในกฎกระทรวง
               - การประกาศเกียรติคุณและการได้รับการสนับสนุนตาม (3) และ (4) ให้เป็นไปตามหลักเกณฑ์ วิธีการ และเงื่อนไขที่กำหนดในกฎกระทรวง

    [ส่วนที่ 3: หลักเกณฑ์ในการประกอบกิจการหอพักสถานศึกษาและหอพักเอกชน]

มาตรา 42: ผู้ประกอบกิจการหอพัก ต้องแสดงใบอนุญาตประกอบกิจการหอพักไว้ในที่เปิดเผยและเห็นได้ง่าย ณ หอพักนั้น

มาตรา 43: ในกรณีที่ใบอนุญาตสูญหายหรือถูกทำลายในสาระสำคัญ ให้ผู้ประกอบกิจการหอพักแจ้งต่อนายทะเบียน 
          และยื่นคำขอรับใบแทนใบอนุญาตภายใน 15 วันนับแต่วันที่ได้ทราบว่าใบอนุญาตสูญหายหรือถูกทำลาย
           - การขอและการออกใบแทนใบอนุญาต ให้เป็นไปตามหลักเกณฑ์ วิธีการ และเงื่อนไขที่กำหนดในกฎกระทรวง

มาตรา 44: ผู้ประกอบกิจการหอพักใดประสงค์จะดัดแปลงหอพักในลักษณะของการดัดแปลงอาคารตามกฎหมายว่าด้วยการควบคุมอาคาร ต้องได้รับอนุญาตจากนายทะเบียน
           - การขออนุญาตและการอนุญาต ให้เป็นไปตามหลักเกณฑ์ วิธีการ และเงื่อนไขที่กำหนดในกฎกระทรวง

มาตรา 45: ผู้ประกอบกิจการหอพักใดประสงค์จะเปลี่ยนชื่อหรือประเภทของหอพักต้องได้รับอนุญาตจากนายทะเบียน
           - การขออนุญาตและการอนุญาต ให้เป็นไปตามหลักเกณฑ์ วิธีการ และเงื่อนไขที่กำหนดในกฎกระทรวง

มาตรา 46: ผู้ประกอบกิจการหอพักใดประสงค์จะเลิกประกอบกิจการหอพัก ให้ยื่นคำขออนุญาตต่อนายทะเบียนล่วงหน้าไม่น้อยกว่า 90 วันก่อนวันเลิกประกอบกิจการ
           - นายทะเบียนจะอนุญาตให้เลิกประกอบกิจการหอพักได้เมื่อผู้ประกอบกิจการหอพักแสดงหลักฐานว่าได้ดำเนินการแจ้งให้ผู้พักทราบล่วงหน้า 
             ไม่น้อยกว่า 90 วัน และคืนเงินค่าเช่าล่วงหน้าหรือเงินประกัน แล้วแต่กรณี ให้แก่ผู้พักเรียบร้อยแล้ว

มาตรา 47: ให้ใบอนุญาตประกอบกิจการหอพักสิ้นผลนับแต่วันที่นายทะเบียนมีคำสั่งอนุญาตให้เลิกประกอบกิจการหอพัก

      [หมวด 4: การจัดการหอพัก]

[ส่วนที่ 1: ผู้จัดการหอพัก]

มาตรา 48: ผู้ประกอบกิจการหอพัก ต้องจัดให้มีผู้จัดการหอพักเป็นผู้มีหน้าที่ควบคุมดูแลหอพัก
           - ในกรณีที่ผู้จัดการหอพักไม่อยู่หรือไม่สามารถปฏิบัติหน้าที่ได้ ให้ผู้ประกอบกิจการหอพักแต่งตั้งผู้อื่นปฏิบัติหน้าที่แทนตามหลักเกณฑ์ที่คณะกรรมการกำหนด
           - ให้ผู้ประกอบกิจการหอพักแจ้งต่อนายทะเบียนทราบภายใน 15 วันนับแต่วันที่มีการแต่งตั้งผู้ปฏิบัติหน้าที่แทน
           - ผู้จัดการหอพักหรือผู้ปฏิบัติหน้าที่แทนของหอพักหญิงต้องเป็นหญิง

มาตรา 49: ผู้จัดการหอพักสถานศึกษา ต้องได้รับแต่งตั้งจากสถานศึกษาโดยผู้ประกอบกิจการหอพักต้องแจ้งต่อนายทะเบียนทราบภายใน 15 วันนับแต่วันที่ได้รับใบอนุญาตประกอบกิจการหอพัก
          - ผู้ซึ่งจะได้รับการแต่งตั้งเป็นผู้จัดการหอพักตามวรรคหนึ่ง ต้องมีคุณสมบัติและไม่มีลักษณะต้องห้ามตามมาตรา 35
          - ในกรณีที่ผู้ประกอบกิจการหอพักเปลี่ยนผู้จัดการหอพัก ต้องแจ้งต่อนายทะเบียนทราบภายใน 15 วันนับแต่วันที่มีการแต่งตั้งผู้จัดการหอพักใหม่

มาตรา 50: ผู้ใดประสงค์จะเป็นผู้จัดการหอพักของหอพักเอกชน ต้องได้รับใบอนุญาตจากนายทะเบียน
          - ในกรณีที่ผู้ประกอบกิจการหอพักเป็นบุคคลธรรมดาและมีคุณสมบัติและไม่มีลักษณะต้องห้ามตามมาตรา 51 ผู้ประกอบกิจการหอพัก
            และผู้จัดการหอพักจะเป็นบุคคลเดียวกันก็ได้

             ใบอนุญาตตามวรรคหนึ่งให้ใช้ได้สำหรับหอพักที่ระบุในใบอนุญาตนั้นการขอรับใบอนุญาตและการออกใบอนุญาต 
             ให้เป็นไปตามหลักเกณฑ์ วิธีการ และเงื่อนไขที่กำหนดในกฎกระทรวง

มาตรา 51: ผู้ขอรับใบอนุญาตผู้จัดการหอพักตามมาตรา 50 ต้องมีคุณสมบัติและไม่มีลักษณะต้องห้าม ดังต่อไปนี้
           (1) คุณสมบัติ:
                 (ก) มีสัญชาติไทย
                 (ข) มีอายุไม่ต่ำกว่า 20 ปีบริบูรณ์
           (2) ลักษณะต้องห้าม:
                 (ก) เป็นคนไร้ความสามารถหรือคนเสมือนไร้ความสามารถ
                 (ข) เป็นผู้มีความประพฤติเสื่อมเสียหรือบกพร่องในศีลธรรมอันดี
                 (ค) เคยได้รับโทษจำคุกโดยคำพิพากษาถึงที่สุดให้จำคุก เว้นแต่เป็นโทษสำหรับความผิดที่ได้กระทำโดยประมาทหรือความผิดลหุโทษ
                 (ง) เคยต้องคำพิพากษาถึงที่สุดว่าเป็นผู้กระทำผิดในความผิดเกี่ยวกับเพศตามประมวลกฎหมายอาญา ความผิดตามกฎหมายว่าด้วยการคุ้มครองเด็ก 
                     ความผิดตามกฎหมายว่าด้วยการป้องกันและปราบปรามการค้าประเวณี ความผิดตามกฎหมายว่าด้วยการป้องกันและปราบปรามการค้ามนุษย์ 
                     ความผิดตามกฎหมายว่าด้วยการพนัน หรือความผิดตามกฎหมายเกี่ยวกับยาเสพติด
                 (จ) เป็นโรคตามที่คณะกรรมการกำหนดโดยประกาศในราชกิจจานุเบกษา
                 (ฉ) เคยถูกเพิกถอนใบอนุญาตผู้จัดการหอพักในระยะเวลา 5 ปีก่อนวันขอรับใบอนุญาต

มาตรา 52: ใบอนุญาตผู้จัดการหอพักตามมาตรา 50 มีอายุ 2 ปีนับแต่วันที่ออกใบอนุญาต
           - การขอต่ออายุใบอนุญาต ให้ยื่นคำขอก่อนวันที่ใบอนุญาตสิ้นอายุ เมื่อได้ยื่นคำขอแล้วให้ถือว่าผู้ยื่นคำขออยู่ในฐานะผู้รับใบอนุญาตจนกว่าจะมีคำสั่งถึงที่สุดไม่อันอนุญาตให้ต่ออายุใบอนุญาต
           - การขอต่ออายุใบอนุญาตและการอนุญาต ให้เป็นไปตามหลักเกณฑ์ วิธีการ และเงื่อนไขที่กำหนดในกฎกระทรวง

มาตรา 53: ผู้จัดการหอพักเอกชน ต้องแสดงใบอนุญาตผู้จัดการหอพักไว้ในที่เปิดเผยและเห็นได้ง่าย ณ หอพักนั้น

มาตรา 54: ในกรณีที่ใบอนุญาตสูญหายหรือถูกทำลายในสาระสำคัญ ให้ผู้จัดการหอพักแจ้งต่อนายทะเบียน และยื่นคำขอรับใบแทนใบอนุญาตภายใน 15 วันนับแต่วันที่ได้ทราบว่าใบอนุญาตสูญหายหรือถูกทำลาย
          - การขอและการออกใบแทนใบอนุญาต ให้เป็นไปตามหลักเกณฑ์ วิธีการ และเงื่อนไขที่กำหนดในกฎกระทรวง

มาตรา 55: ให้นายทะเบียนมีอำนาจเพิกถอนใบอนุญาตผู้จัดการหอพักหรือแจ้งให้ผู้ประกอบกิจการหอพักสถานศึกษาเปลี่ยนผู้จัดการหอพักใหม่ เมื่อปรากฏต่อนายทะเบียนว่า ผู้จัดการหอพักผู้ใด
          (1) ขาดคุณสมบัติหรือมีลักษณะต้องห้ามตามมาตรา 51
          (2) ฝ่าฝืนหรือไม่ปฏิบัติตามมาตรา 6 หรือมาตรา 63 หรือมาตรา 64 ในกรณีที่ผู้จัดการหอพักมีพฤติการณ์ตาม (2) ให้นายทะเบียนมีหนังสือเตือนให้แก้ไขหรือปฏิบัติให้ถูกต้องภายในระยะเวลาที่กำหนด 
                หากผู้จัดการหอพักไม่ปฏิบัติตามหนังสือเตือนดังกล่าว ให้นายทะเบียนมีคำสั่งเพิกถอนใบอนุญาตหรือแจ้งให้ผู้ประกอบกิจการหอพักสถานศึกษาเปลี่ยนผู้จัดการหอพักใหม่

มาตรา 56: ในกรณีที่ผู้จัดการหอพักถูกเพิกถอนใบอนุญาตหรือพ้นจากหน้าที่ ให้ผู้ประกอบกิจการหอพักแต่งตั้งบุคคลอื่นเป็นผู้จัดการหอพักแทน 
          และแจ้งต่อนายทะเบียนทราบ ทั้งนี้ ภายใน 30 วันนับแต่วันที่ผู้จัดการหอพักถูกเพิกถอนใบอนุญาตหรือพ้นจากหน้าที่
          - ในกรณีที่ไม่สามารถแต่งตั้งผู้จัดการหอพักได้ภายในกำหนดเวลาตามวรรคหนึ่ง ให้ผู้ประกอบกิจการหอพักแจ้งต่อนายทะเบียนทราบ 
            ในการนี้ นายทะเบียนอาจขยายระยะเวลาออกไปได้อีกไม่เกิน 15 วัน
          - ในระหว่างที่ยังไม่มีการแต่งตั้งผู้จัดการหอพักตามวรรคหนึ่งและวรรคสอง ให้ผู้ประกอบกิจการหอพักหรือบุคคลตามมาตรา 48 วรรคสอง 
            ทำหน้าที่ผู้จัดการหอพักแทนได้และให้นำบทบัญญัติมาตรา 48 วรรคสาม มาใช้บังคับโดยอนุโลม

   [ส่วนที่ 2: หน้าที่ของผู้ประกอบกิจการหอพักและผู้จัดการหอพัก]

มาตรา 57: ผู้ประกอบกิจการหอพัก ต้องจัดให้มีการประกันภัยเพื่อคุ้มครองชีวิต ร่างกาย และทรัพย์สินของผู้พักตามหลักเกณฑ์ที่คณะกรรมการกำหนดโดยประกาศในราชกิจจานุเบกษา

มาตรา 58: ผู้ประกอบกิจการหอพักสถานศึกษาที่รับผู้พักซึ่งอยู่ในระหว่างการศึกษาขั้นพื้นฐานต้องจัดให้อาหารที่ถูกอนามัยและเพียงพอสำหรับผู้พักอย่างน้อยวันละสองมื้อ

มาตรา 59: ผู้ประกอบกิจการหอพัก ต้องจัดให้มีระเบียบประจำหอพักปิดประกาศไว้โดยเปิดเผยและเห็นได้ง่ายภายในหอพัก
           - ระเบียบประจำหอพักตามวรรคหนึ่ง ให้เป็นไปตามหลักเกณฑ์ที่คณะกรรมการกำหนดอย่างน้อยต้องมีรายละเอียด ดังต่อไปนี้
           (1) การรับผู้พัก
           (2) อัตราค่าหอพัก เงินค่าเช่าล่วงหน้า เงินประกัน และค่าบริการอื่น ๆ ที่เรียกเก็บจากผู้พัก
           (3) เวลาเข้าออกหอพัก
           (4) หลักเกณฑ์การเยี่ยมผู้พัก
           (5) การไปพักที่อื่นเป็นการชั่วคราว
           (6) การปฏิบัติตนในการอยู่ร่วมกันของผู้พัก
           (7) ชื่อผู้ประกอบกิจการหอพักและผู้จัดการหอพัก
           (8) เวลาทำการของหอพัก
               ระเบียบประจำหอพักและการแก้ไขเพิ่มเติมระเบียบประจำหอพัก เมื่อได้รับความเห็นชอบจากนายทะเบียนแล้วจึงจะใช้บังคับได้

               
มาตรา 60: ผู้ประกอบกิจการหอพัก ต้องจัดให้มีป้ายชื่อเป็นอักษรไทย ซึ่งมีคำว่า "หอพัก" นำหน้า 
          และตามด้วยประเภทของหอพัก โดยป้ายดังกล่าวต้องมีขนาดที่เหมาะสมและติดไว้ ณ หอพักในที่เปิดเผยและเห็นได้ง่ายจากภายนอกหอพัก
           - วัตถุที่ใช้ทำป้าย ลักษณะ ขนาดของป้าย และขนาดของตัวอักษร ให้เป็นไปตามหลักเกณฑ์ที่คณะกรรมการกำหนดโดยประกาศในราชกิจจานุเบกษา

มาตรา 61: ผู้ประกอบกิจการหอพัก ต้องจัดให้มีการตรวจสอบประวัติคนที่จะรับเข้าทำงานในหอพักว่าไม่มีประวัติอาชญากรรมและไม่เป็นโรคติดต่อหรือน่ารังเกียจตามที่คณะกรรมการกำหนดโดยประกาศในราชกิจจานุเบกษา
           - คนดูแลหอพักของหอพักหญิงต้องเป็นหญิง

มาตรา 62: ผู้ประกอบกิจการหอพักและผู้จัดการหอพักมีหน้าที่และความรับผิดชอบร่วมกัน ดังต่อไปนี้
           (1) ดูแลรักษาสภาพของหอพักให้มีความมั่นคงแข็งแรงและมีระบบการป้องกันอัคคีภัยให้เป็นไปตามกฎหมายว่าด้วยการควบคุมอาคาร
           (2) ดูแลรักษาความสะอาดด้านสุขลักษณะและอนามัยของหอพักให้เป็นไปตามกฎหมายว่าด้วยการสาธารณสุข
           (3) จัดให้มียาและเวชภัณฑ์ที่จำเป็นไว้ในหอพักเพื่อให้ความช่วยเหลือเบื้องต้นแก่ผู้พักที่เจ็บป่วย
           (4) จัดให้มีแผนผังแสดงทางหนีไฟในแต่ละชั้นของหอพักและห้องพักทุกห้องและป้ายทางออกฉุกเฉินไว้ในแต่ละชั้นของหอพัก
           (5) ดูแลและอำนวยความสะดวกให้กับผู้พักในกรณีเกิดอัคคีภัย อุทกภัย หรือเกิดอันตรายใด ๆ ขึ้นและอาจมีผลกระทบต่อผู้พัก

มาตรา 63: ผู้จัดการหอพัก ต้องจัดทำทะเบียนผู้พักแต่ละรายและส่งให้นายทะเบียนทราบภายใน 7 วันนับแต่วันที่มีการทำสัญญาเช่าหรือสัญญาเช่าสิ้นสุดลง
          - ทะเบียนผู้พักตามวรรคหนึ่งอย่างน้อยต้องมีรายการ ดังต่อไปนี้
           (1) ชื่อ อายุ และเพศของผู้พัก
           (2) เลขประจำตัวประชาชนหรือเลขประจำตัวคนต่างด้าวของผู้พัก
           (3) ชื่อสถานศึกษาของผู้พัก
           (4) ชื่อและที่อยู่ของบิดามารดาหรือผู้ปกครองของผู้พัก
           (5) วันที่เข้าอยู่นหอพัก
           (6) ลายมือชื่อผู้พัก
                การจัดทำและจัดส่งทะเบียนผู้พักให้นายทะเบียนตามวรรคหนึ่ง ให้เป็นไปตามหลักเกณฑ์ที่คณะกรรมการกำหนดโดยประกาศในราชกิจจานุเบกษา
                ผู้ประกอบกิจการหอพัก ต้องเก็บรักษาทะเบียนผู้พักไว้เป็นเวลาอย่างน้อย 2 ปีนับแต่วันที่สัญญาเช่าสิ้นสุดลง โดยจะเก็บไว้ในรูปของข้อมูลอิเล็กทรอนิกส์หรือรูปแบบใดก็ได้ และต้องให้ให้อยู่ในสภาพที่ตรวจสอบได้

มาตรา 64: ผู้จัดการหอพักมีหน้าที่ ดังต่อไปนี้
           (1) ดูแลไม่ให้บุคคลอื่นที่ไม่ใช่ผู้พักเข้าไปในห้องพัก เว้นแต่ได้รับอนุญาตจากผู้จัดการหอพัก
           (2) ดูแลไม่ให้มีการเล่นการพนัน เสพสุรา หรือยาเสพติดในหอพัก
           (3) ดูแลไม่ให้มีการกระทำอันควรเชื่อว่ามีการสมกันหรือร่วมกันกระทำารอันมิชอบด้วยกฎหมาย
           (4) ดูแลไม่ให้ผู้พักก่อความรำคาญแก่ผู้พักผู้อื่น or ผู้ที่อยู่อาศัยในบริเวณใกล้เคียงหอพัก
           (5) ให้ความช่วยเหลือและแจ้งให้บิดามารดาหรือผู้ปกครองของผู้พักทราบโดยทันทีในกรณีที่ปรากฏว่าผู้พักได้รับอันตรายเพราะเจ็บป่วยหรือเหตุอื่นใด
           (6) แจ้งให้บิดามารดาหรือผู้ปกครองของผู้พักทราบในกรณีที่ผู้พักไปพักที่อื่นโดยไม่แจ้งให้ทราบ
           (7) แจ้งให้พนักงานเจ้าหน้าที่ทราบในกรณีที่มีพฤติกรรมตาม (2) หรือ (3)

        [หมวด 5: นายทะเบียนและพนักงานเจ้าหน้าที่]

มาตรา 65: นายทะเบียนมีอำนาจเพิกถอนใบอนุญาตประกอบกิจการหอพักได้ เมื่อปรากฏต่อนายทะเบียนว่า
           (1) หอพักไม่เป็นไปตามหลักเกณฑ์ที่กำหนดไว้ในกฎกระทรวงที่ออกตามมาตรา 28 หรือมาตรา 34
           (2) ผู้ประกอบกิจการหอพักขาดคุณสมบัติหรือมีลักษณะต้องห้ามตามมาตรา 35

มาตรา 66: ก่อนมีคำสั่งเพิกถอนใบอนุญาตประกอบกิจการหอพักตามมาตรา 65 ให้นายทะเบียนดำเนินการ ดังต่อไปนี้
          (1) ในกรณีที่หอพักไม่เป็นไปตามหลักเกณฑ์ที่กำหนดไว้ในกฎกระทรวงที่ออกตามมาตรา 28 
              หรือมาตรา 34 ให้มีหนังสือแจ้งให้ผู้ประกอบกิจการหอพักดำเนินการแก้ไขภายในระยะเวลาที่กำหนด
          (2) ในกรณีที่ผู้ประกอบกิจการหอพักเป็นห้างหุ้นส่วนหรือนิติบุคคล และหุ้นส่วน ผู้จัดการ ผู้จัดการหรือผู้แทนของนิติบุคคล
              ขาดคุณสมบัติหรือมีลักษณะต้องห้ามตามมาตรา 35 ให้มีหนังสือแจ้งให้ผู้ประกอบกิจการหอพักแต่งตั้งบุคคลอื่นมาดำรงตำแหน่งแทนภายใน 30 วันนับแต่วันที่ได้รับแจ้ง
          (3) ในกรณีที่ผู้ประกอบกิจการหอพักเป็นบุคคลธรรมดาและขาดคุณสมบัติหรือมีลักษณะต้องห้ามตามมาตรา 35 ให้มีหนังสือแจ้งให้ผู้ประกอบกิจการหอพักโอนใบอนุญาตประกอบกิจการหอพักให้แก่บุคคล 
              ซึ่งมีคุณสมบัติและไม่มีลักษณะต้องห้ามตามมาตรา 35 หรือสถานศึกษาภายในระยะเวลาที่กำหนด แต่ทั้งนี้ต้องไม่เกิน 60 วันนับแต่วันที่ได้รับแจ้ง


มาตรา 67: ในกรณีที่ผู้ประกอบกิจการหอพักฝ่าฝืนหรือไม่ปฏิบัติตามมาตรา 66 (1) หรือ (2) ให้นายทะเบียนดำเนินการ ดังต่อไปนี้
          (1) สำหรับหอพักสถานศึกษา ให้มีหนังสือแจ้งให้ผู้ประกอบกิจการหอพักโอนใบอนุญาตประกอบกิจการหอพักให้แก่สถานศึกษาอื่นภายในระยะเวลาที่กำหนด 
              แต่ทั้งนี้ต้องไม่เกินหกสิบวันนับแต่วันที่ได้รับแจ้ง
          (2) สำหรับหอพักเอกชน ให้มีหนังสือแจ้งให้ผู้ประกอบกิจการหอพักดำเนินการขึ้นทะเบียนหอพักไว้กับสถานศึกษา 
              หรือโอนใบอนุญาตประกอบกิจการหอพักให้แก่บุคคลซึ่งมีคุณสมบัติและไม่มีลักษณะต้องห้ามตามมาตรา 35 หรือสถานศึกษาภายในระยะเวลาที่กำหนด 
              แต่ทั้งนี้ต้องไม่เกินหกสิบวันนับแต่วันที่ได้รับแจ้ง แล้วแต่กรณี

มาตรา 68: ในกรณีที่ผู้ประกอบกิจการหอพักไม่สามารถปฏิบัติตามคำสั่งของนายทะเบียนได้ภายในระยะเวลาที่กำหนด
          ตามมาตรา 66 หรือมาตรา 67 นายทะเบียนอาจขยายระยะเวลาได้ตามความเหมาะสม แต่ทั้งนี้ต้องไม่เกินสามสิบวันนับแต่วันที่ครบกำหนดดังกล่าว

มาตรา 69: ในกรณีที่ผู้ประกอบกิจการหอพักไม่สามารถโอนใบอนุญาตประกอบกิจการหอพักหรือนำหอพักไปขึ้นทะเบียนไว้กับสถานศึกษาได้
          ภายในระยะเวลาที่กำหนดตามมาตรา 66 (3) มาตรา 67 หรือภายในระยะเวลาที่นายทะเบียนสั่งขยายตามมาตรา 68 ให้นายทะเบียนมีหนังสือแจ้งให้ผู้ประกอบกิจการหอพักคืนเงินค่าเช่าล่วงหน้าหรือเงินประกันให้แก่ผู้พักจำนวนที่เหลืออยู่หลังจากหักเป็นค่าเช่าหรือค่าเสียหาย แล้วแต่กรณี ภายในระยะเวลาที่กำหนด ก่อนมีคำสั่งเพิกถอนใบอนุญาต

มาตรา 70: ในการปฏิบัติหน้าที่ตามพระราชบัญญัตินี้ ให้นายทะเบียนและพนักงานเจ้าหน้าที่มีอำนาจหน้าที่ ดังต่อไปนี้
          (1) เข้าไปในหอพักเพื่อตรวจสอบการปฏิบัติการตามพระราชบัญญัตินี้
          (2) เข้าไปในสถานที่ใด ๆ เพื่อตรวจสอบในกรณีที่มีเหตุอันควรสงสัยว่ามีการประกอบกิจการหอพักโดยไม่ได้รับใบอนุญาตตามพระราชบัญญัตินี้
          (3) เรียกผู้ประกอบกิจการหอพัก ผู้จัดการหอพัก หรือบุคคลที่ทำงานในหอพักมาให้ถ้อยคำหรือชี้แจงหรือส่งเอกสารหรือหลักฐานที่เกี่ยวข้องมาเพื่อประกอบการพิจารณาเกี่ยวกับการจัดการหอพัก
               ในการปฏิบัติหน้าที่ตาม (1) และ (2) ต้องเข้าไปในระหว่างเวลาพระอาทิตย์ขึ้นถึงพระอาทิตย์ตกและต้องไม่กระทำการอันเป็นการรบกวนหรือก่อให้เกิดความรำคาญแก่ผู้พักหรือผู้ซึ่งอาศัยอยู่ในสถานที่นั้น
               ในการปฏิบัติหน้าที่ตาม (2) นายทะเบียนและพนักงานเจ้าหน้าที่อาจขอให้เจ้าหน้าที่ตำรวจในท้องที่ที่สถานที่นั้นตั้งอยู่ร่วมตรวจสอบได้

มาตรา 71: ในการปฏิบัติหน้าที่ของนายทะเบียนและพนักงานเจ้าหน้าที่ตามมาตรา 70 ให้บุคคลซึ่งเกี่ยวข้องอำนวยความสะดวกตามสมควร

มาตรา 72: ในการปฏิบัติหน้าที่ตามมาตรา 70 ให้นายทะเบียนและพนักงานเจ้าหน้าที่แสดงบัตรประจำตัวต่อบุคคลที่เกี่ยวข้องทุกครั้ง
          - บัตรประจำตัวนายทะเบียนและพนักงานเจ้าหน้าที่ ให้เป็นไปตามแบบที่รัฐมนตรีประกาศกำหนด

มาตรา 73: ในการปฏิบัติหน้าที่ตามพระราชบัญญัตินี้ ให้นายทะเบียนและพนักงานเจ้าหน้าที่เป็นเจ้าพนักงานตามประมวลกฎหมายอาญา

     [หมวด 6: การอุทธรณ์]

มาตรา 74: ในกรณีที่ผู้ได้รับคำสั่งของนายทะเบียนตามมาตรา 27 มาตรา 33 มาตรา 37 มาตรา 44 มาตรา 45 มาตรา 46 มาตรา 47 มาตรา 50 มาตรา 52 มาตรา 55 มาตรา 56 มาตรา 65 มาตรา 66 และมาตรา 69 ไม่เห็นด้วยกับคำสั่งดังกล่าวให้มีสิทธิอุทธรณ์ต่อบุคคลดังต่อไปนี้ ภายในสามสิบวันนับแต่วันที่ได้รับแจ้งคำสั่ง
           (1) ในเขตกรุงเทพมหานคร ให้อุทธรณ์ต่อรัฐมนตรีว่าการกระทรวงมหาดไทย
           (2) ในเขตจังหวัดอื่น ให้อุทธรณ์ต่อผู้ว่าราชการจังหวัดที่หอพักตั้งอยู่

มาตรา 75: คำวินิจฉัยอุทธรณ์ของรัฐมนตรีว่าการกระทรวงการมหาดไทยหรือผู้ว่าราชการจังหวัดให้เป็นที่สุด

      [หมวด 7: บทกำหนดโทษ]
 
มาตรา 76: ผู้ใดใช้คำว่า “หอพัก” ในสถานที่ของตนโดยไม่ได้รับใบอนุญาตประกอบกิจการหอพัก ต้องระวางโทษปรับไม่เกินห้าหมื่นบาท และปรับอีกวันละไม่เกินห้าพันบาทตลอดเวลาที่ยังฝ่าฝืนอยู่

มาตรา 77: ผู้ประกอบกิจการหอพักผู้ใดรับผู้พักไม่เป็นไปตามประเภทของหอพักตามมาตรา 8 ต้องระวางโทษจำคุกไม่เกินหกเดือน หรือปรับไม่เกินห้าหมื่นบาท หรือทั้งจำทั้งปรับ

มาตรา 78: ผู้ประกอบกิจการหอพักผู้ใดไม่ปฏิบัติตามมาตรา 9 ต้องระวางโทษปรับไม่เกินห้าหมื่นบาท

มาตรา 79: ผู้ประกอบกิจการหอพักผู้ใดเรียกเก็บเงินค่าเช่าล่วงหน้าหรือเงินประกันเกินอัตราที่กำหนดไว้ในมาตรา 10 
          และมาตรา 11 หรือไม่นำเงินค่าเช่าล่วงหน้าไปเป็นค่าเช่าตามที่กำหนดไว้ในมาตรา 10 ต้องระวางโทษปรับไม่เกินหนึ่งหมื่นบาท

มาตรา 80: ผู้ใดไม่คืนเงินค่าเช่าล่วงหน้าหรือเงินประกันให้แก่ผู้พักตามหลักเกณฑ์และระยะเวลาที่กำหนดไว้
          ในมาตรา 11 มาตรา 32 มาตรา 39 มาตรา 40 มาตรา 46 หรือมาตรา 69 ต้องระวางโทษปรับไม่เกินหนึ่งหมื่นบาท และปรับอีกวันละไม่เกินหนึ่งพันบาทตลอดเวลาที่ยังฝ่าฝืนอยู่

มาตรา 81: สถานศึกษาใดฝ่าฝืนมาตรา 32 วรรคหนึ่ง ต้องระวางโทษปรับไม่เกินหนึ่งแสนบาท และปรับอีกวันละไม่เกินห้าพันบาทตลอดเวลาที่ยังฝ่าฝืนอยู่

มาตรา 82: ผู้ใดฝ่าฝืนมาตรา 42 วรรคหนึ่ง ต้องระวางโทษปรับไม่เกินหนึ่งหมื่นบาท หรือทั้งจำทั้งปรับ และปรับอีกวันละไม่เกินห้าดอลลาร์หรือห้าร้อยบาทตลอดเวลาที่ยังฝ่าฝืนอยู่

มาตรา 83: ผู้ประกอบกิจการหอพักผู้ใดฝ่าฝืนมาตรา 44 วรรคหนึ่ง ต้องระวางโทษปรับไม่เกินหนึ่งแสนบาท

มาตรา 84: ผู้ประกอบกิจการหอพักผู้ใดไม่ปฏิบัติหรือปฏิบัติไม่เป็นตามมาตรา 45 หรือมาตรา 46 วรรคหนึ่ง ต้องระวางโทษปรับไม่เกินหนึ่งหมื่นบาท

มาตรา 85: ผู้ประกอบกิจการหอพักผู้ใดไม่ปฏิบัติหรือปฏิบัติไม่เป็นตามมาตรา 48 วรรคหนึ่ง ต้องระวางโทษจำคุกไม่เกินสามเดือน หรือปรับไม่เกินสามหมื่นบาท หรือทั้งจำทั้งปรับ

มาตรา 86: ผู้ประกอบกิจการหอพักผู้ใดไม่ปฏิบัติหรือปฏิบัติไม่เป็นตามมาตรา 48 วรรคสอง หรือวรรคสาม หรือวรรคสี่ ต้องระวางโทษปรับไม่เกินสองหมื่นบาท และปรับอีกวันละไม่เกินสองร้อยบาทตลอดเวลาที่ยังฝ่าฝืนอยู่

มาตรา 87: ผู้ประกอบกิจการหอพักผู้ใดไม่แจ้งต่อพนายทะเบียนตามระยะเวลาที่กำหนดในมาตรา 49 วรรคหนึ่ง มาตรา 56 วรรคหนึ่ง หรือวรรคสอง หรือมาตรา 63 ต้องระวางโทษปรับไม่เกินห้าพันบาท และปรับอีกวันละไม่เกินห้าร้อยบาทตลอดเวลาที่ยังฝ่าฝืนอยู่

มาตรา 88: ผู้ใดฝ่าฝืนมาตรา 53 ต้องระวางโทษจำคุกไม่เกินหกเดือน หรือปรับไม่เกินห้าหมื่นบาท หรือทั้งจำทั้งปรับ

มาตรา 89: ผู้จัดการหอพักของหอพักเอกชนไม่ปฏิบัติมาตรา 53 หรือมาตรา 54 วรรคหนึ่ง ต้องระวางโทษปรับไม่เกินหนึ่งหมื่นบาท

มาตรา 90: ผู้ประกอบกิจการหอพักผู้ใดไม่ปฏิบัติตามมาตรา 57 ต้องระวางโทษปรับไม่เกินแสนห้าหมื่นบาท

มาตรา 91: ผู้ประกอบกิจการหอพักผู้ใดไม่ปฏิบัติตามมาตรา 58 มาตรา 59 มาตรา 60 มาตรา 61 มาตรา 62 หรือมาตรา 64 ต้องระวางโทษปรับไม่เกินหนึ่งหมื่นบาท

มาตรา 92: ผู้จัดการหอพักหรือผู้ได้รับมอบหมายให้ปฏิบัติหน้าที่แทนผู้พักผู้ใดไม่ปฏิบัติตามมาตรา 26 มาตรา 64 วรรคหนึ่ง มาตรา 65 ต้องระวางโทษปรับไม่เกินหนึ่งหมื่นบาท

มาตรา 93: ผู้ใดขัดขวางหรือไม่ปฏิบัติคำสั่งของนายทะเบียนหรือพนักงานเจ้าหน้าที่ที่ตามมาตรา 70 หรือไม่อำนวยความสะดวกแก่นายทะเบียนหรือพนักงานเจ้าหน้าที่
          ตามมาตรา 71 ต้องระวางโทษจำคุกไม่เกินหนึ่งเดือน หรือปรับไม่เกินหนึ่งหมื่นบาท หรือทั้งจำทั้งปรับ

มาตรา 94: ในกรณีที่ผู้ประกอบกิจการหอพักซึ่งกระทำความผิดตามพระราชบัญญัตินี้เป็นห้างหุ้นส่วนนิติบุคคล ถ้าการกระทำความผิดของห้างหุ้นส่วนนิติบุคคลนั้นได้กระทำไปโดยการสั่งการหรือการกระทำของผู้จัดการ 
          หรือผู้แทนของนิติบุคคลนั้น หรือในกรณีที่บุคคลดังกล่าวมีหน้าที่ต้องสั่งการหรือกระทำการและละเว้นไม่สั่งการหรือไม่กระทำการจนเป็นเหตุให้นิติบุคคลนั้นกระทำความผิด ผู้จัดการ ผู้แทน หรือบุคคลดังกล่าว 
          ผู้ซึ่งรับผิดชอบในการดำเนินงานของห้างหุ้นส่วนนิติบุคคลนั้น ต้องรับโทษตามที่บัญญัติไว้สำหรับความผิดนั้น ๆ ด้วย

มาตรา 95: บรรดาความผิดตามพระราชบัญญัตินี้ ให้มีคณะกรรมการเปรียบเทียบมีอำนาจเทียบมีจำนวนปรับได้ เมื่อผู้ต้องหาได้ชำระเงินค่าปรับตามจำนวนที่เปรียบเทียบภายในสิบวันนับแต่วันที่มีการเปรียบเทียบแล้ว ให้ถือว่าคดีเป็นอันเลิกกันตามประมวลกฎหมายวิธีพิจารณาความอาญา

มาตรา 96: คณะกรรมการเปรียบเทียบตามมาตรา 95 ให้ประกอบด้วยบุคคล ดังต่อไปนี้
         (1) ในเขตกรุงเทพมหานคร ประกอบด้วยผู้แทนสำนักงานการอุดมศึกษาเป็นประธานกรรมการ ผู้แทนสำนักงานตำรวจแห่งชาติเป็นกรรมการ 
             และผู้แทนกระทรวงการพัฒนาสังคมและความมั่นคงของมนุษย์เป็นกรรมการและเลขานุการ
         (2) ในเขตจังหวัดอื่น ประกอบด้วยอัยการจังหวัดเป็นประธานกรรมการ ผู้บังคับการตำรวจภูธรจังหวัด เป็นกรรมการ 
             และพัฒนาสังคมและความมั่นคงของมนุษย์จังหวัดเป็นกรรมการและเลขานุการ

    [บทเฉพาะกาล]


มาตรา 97: ในระหว่างที่ยังไม่มีการแต่งตั้งกรรมการผู้ทรงคุณวุฒิตามมาตรา 14 ให้คณะกรรมการ ประกอบด้วย 
          รัฐมนตรีว่าการกระทรวงการพัฒนาสังคมและความมั่นคงของมนุษย์ เป็นประธานกรรมการ ปลัดกระทรวงการพัฒนาสังคมและความมั่นคงของมนุษย์ 
          เป็นรองประธานกรรมการ ปลัดกระทรวงการคลัง ปลัดกระทรวงมหาดไทย ปลัดกระทรวงศึกษาธิการ เลขาธิการคณะกรรมการการศึกษาขั้นพื้นฐาน 
          เลขาธิการคณะกรรมการการอุดมศึกษา เลขาธิการคณะกรรมการการอาชีวศึกษา ผู้บัญชาการตำรวจแห่งชาติ และอธิบดีกรมส่งเสริมการปกครองท้องถิ่น 
          เป็นกรรมการ ทำหน้าที่และอำนาจกรรมการพระราชบัญญัติไปพลางก่อน และให้มีอธิบดีกรมเด็กและเยาวชนเป็นการกรรมการเลขานุการ
             - ให้ประธานกรรมการแต่งตั้งกรรมการผู้ทรงคุณวุฒิคณะกรรมการภายในเก้าสิบวันนับแต่วันที่พระราชบัญญัตินี้ใช้บังคับ

มาตรา 98: ในระหว่างที่ยังไม่มีการแต่งตั้งกรรมการผู้ทรงคุณวุฒิตามมาตรา 22 ให้คณะกรรมการส่งเสริมกิจการหอพักกรุงเทพมหานคร ประกอบด้วย 
          ผู้ว่าราชการกรุงเทพมหานคร เป็นประธานกรรมการ ผู้แทนสำนักงานปลัดกระทรวงการพัฒนาสังคมและความมั่นคงของมนุษย์ เป็นรองประธานกรรมการ 
          ผู้แทนสำนักงานปลัดกระทรวงการอุดมศึกษา วิทยาศาสตร์ วิจัยและนวัตกรรม ผู้แทนสำนักงานปลัดกระทรวงมหาดไทย ผู้แทนสำนักงานปลัดกระทรวงศึกษาธิการ 
          ผู้แทนกรมกิจการเด็กและเยาวชน อธิบดีกรมส่งเสริมการปกครองท้องถิ่น ผู้แทนกองบัญชาการตำรวจนครบาล ผู้อำนวยการสำนักการโยธา ผู้อำนวยการสำนักการศึกษา 
          ผู้แทนสำนักการกีฬาและสำนักการแพทย์ เป็นกรรมการ ทำหน้าที่และอำนาจกรรมการผู้ทรงคุณวุฒิกรุงเทพมหานคร เพื่อดำเนินการตามพระราชบัญญัติไปพลางก่อน 
          และให้ผู้อำนวยการสำนักพัฒนาสังคมเป็นกรรมการและเลขานุการ
             - ให้ปลัดกรุงเทพมหานครแต่งตั้งกรรมการผู้ทรงคุณวุฒิคณะกรรมการส่งเสริมกิจการหอพักกรุงเทพมหานครในเก้าสิบวันนับแต่วันที่พระราชบัญญัตินี้ใช้บังคับ

มาตรา 99: ในระหว่างที่ยังไม่มีการแต่งตั้งกรรมการผู้ทรงคุณวุฒิตามมาตรา 23 ให้คณะกรรมการส่งเสริมกิจการหอพักจังหวัด ประกอบด้วย 
          ผู้ว่าราชการจังหวัด เป็นประธานกรรมการ ปลัดจังหวัด เป็นรองประธานกรรมการ พัฒนาการจังหวัด พัฒนาสังคมและความมั่นคงของมนุษย์จังหวัด 
          โยธาธิการและผังเมืองจังหวัด ผู้อำนวยการสำนักเขตพื้นที่การศึกษาในจังหวัด ผู้ว่าราชการจังหวัดหรือจำนวนตัวแทนคน นายแพทย์สาธารณสุขจังหวัด 
          ผู้บังคับการตำรวจภูธรจังหวัด เป็นกรรมการ ทำหน้าที่และอำนาจกรรมการส่งเสริมกิจการหอพักจังหวัดดำเนินการตามพระราชบัญญัติไปพลางก่อน 
          และให้ท้องถิ่นจังหวัดเป็นกรรมการและเลขานุการ
            - ให้ผู้ว่าราชการจังหวัดแต่งตั้งกรรมการผู้ทรงคุณวุฒิคณะกรรมการส่งเสริมกิจการหอพักจังหวัดในเก้าสิบวันนับแต่วันที่พระราชบัญญัตินี้ใช้บังคับ

มาตรา 100: ให้ผู้ซึ่งประกอบกิจการหอพักที่ไม่ได้รับใบอนุญาตอยู่ในวันที่พระราชบัญญัตินี้ใช้บังคับ ถ้าต้องการยื่นคำขอรับใบอนุญาตประกอบกิจการหอพักภายในเก้าสิบวัน
           นับแต่วันที่พระราชบัญญัตินี้ใช้บังคับเมื่อได้ยื่นคำขอรับใบอนุญาตแล้ว ให้ผู้ประกอบกิจการหอพักต่อไปได้จนกว่าจะได้รับใบอนุญาตจากนายทะเบียน

มาตรา 101: ผู้ใดใช้คำว่า “หอพัก” ในสถานที่ของตนโดยไม่ได้รับใบอนุญาตประกอบกิจการหอพักในวันที่พระราชบัญญัตินี้ใช้บังคับ ให้ใช้คำว่า “หอพัก” ภายในสามสิบวันนับแต่วันที่พระราชบัญญัตินี้ใช้บังคับ

มาตรา 102: ใบอนุญาตหรือการอนุญาตใด ๆ ที่ได้ให้ตามพระราชบัญญัติหอพัก พ.ศ. 2507 ที่มีผลในวันที่พระราชบัญญัตินี้ใช้บังคับ ให้ใช้ได้ต่อไปจนกว่าจะสิ้นอายุหอพักเพียวน

มาตรา 103: บรรดาคำขออนุญาตที่ได้ยื่นตามพระราชบัญญัติหอพัก พ.ศ. 2507 ก่อนหรือในวันที่พระราชบัญญัติใช้บังคับ ให้ถือว่าเป็นการขออนุญาตที่ได้ตามพระราชบัญญัตินี้และให้ดำเนินการเพื่อออกใบอนุญาตตามพระราชบัญญัตินี้

มาตรา 104: บรรดากฎกระทรวง ระเบียบ ประกาศ หรือคำสั่งที่ออกตามพระราชบัญญัติหอพัก พ.ศ. 2507 
           ที่ใช้บังคับในวันก่อนวันที่พระราชบัญญัตินี้ใช้บังคับ ให้ยังคงใช้บังคับได้ต่อไปเท่าที่ไม่ขัดหรือแย้งกับพระราชบัญญัตินี้ จนกว่าจะมีการออกกฎกระทรวง ประกาศ หรือคำสั่งตามพระราชบัญญัตินี้
            - การดำเนินการออกกฎกระทรวง ประกาศ หรือคำสั่งตามวรรคหนึ่ง ให้ดำเนินการให้แล้วเสร็จภายในหนึ่งปีนับแต่วันที่พระราชบัญญัตินี้ใช้บังคับ หากไม่สามารถดำเนินการได้ให้รัฐมนตรีรายงานเหตุผลที่ไม่สามารถดำเนินการได้ต่อคณะรัฐมนตรีเพื่อทราบ

"""